import { Client, type ClientChannel } from "ssh2";

/**
 * READ-ONLY source auto-detection for the migration wizard.
 *
 * Given SSH credentials for a customer-specified SOURCE box, we open a single
 * password-authenticated SSH session and *look* at what is there — web roots,
 * home directories, database engines AND what is actually RUNNING (Docker
 * containers, listening ports, app processes and their working directories,
 * signature-bearing app dirs under /opt·/srv·/app, non-distro services) — so the
 * wizard can present a pre-checked "here's what we found" checklist instead of
 * making the customer type paths and DB names by hand. All of the running-app
 * discovery uses ONLY read-only probes: `docker ps`, `ss`/`netstat -lntp`, `ps`,
 * `readlink /proc/<pid>/cwd`, `du`, `[ -f ]`/`[ -d ]` tests and
 * `systemctl list-units` — no writes, installs or state changes, still fixed and
 * input-free (only constant shell globs the REMOTE shell expands), still capped
 * and timeout-bounded. Names/paths that come back are re-validated against the
 * same allowlists before any can be selected for transfer.
 *
 * SECURITY — the source is UNTRUSTED and customer-supplied, so this mirrors the
 * hardening in worker/migrate-real.ts:
 *
 *   1. The scan is strictly READ-ONLY. Every probe is a fixed, input-free shell
 *      script (directory globs are expanded by the REMOTE shell from constant
 *      patterns — no customer value is ever interpolated into it). We never
 *      write, install or modify anything on the source. Database listing reads
 *      its credentials file from `/dev/stdin`, so not even a temp file is
 *      written to the source.
 *
 *   2. SECRETS NEVER TOUCH A COMMAND STRING. The SSH password is handed to the
 *      ssh2 transport, never a shell. DB credentials are streamed into the far
 *      command's STDIN (a `[client]` defaults file / a `.pgpass` line consumed
 *      via `/dev/stdin`), never as an argv token.
 *
 *   3. STRICT ALLOWLIST VALIDATION. Host / port / SSH user / DB user are checked
 *      against shell-inert allowlists before use — we reject, never sanitize.
 *      Paths and DB names that come BACK from the source are re-validated against
 *      the same allowlist the real engine enforces; anything that doesn't match
 *      is dropped (it could not be migrated safely anyway).
 *
 *   4. Everything is timeout-bounded and size/count-capped.
 */

// ---- Result shapes (no secrets ever) --------------------------------------
export type WebAppType = "wordpress" | "laravel" | "django" | "node" | "php" | "unknown";

export type DetectedWebRoot = { path: string; sizeLabel: string; appType: WebAppType };
export type DetectedHome = { path: string; sizeLabel: string };
export type DetectedDatabase = { engine: "mysql" | "postgres"; name: string; sizeLabel: string };
export type DetectedEngine = {
  engine: "mysql" | "postgres";
  present: boolean;
  listening: boolean;
  listed: boolean; // did we successfully enumerate databases with the given creds?
};

/**
 * Exact DB engine variant + version detected on the SOURCE, so the migration can
 * install the SAME engine on the target for a clean, same-engine restore.
 *   - engine  : "mysql" (the MySQL/MariaDB family) or "postgres".
 *   - variant : "mysql" = Oracle MySQL, "mariadb" = MariaDB, null = couldn't tell
 *               (or N/A for postgres).
 *   - version : detected major(.minor), e.g. "8.0" (MySQL), "10.11" (MariaDB),
 *               "15" (PostgreSQL); null when unreadable.
 * All fields are parsed from constant, read-only `--version` probes and are
 * shell-inert display/decision values — never fed back into a command.
 */
export type DbEngineDetail = {
  engine: "mysql" | "postgres";
  variant: "mysql" | "mariadb" | null;
  version: string | null;
};

// The runtime that pointed us at a candidate app directory (or "unknown" when a
// directory scan found app signatures without a matching running process).
export type AppRuntime =
  | "node"
  | "python"
  | "java"
  | "ruby"
  | "php-fpm"
  | "pm2"
  | "next"
  | "dotnet"
  | "unknown";
// The on-disk signature that marks a directory as an app worth migrating.
export type AppDirSignature =
  | "wordpress"
  | "laravel"
  | "django"
  | "node"
  | "php"
  | "compose"
  | "python"
  | "git-repo"
  | "unknown";

/** A candidate app directory discovered OUTSIDE the standard web roots — either a
 *  running process's cwd (#3) or a signature-bearing dir under /opt, /srv, /app… (#4). */
export type DetectedAppDir = {
  path: string;
  sizeLabel: string;
  runtime: AppRuntime;
  signature: AppDirSignature;
};
/** A running Docker container. `mounts` are the bind-mount host paths (the data to
 *  migrate); named volumes appear here too but are not absolute paths. */
export type DetectedContainer = {
  name: string;
  image: string;
  ports: string;
  mounts: string[];
};
/** A listening TCP socket + owning process, with a friendly role guess. Informational. */
export type DetectedPort = { port: number; proc: string; role: string };
/** A running non-distro systemd service — name only, as a hint. Informational. */
export type DetectedService = { name: string };

export type ScanResult = {
  ok: boolean;
  webRoots: DetectedWebRoot[];
  homes: DetectedHome[];
  databases: DetectedDatabase[];
  engines: DetectedEngine[];
  // Exact engine variant + version per present DB engine (read-only `--version`
  // probes). Drives installing the MATCHING engine on the target so DB restores
  // are same-engine with no caveats.
  dbEngines?: DbEngineDetail[];
  // Running-app discovery (all read-only, informational except appDirs which are
  // migratable paths that get merged into the copy list, deduped against webRoots/homes).
  appDirs: DetectedAppDir[];
  containers: DetectedContainer[];
  ports: DetectedPort[];
  services: DetectedService[];
  notes: string[];
  // Read-only DB data-dir size estimate (bytes) — sum of the detected engines'
  // on-disk data dirs (/var/lib/mysql, /var/lib/postgresql). Lets the DB portion
  // count toward the migration total even though databases carry no per-DB size
  // unless the customer supplied DB creds. 0 when nothing detected / unreadable.
  dbSizeBytes?: number;
  // OS / CPU-architecture of the SOURCE, for the compatibility guardrail. Parsed
  // from /etc/os-release (NEVER sourced) + `uname -m`; display-only, re-validated.
  sourceOs?: { id: string; versionId: string; pretty: string } | null;
  sourceArch?: string | null;
  synthetic?: boolean;
};

export type DetectInput = {
  host: string;
  port: number;
  user: string;
  password: string;
  /** Optional DB admin creds — only then can we enumerate database names/sizes. */
  dbUser?: string;
  dbPassword?: string;
};

// ---- Timeouts / caps ------------------------------------------------------
const CONNECT_TIMEOUT_MS = 20_000;
const SCAN_TIMEOUT_MS = 75_000; // the big du/probe sweep
const DB_TIMEOUT_MS = 25_000;
const MAX_WEB_ROOTS = 40;
const MAX_HOMES = 40;
const MAX_DATABASES = 60;
const MAX_APP_DIRS = 40;
const MAX_CONTAINERS = 30;
const MAX_PORTS = 60;
const MAX_SERVICES = 30;

// ---- Strict allowlist validators (mirror worker/migrate-real.ts) ----------
const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
const DBUSER_RE = /^[A-Za-z0-9_]{1,64}$/;
const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/;
// MUST match IDENT_RE in worker/migrate-real.ts — only surface DB names the real
// transfer engine can actually migrate, so nothing selected here fails later.
const DBNAME_RE = /^[A-Za-z0-9_]{1,64}$/;
// Informational identifiers that come BACK from the source. These are never used
// in a shell or selected for transfer — only rendered as text — but we still keep
// them shell-inert and bounded so nothing weird flows through.
const CONTNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
const SVCNAME_RE = /^[A-Za-z0-9@][A-Za-z0-9@._-]{0,127}$/;

/** Strip control chars, trim and bound the length of any free text from the source. */
function cleanText(s: string, max: number): string {
  // eslint-disable-next-line no-control-regex
  return (s ?? "").replace(/[\x00-\x1f\x7f]/g, "").trim().slice(0, max);
}

// Well-known listening ports → a friendly role label for the "what's running" summary.
const PORT_ROLES: Record<number, string> = {
  21: "ftp",
  22: "ssh",
  25: "mail",
  80: "web",
  110: "mail",
  143: "mail",
  443: "web",
  465: "mail",
  587: "mail",
  993: "mail",
  3000: "app",
  3306: "mysql",
  4000: "app",
  5000: "app",
  5432: "postgres",
  5433: "postgres",
  5672: "rabbitmq",
  6379: "redis",
  8000: "app",
  8080: "app",
  8443: "web",
  9000: "app",
  9200: "elasticsearch",
  11211: "memcached",
  27017: "mongo",
};
function mapPortRole(p: number): string {
  return PORT_ROLES[p] ?? "other";
}
function mapRuntime(s: string): AppRuntime {
  switch (s) {
    case "node":
      return "node";
    case "python":
      return "python";
    case "java":
      return "java";
    case "ruby":
      return "ruby";
    case "phpfpm":
      return "php-fpm";
    case "pm2":
      return "pm2";
    case "next":
      return "next";
    case "dotnet":
      return "dotnet";
    default:
      return "unknown";
  }
}
function mapSignature(s: string): AppDirSignature {
  if (s === "gitrepo") return "git-repo";
  return (["wordpress", "laravel", "django", "node", "php", "compose", "python"] as AppDirSignature[]).includes(
    s as AppDirSignature
  )
    ? (s as AppDirSignature)
    : "unknown";
}

function assert(cond: unknown, msg: string): asserts cond {
  if (!cond) throw new Error(msg);
}
function validHost(h: string): boolean {
  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
}
function validPath(p: string): boolean {
  return typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
}

/** Collapse duplicate slashes and strip a trailing slash from a du-emitted path. */
function normalizeRemotePath(p: string): string {
  const collapsed = (p ?? "").replace(/\/{2,}/g, "/").replace(/\/+$/, "");
  return collapsed || "/";
}

// ---- SSH plumbing (same shape as migrate-real.ts) -------------------------
function execRemote(
  conn: Client,
  cmd: string,
  timeoutMs: number
): Promise<{ code: number; stdout: string; stderr: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      const timer = setTimeout(() => {
        try {
          stream.close();
        } catch {
          /* ignore */
        }
        reject(new Error("remote command timed out"));
      }, timeoutMs);
      stream
        .on("close", (code: number) => {
          clearTimeout(timer);
          resolve({ code: code ?? 0, stdout, stderr });
        })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
    });
  });
}

/** Run a command, streaming `input` into its STDIN (secret goes here, never argv). */
function execRemoteInput(
  conn: Client,
  cmd: string,
  input: string,
  timeoutMs: number
): Promise<{ code: number; stdout: string; stderr: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      const timer = setTimeout(() => {
        try {
          stream.close();
        } catch {
          /* ignore */
        }
        reject(new Error("remote command timed out"));
      }, timeoutMs);
      stream
        .on("close", (code: number) => {
          clearTimeout(timer);
          resolve({ code: code ?? 0, stdout, stderr });
        })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
      stream.end(input);
    });
  });
}

import { Client, type ClientChannel, type SFTPWrapper } from "ssh2";
import { connectionTarget, serverRootPassword } from "../lib/sftp";
import { decryptSecret } from "../lib/crypto-box";

/**
 * SECURE real cross-provider LIFT-AND-SHIFT migration engine (gated behind
 * ENABLE_REAL_MIGRATION).
 *
 * This automates a whole-server move: it copies the selected apps/web roots/home
 * dirs/Docker data to the SAME absolute paths on the new Nxeon server, dumps and
 * imports the databases WITHOUT ever asking the customer for a DB password (we
 * have root SSH into the source, so we dump via root's LOCAL socket/peer auth),
 * installs the prerequisites the source needs (Docker + compose, DB engines, web
 * servers, runtimes) from a FIXED package allowlist, brings Docker Compose
 * projects up, best-effort enables services + web vhosts, then VERIFIES what is
 * actually running. The final summary honestly separates "migrated & running"
 * (verified) from "copied — needs a manual step".
 *
 * The security bar from the original transfer engine is UNCHANGED and extended:
 *
 *   1. STRICT ALLOWLIST VALIDATION. Every non-secret value that is interpolated
 *      into a command — source host/port/user, file paths, DB engine names,
 *      Docker volume/compose-dir names, systemd service names, listening ports —
 *      must match a shell-inert allowlist regex or it is REJECTED (never
 *      sanitized). The permitted charsets contain no shell metacharacters, so an
 *      interpolated value cannot break out of the command. Anything that came
 *      BACK from the untrusted source scan is re-validated here before use.
 *
 *   2. FIXED PACKAGE ALLOWLIST. Package installs on the target only ever use
 *      compile-time-constant package strings from PKG_* below — never a string
 *      supplied by the source.
 *
 *   3. SECRETS NEVER TOUCH A COMMAND STRING. The source SSH password is written
 *      to a 0600 file over SFTP (bytes, not an argv token) and consumed with
 *      `sshpass -f`. Database dumps use root's LOCAL auth on each side (unix
 *      socket / peer), so NO database password exists to leak. DB contents are
 *      streamed to dump files and never echoed to logs.
 *
 *   4. Everything is confined to a per-migration work dir for transient state
 *      (pass file, known_hosts, DB dumps), bounded by timeouts, and the SSH
 *      password file is scrubbed in a `finally` block regardless of outcome.
 *
 * Best-effort steps (DB dump/import, prerequisite installs, compose up, service
 * enable, vhost copy) LOG their failure reason and continue — a single failed
 * sub-step must not fail the whole migration. Only a fatal setup error throws.
 */

type ReportFn = (progress: number, step: string, line: string) => Promise<void>;

type MigrationRow = {
  id: string;
  sourceHost: string;
  sourcePort: number;
  sourceUser: string;
  sourcePasswordEnc: string | null;
};

type TargetServer = {
  id: string;
  rootPassword: string | null;
  rootPasswordEnc?: string | null;
  sshPort: number | null;
  dedicatedIp?: { address: string } | null;
};

// The secret-free detection snapshot stored under Migration.items.scan. Used here
// only to log standalone containers and derive fallbacks; every field is
// re-validated before it can flow into a command.
export type ScanSnapshot = {
  engines?: { engine?: string; present?: boolean }[];
  // Exact engine variant + version detected on the source (read-only). Chooses the
  // MATCHING engine package on the target; the variant is a validated enum, never
  // interpolated into a command.
  dbEngines?: { engine?: string; variant?: string | null; version?: string | null }[];
  containers?: { name?: string; image?: string; ports?: string; mounts?: string[] }[];
  ports?: { port?: number; proc?: string; role?: string }[];
  services?: { name?: string }[];
  appDirs?: { path?: string; runtime?: string; signature?: string }[];
};

type Items = {
  paths?: string[];
  // Legacy per-DB list (with encrypted password) — no longer used for dumping;
  // kept optional so old rows still type-check. Passwordless dumping uses dbEngines.
  databases?: { engine: string; name: string; user: string; passEnc?: string }[];
  dbEngines?: string[]; // which engines to dump via source root LOCAL auth
  dockerVolumes?: string[]; // named docker volumes to copy (/var/lib/docker/volumes/<n>/_data)
  composeDirs?: string[]; // compose project dirs → `docker compose up -d`
  verifyPorts?: number[]; // ports that should be listening on the target after bring-up
  hasContainers?: boolean; // Docker containers detected → install Docker Engine + compose
  webServers?: string[]; // "nginx" | "apache" to install + enable vhosts for
  runtimes?: string[]; // "nodejs" | "python3" to install
  totalBytes?: number; // trusted server-side total to migrate (bytes) for the pre-flight
  scan?: ScanSnapshot;
};

// A single line item in the honest final summary.
export type MigrationStepResult = {
  step: string;
  // running  = verified running on the target
  // copied   = placed on the target but NOT verified running (may need a manual step)
  // failed   = attempted, failed (reason in detail) — did NOT fail the migration
  // skipped  = nothing to do
  status: "running" | "copied" | "failed" | "skipped";
  detail: string;
};

export type RealMigrationSummary = {
  results: MigrationStepResult[];
  verifiedRunning: string[];
  needsAttention: string[];
};

export type RealMigrationInput = {
  migration: MigrationRow;
  target: TargetServer | null;
  items: Items;
  report: ReportFn;
};

// ---- Timeouts -------------------------------------------------------------
const CONNECT_TIMEOUT_MS = 20_000;
const SETUP_TIMEOUT_MS = 60_000; // small writes, checks
const INSTALL_TIMEOUT_MS = 10 * 60_000; // package installs (apt/dnf can be slow)
const TRANSFER_TIMEOUT_MS = Number(process.env.MIGRATE_EXEC_TIMEOUT_MS ?? 45 * 60_000); // rsync/dump/import
const GiB = 1024 ** 3;

// ---- Strict allowlist validators (throw/reject on any violation) ----------
// Charsets below are deliberately shell-inert: no quotes, spaces, metachars or
// newlines. Validated values are therefore safe to interpolate into a command.
const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/; // absolute path, safe charset
// Docker volume name (docker's own charset) and systemd unit name — shell-inert.
const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
const SVCNAME_RE = /^[A-Za-z0-9@][A-Za-z0-9@._-]{0,127}$/;
// Database identifier (schema name) — shell-inert (no metachars, quotes or spaces).
// MUST match DBNAME_RE in worker/migrate-detect.ts. Every DB name returned by the
// source's `SHOW DATABASES` is validated against this (reject, never sanitize)
// before it is interpolated into a mysqldump command.
const IDENT_RE = /^[A-Za-z0-9_]{1,64}$/;

// Top-level system locations we refuse to overwrite on the target even if a
// (validated) path points at one — a lift-and-shift must never clobber the new
// server's own OS. Docker volumes/state are handled by their dedicated steps.
const UNSAFE_PREFIXES = [
  "/bin", "/sbin", "/usr", "/lib", "/lib64", "/etc/systemd", "/proc", "/sys",
  "/dev", "/run", "/boot", "/var/lib/docker",
];
const UNSAFE_EXACT = new Set(["/", "/etc", "/var", "/var/lib", "/usr", "/home", "/root/.ssh"]);

function assert(cond: unknown, msg: string): asserts cond {
  if (!cond) throw new Error(msg);
}

function validHost(h: string): boolean {
  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
}

function validPath(p: string): boolean {
  return typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
}

/** A validated path we are willing to rsync directly onto the target's real fs. */
function safeCopyTarget(p: string): boolean {
  if (!validPath(p)) return false;
  if (UNSAFE_EXACT.has(p)) return false;
  for (const pre of UNSAFE_PREFIXES) if (p === pre || p.startsWith(pre + "/")) return false;
  return true;
}

/** dirname of a validated absolute path (both inputs/outputs are shell-inert). */
function parentDir(p: string): string {
  const i = p.lastIndexOf("/");
  return i <= 0 ? "/" : p.slice(0, i);
}

// ---- SSH plumbing ---------------------------------------------------------
function execRemote(
  conn: Client,
  cmd: string,
  timeoutMs: number
): Promise<{ code: number; stdout: string; stderr: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      const timer = setTimeout(() => {
        try {
          stream.close();
        } catch {
          /* ignore */
        }
        reject(new Error("remote command timed out"));
      }, timeoutMs);
      stream
        .on("close", (code: number) => {
          clearTimeout(timer);
          resolve({ code: code ?? 0, stdout, stderr });
        })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
    });
  });
}

/** Write bytes to a remote file over SFTP with a fixed 0600 mode (no shell). */
function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const ws = sftp.createWriteStream(path, { mode: 0o600 });
    ws.on("close", () => resolve());
    ws.on("error", (e: Error) => reject(e));
    ws.end(Buffer.from(content, "utf8"));
  });
}

function connectTarget(server: TargetServer): Promise<{ conn: Client; sftp: SFTPWrapper }> {
  return new Promise((resolve, reject) => {
    const target = connectionTarget(server as any);
    if (!target) return reject(new Error("target server is not reachable yet — connection details are pending"));
    const password = serverRootPassword(server);
    if (!password) return reject(new Error("target server has no root password on record"));
    const conn = new Client();
    conn.on("ready", () => {
      conn.sftp((err, sftp) => {
        if (err) return reject(err);
        resolve({ conn, sftp });
      });
    });
    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
    conn.connect({
      host: target.host,
      port: target.port,
      username: "root",
      password,
      readyTimeout: CONNECT_TIMEOUT_MS,
    });
  });
}

// ---- Prerequisite install (FIXED allowlist — never source-supplied) -------
// `mysql`        → MariaDB server (the MariaDB path, and the transparent fallback).
// `mysql_oracle` → Oracle MySQL server (installed when the source runs Oracle MySQL,
//                  so the restore is a clean same-engine import). Every package
//                  string below is a compile-time constant; the CHOICE between keys
//                  comes from a validated detected enum, never a source-supplied string.
type PkgKey = "docker" | "mysql" | "mysql_oracle" | "postgresql" | "nginx" | "apache" | "nodejs" | "python3";

// Command that succeeds iff the package's main binary is already present.
const PKG_CHECK: Record<PkgKey, string> = {
  docker: "command -v docker >/dev/null 2>&1",
  mysql: "command -v mysql >/dev/null 2>&1 || command -v mariadb >/dev/null 2>&1",
  mysql_oracle: "command -v mysqld >/dev/null 2>&1 || command -v mysql >/dev/null 2>&1",
  postgresql: "command -v psql >/dev/null 2>&1",
  nginx: "command -v nginx >/dev/null 2>&1",
  apache: "command -v apache2 >/dev/null 2>&1 || command -v httpd >/dev/null 2>&1",
  nodejs: "command -v node >/dev/null 2>&1",
  python3: "command -v python3 >/dev/null 2>&1",
};
// Debian/Ubuntu (apt) package strings — the primary target for Nxeon servers.
const PKG_APT: Record<PkgKey, string> = {
  docker: "docker.io docker-compose-plugin",
  mysql: "mariadb-server mariadb-client",
  mysql_oracle: "mysql-server mysql-client",
  postgresql: "postgresql",
  nginx: "nginx",
  apache: "apache2",
  nodejs: "nodejs npm",
  python3: "python3 python3-pip",
};
// RHEL/Fedora (dnf/yum) fallback package strings.
const PKG_DNF: Record<PkgKey, string> = {
  docker: "docker docker-compose-plugin",
  mysql: "mariadb-server mariadb",
  mysql_oracle: "mysql-server mysql",
  postgresql: "postgresql-server postgresql",
  nginx: "nginx",
  apache: "httpd",
  nodejs: "nodejs npm",
  python3: "python3 python3-pip",
};
// A friendly label for the log/summary.
const PKG_LABEL: Record<PkgKey, string> = {
  docker: "Docker Engine + compose",
  mysql: "MariaDB server",
  mysql_oracle: "MySQL server (Oracle)",
  postgresql: "PostgreSQL server",
  nginx: "nginx",
  apache: "Apache",
  nodejs: "Node.js",
  python3: "Python 3 + pip",
};

/**
 * Idempotently ensure each allowlisted package is present on the target. Runs
 * `apt-get update` once, then for each key: skip if the check passes, else try
 * apt → dnf → yum with the FIXED package string. Returns which were newly
 * installed / already present / failed. Never throws (best-effort per package).
 */
async function ensurePackages(
  conn: Client,
  keys: PkgKey[]
): Promise<{ key: PkgKey; ok: boolean; already: boolean; err?: string }[]> {
  const out: { key: PkgKey; ok: boolean; already: boolean; err?: string }[] = [];
  if (keys.length === 0) return out;
  // Refresh apt metadata once (best-effort; ignored on non-apt systems).
  await execRemote(conn, `apt-get update -y >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => {});
  for (const key of keys) {
    const already = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((r) => r.code === 0).catch(() => false);
    if (already) {
      out.push({ key, ok: true, already: true });
      continue;
    }
    // Docker is special-cased: install via the OFFICIAL convenience script — the
    // SAME method the platform's own provisioning uses (buildCloudInit in
    // worker/index.ts). The apt/dnf package list fails on Ubuntu because
    // `docker-compose-plugin` isn't in Ubuntu's default apt repo, so the whole
    // install returned non-zero and Docker never came up. get.docker.com adds
    // Docker's own repo and installs docker-ce + the compose plugin across
    // Debian/Ubuntu/RHEL. The command is a FIXED constant (no source input);
    // still best-effort + logged like every other package.
    const install =
      key === "docker"
        ? `curl -fsSL https://get.docker.com | sh && systemctl enable --now docker`
        : `DEBIAN_FRONTEND=noninteractive apt-get install -y ${PKG_APT[key]} ` +
          `|| dnf install -y ${PKG_DNF[key]} ` +
          `|| yum install -y ${PKG_DNF[key]}`;
    const r = await execRemote(conn, install, INSTALL_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
    const nowPresent = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
    if (nowPresent) {
      out.push({ key, ok: true, already: false });
    } else {
      const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
      out.push({ key, ok: false, already: false, err: tail || `install exit ${r.code}` });
    }
  }
  return out;
}

// ---- Plan derivation (prefer explicit items, re-validate everything) ------
function derivePlan(items: Items) {
  const scan = items.scan ?? {};

  // Engines to dump: explicit dbEngines, else engines the scan marked present.
  const engineSet = new Set<string>();
  for (const e of items.dbEngines ?? []) engineSet.add(e);
  if (engineSet.size === 0) for (const e of scan.engines ?? []) if (e?.present && e.engine) engineSet.add(e.engine);
  const dbEngines = [...engineSet].filter((e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres");

  // Which MySQL-family engine to install on the target, from the DETECTED variant:
  // Oracle MySQL → mysql-server (clean same-engine); MariaDB (or undeterminable) →
  // mariadb-server (the existing safe default). This is a validated enum, never a
  // source string; it only selects a fixed package-allowlist KEY.
  const mysqlDetail = (scan.dbEngines ?? []).find((d) => d?.engine === "mysql");
  const mysqlVariant: "mysql" | "mariadb" = mysqlDetail?.variant === "mysql" ? "mysql" : "mariadb";
  const mysqlVersion: string | null = mysqlDetail?.version ?? null;
  const pgDetail = (scan.dbEngines ?? []).find((d) => d?.engine === "postgres");
  const pgVersion: string | null = pgDetail?.version ?? null;

  const dockerVolumes = [...new Set(items.dockerVolumes ?? [])].filter((v) => VOLNAME_RE.test(v)).slice(0, 60);
  const composeDirs = [...new Set(items.composeDirs ?? [])].filter((p) => validPath(p)).slice(0, 40);
  const verifyPorts = [...new Set((items.verifyPorts ?? []).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22))].slice(0, 60);
  const hasContainers = !!items.hasContainers || (scan.containers?.length ?? 0) > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
  const webServers = [...new Set(items.webServers ?? [])].filter((w): w is "nginx" | "apache" => w === "nginx" || w === "apache");
  const runtimes = [...new Set(items.runtimes ?? [])].filter((r): r is "nodejs" | "python3" => r === "nodejs" || r === "python3");
  const services = [...new Set((scan.services ?? []).map((s) => s?.name ?? "").filter((n) => SVCNAME_RE.test(n)))].slice(0, 30);
  const containers = (scan.containers ?? [])
    .map((c) => ({
      name: String(c?.name ?? ""),
      image: String(c?.image ?? ""),
      ports: String(c?.ports ?? ""),
      mounts: Array.isArray(c?.mounts) ? c!.mounts!.map((m) => String(m)) : [],
    }))
    .slice(0, 30);

  const prereqs: PkgKey[] = [];
  // Install the engine variant that MATCHES the source (Oracle MySQL vs MariaDB).
  if (dbEngines.includes("mysql")) prereqs.push(mysqlVariant === "mysql" ? "mysql_oracle" : "mysql");
  if (dbEngines.includes("postgres")) prereqs.push("postgresql");
  if (hasContainers) prereqs.push("docker");
  for (const w of webServers) prereqs.push(w === "nginx" ? "nginx" : "apache");
  for (const rt of runtimes) prereqs.push(rt);

  return { dbEngines, mysqlVariant, mysqlVersion, pgVersion, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes, services, containers, prereqs };
}

