function connectSource(input: DetectInput): Promise<Client> {
  return new Promise((resolve, reject) => {
    const conn = new Client();
    conn.on("ready", () => resolve(conn));
    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
    conn.connect({
      host: input.host,
      port: input.port,
      username: input.user,
      password: input.password,
      readyTimeout: CONNECT_TIMEOUT_MS,
      // Password-only: never offer a local key to the untrusted source host.
      tryKeyboard: false,
    });
  });
}

// ---- Helpers --------------------------------------------------------------
function humanBytes(n: number): string {
  if (!Number.isFinite(n) || n <= 0) return "0 B";
  const units = ["B", "KB", "MB", "GB", "TB"];
  let i = 0;
  let v = n;
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024;
    i++;
  }
  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`;
}

/**
 * The read-only probe script. Deliberately input-free: the only variable parts
 * are constant shell globs expanded by the REMOTE shell, so there is no
 * injection surface. POSIX-sh only (works under `sh` or `bash`).
 */
// NOTE: authored as a plain string (not a template literal) so shell `${...}`
// parameter expansions can never collide with JS `${}` interpolation. Any
// trailing/duplicate slashes in emitted paths are normalized in JS below.
const SCAN_SCRIPT = [
  "export LC_ALL=C",
  'if command -v timeout >/dev/null 2>&1; then TO="timeout 25"; else TO=""; fi',
  "emit_web() {",
  "  d=$1",
  '  [ -d "$d" ] || return 0',
  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1)',
  '  [ -n "$sz" ] || sz=\'?\'',
  "  t=unknown",
  '  if [ -f "$d/wp-config.php" ]; then t=wordpress',
  '  elif [ -f "$d/artisan" ]; then t=laravel',
  '  elif [ -f "$d/manage.py" ]; then t=django',
  '  elif [ -f "$d/package.json" ]; then t=node',
  '  elif [ -f "$d/composer.json" ]; then t=php',
  "  else",
  '    for f in "$d"/*.php; do [ -e "$f" ] && { t=php; break; }; done',
  "  fi",
  "  printf 'WEB\\t%s\\t%s\\t%s\\n' \"$t\" \"$sz\" \"$d\"",
  "}",
  // Emit a candidate app directory OUTSIDE the web roots (a process cwd or a
  // signature-bearing dir). $1=runtime hint, $2=dir. Read-only: du + [ -f ] tests
  // only. seen_cwd de-dups within a shell to avoid repeated du on the same dir.
  "seen_cwd=' '",
  "emit_appdir() {",
  "  rt=$1; d=$2",
  '  [ -d "$d" ] || return 0',
  '  case "$d" in /|/usr|/usr/*|/bin|/sbin|/lib|/lib/*|/lib64*|/etc|/etc/*|/proc*|/sys*|/dev*|/run*|/tmp|/tmp/*|/var/lib/docker*|/snap*) return 0;; esac',
  '  case "$seen_cwd" in *" $d "*) return 0;; esac',
  '  seen_cwd="$seen_cwd$d "',
  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1); [ -n "$sz" ] || sz=\'?\'',
  "  sig=unknown",
  '  if [ -f "$d/wp-config.php" ]; then sig=wordpress',
  '  elif [ -f "$d/artisan" ]; then sig=laravel',
  '  elif [ -f "$d/manage.py" ]; then sig=django',
  '  elif [ -f "$d/docker-compose.yml" ] || [ -f "$d/docker-compose.yaml" ] || [ -f "$d/compose.yml" ] || [ -f "$d/compose.yaml" ]; then sig=compose',
  '  elif [ -f "$d/requirements.txt" ]; then sig=python',
  '  elif [ -f "$d/package.json" ]; then sig=node',
  '  elif [ -f "$d/composer.json" ]; then sig=php',
  '  elif [ -d "$d/.git" ]; then sig=gitrepo',
  "  fi",
  "  printf 'APPDIR\\t%s\\t%s\\t%s\\t%s\\n' \"$rt\" \"$sig\" \"$sz\" \"$d\"",
  "}",
  'for d in /var/www/html /usr/share/nginx/html /var/www /srv/www; do emit_web "$d"; done',
  'for d in /var/www/*/ /srv/www/*/ /home/*/public_html; do emit_web "$d"; done',
  "for d in /home/*/; do",
  '  [ -d "$d" ] || continue',
  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1); [ -n "$sz" ] || sz=\'?\'',
  "  printf 'HOME\\t%s\\t%s\\n' \"$sz\" \"$d\"",
  "done",
  "if [ -d /root ]; then",
  "  sz=$($TO du -shx /root 2>/dev/null | cut -f1); [ -n \"$sz\" ] || sz='?'",
  "  printf 'HOME\\t%s\\t%s\\n' \"$sz\" /root",
  "fi",
  "mp=0; ml=0; pp=0; pl=0",
  "{ command -v mysqld >/dev/null 2>&1 || command -v mariadbd >/dev/null 2>&1 || command -v mysql >/dev/null 2>&1 || [ -d /var/lib/mysql ]; } && mp=1",
  "{ command -v pg_dump >/dev/null 2>&1 || command -v psql >/dev/null 2>&1 || [ -d /var/lib/postgresql ]; } && pp=1",
  "ports=$( (ss -H -lnt 2>/dev/null || netstat -lnt 2>/dev/null) )",
  "printf '%s\\n' \"$ports\" | grep -q ':3306[^0-9]' && ml=1",
  "printf '%s\\n' \"$ports\" | grep -q ':5432[^0-9]' && pl=1",
  "printf 'ENGINE\\tmysql\\t%s\\t%s\\n' \"$mp\" \"$ml\"",
  "printf 'ENGINE\\tpostgres\\t%s\\t%s\\n' \"$pp\" \"$pl\"",
  // ---- DB engine variant + version. Read-only: only the client's `--version`
  // banner (no DB connection). The banner says "MariaDB" for MariaDB; Oracle MySQL
  // omits it. Version parsing happens in JS. $TO-bounded, no interpolation. --
  'if [ "$mp" = 1 ]; then',
  "  mv=''",
  "  if command -v mariadb >/dev/null 2>&1; then mv=$($TO mariadb --version 2>/dev/null | head -n1)",
  "  elif command -v mysql >/dev/null 2>&1; then mv=$($TO mysql --version 2>/dev/null | head -n1)",
  "  elif command -v mariadbd >/dev/null 2>&1; then mv=$($TO mariadbd --version 2>/dev/null | head -n1)",
  "  elif command -v mysqld >/dev/null 2>&1; then mv=$($TO mysqld --version 2>/dev/null | head -n1)",
  "  fi",
  "  printf 'DBVER\\tmysql\\t%s\\n' \"$mv\"",
  "fi",
  'if [ "$pp" = 1 ]; then',
  "  pv=''",
  "  if command -v psql >/dev/null 2>&1; then pv=$($TO psql --version 2>/dev/null | head -n1)",
  "  elif command -v pg_config >/dev/null 2>&1; then pv=$($TO pg_config --version 2>/dev/null | head -n1)",
  "  fi",
  "  printf 'DBVER\\tpostgres\\t%s\\n' \"$pv\"",
  "fi",
  // ---- DB data-dir size estimate (bytes). Only probed when the engine is
  // present. Constant paths, read-only `du -sbx`, $TO-bounded — no injection. --
  'if [ "$mp" = 1 ] && [ -d /var/lib/mysql ]; then',
  "  mb=$($TO du -sbx /var/lib/mysql 2>/dev/null | cut -f1); [ -n \"$mb\" ] || mb=0",
  "  printf 'DBSIZE\\tmysql\\t%s\\n' \"$mb\"",
  "fi",
  'if [ "$pp" = 1 ] && [ -d /var/lib/postgresql ]; then',
  "  pb=$($TO du -sbx /var/lib/postgresql 2>/dev/null | cut -f1); [ -n \"$pb\" ] || pb=0",
  "  printf 'DBSIZE\\tpostgres\\t%s\\n' \"$pb\"",
  "fi",
  // ---- OS / CPU architecture (read-only). /etc/os-release is GREPPED, never
  // sourced (the source is untrusted — sourcing could execute code); values are
  // re-validated + bounded in JS. `uname -m` for the arch. --
  'arch=$(uname -m 2>/dev/null); [ -n "$arch" ] || arch=unknown',
  "printf 'ARCH\\t%s\\n' \"$arch\"",
  "if [ -r /etc/os-release ]; then",
  "  grep -E '^(ID|VERSION_ID|PRETTY_NAME)=' /etc/os-release 2>/dev/null | head -n 20 | while IFS= read -r orl; do",
  "    printf 'OSREL\\t%s\\n' \"$orl\"",
  "  done",
  "fi",
  // ---- Running Docker containers (name/image/ports/mounts). Read-only `docker ps`
  // only; wrapped in $TO so an unresponsive daemon can't hang the probe. Cap 30. --
  "if command -v docker >/dev/null 2>&1; then",
  "  $TO docker ps --no-trunc --format '{{.Names}}|{{.Image}}|{{.Ports}}|{{.Mounts}}' 2>/dev/null | head -n 30 | while IFS= read -r dl; do",
  "    [ -n \"$dl\" ] && printf 'DOCKER\\t%s\\n' \"$dl\"",
  "  done",
  "fi",
  // ---- Listening TCP sockets + owning process (ss, fallback netstat). Read-only. --
  "lp=$( ($TO ss -H -lntp 2>/dev/null || $TO netstat -lntp 2>/dev/null) )",
  "printf '%s\\n' \"$lp\" | head -n 200 | while IFS= read -r pl; do",
  "  [ -n \"$pl\" ] && printf 'PORT\\t%s\\n' \"$pl\"",
  "done",
  // ---- App processes → their working directory (candidate app dirs). Read-only:
  // ps + readlink /proc/<pid>/cwd only; emit_appdir does the du/signature test. --
  "if command -v ps >/dev/null 2>&1; then",
  "  ps -eo pid=,comm= 2>/dev/null | head -n 400 | while read -r ppid pcomm; do",
  '    rt=""',
  '    case "$pcomm" in',
  "      node|nodejs) rt=node;;",
  "      python|python3|gunicorn|uvicorn|celery) rt=python;;",
  "      java) rt=java;;",
  "      ruby|puma|unicorn) rt=ruby;;",
  "      php-fpm*|php) rt=phpfpm;;",
  "      PM2*|pm2*) rt=pm2;;",
  "      next*|next-server*) rt=next;;",
  "      dotnet) rt=dotnet;;",
  "    esac",
  '    [ -n "$rt" ] || continue',
  '    cwd=$(readlink "/proc/$ppid/cwd" 2>/dev/null)',
  '    [ -n "$cwd" ] || continue',
  '    emit_appdir "$rt" "$cwd"',
  "  done",
  "fi",
  // ---- Signature-bearing app dirs under /opt, /srv, /app, home subdirs. Read-only. --
  "acount=0",
  "for d in /opt/*/ /srv/*/ /app /app/*/ /home/*/*/; do",
  '  [ -d "$d" ] || continue',
  '  case "$d" in /srv/www|/srv/www/*) continue;; esac',
  '  if [ -f "$d/package.json" ] || [ -f "$d/composer.json" ] || [ -f "$d/requirements.txt" ] || [ -f "$d/manage.py" ] || [ -f "$d/docker-compose.yml" ] || [ -f "$d/docker-compose.yaml" ] || [ -f "$d/compose.yml" ] || [ -f "$d/compose.yaml" ] || [ -d "$d/.git" ]; then',
  '    emit_appdir scan "$d"',
  '    acount=$((acount+1)); [ "$acount" -ge 60 ] && break',
  "  fi",
  "done",
  // ---- Running non-distro systemd services, name only, as hints. Read-only. --
  "if command -v systemctl >/dev/null 2>&1; then",
  "  $TO systemctl list-units --type=service --state=running --no-legend --plain 2>/dev/null | head -n 150 | while read -r unit rest; do",
  '    case "$unit" in',
  "      systemd*|dbus*|cron*|crond*|ssh*|sshd*|rsyslog*|syslog*|networkd*|resolved*|getty*|user@*|polkit*|accounts-daemon*|snapd*|multipathd*|udisks*|apparmor*|unattended*|packagekit*|chrony*|ntp*|thermald*|irqbalance*|atd*|acpid*) continue;;",
  "    esac",
  '    u=${unit%.service}',
  '    [ -n "$u" ] && printf \'SVC\\t%s\\n\' "$u"',
  "  done",
  "fi",
].join("\n");

const SYSTEM_SCHEMAS = new Set(["information_schema", "performance_schema", "mysql", "sys"]);

/** Parse a `du -sh`-style size label ("1.2G", "340M", "512K", "1.2 GB") into bytes. */
export function parseSizeLabel(label: string): number {
  const m = /^([\d.]+)\s*([KMGT]?)/i.exec(label.trim());
  if (!m) return 0;
  const n = parseFloat(m[1]);
  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
  return n * (mult[m[2].toUpperCase()] ?? 1);
}

/**
 * Parse a MySQL/MariaDB client `--version` banner into a variant + major.minor.
 * MariaDB banners contain the literal "MariaDB" (e.g. "...Distrib 10.11.6-MariaDB");
 * Oracle MySQL banners look like "mysql  Ver 8.0.36 for Linux". Returns
 * {variant:null,version:null} when the banner is empty/unrecognised.
 */
export function parseMysqlVersion(raw: string): { variant: "mysql" | "mariadb" | null; version: string | null } {
  const s = cleanText(raw, 200);
  if (!s) return { variant: null, version: null };
  if (/mariadb/i.test(s)) {
    const m = /(\d+\.\d+)(?:\.\d+)?-MariaDB/i.exec(s) || /(\d+\.\d+)/.exec(s);
    return { variant: "mariadb", version: m ? m[1] : null };
  }
  const m = /Ver\s+(\d+\.\d+)/i.exec(s) || /(\d+\.\d+)/.exec(s);
  return { variant: "mysql", version: m ? m[1] : null };
}

/** Parse a `psql --version` / `pg_config --version` banner into a major version.
 *  PostgreSQL ≥ 10 uses a single-number major ("15"); 9.x keeps major.minor. */
export function parsePgVersion(raw: string): string | null {
  const s = cleanText(raw, 200);
  const m = /(\d+(?:\.\d+)?)/.exec(s);
  if (!m) return null;
  const major = parseInt(m[1], 10);
  return Number.isFinite(major) && major >= 10 ? String(major) : m[1];
}

// ---- Public entrypoint ----------------------------------------------------
/**
 * SSH into the source (read-only) and return a structured inventory. Throws only
 * on a fatal connection/auth failure; a source that is reachable but has (say) no
 * readable DB creds still returns a useful partial result with notes.
 */
export async function detectSource(input: DetectInput): Promise<ScanResult> {
  assert(validHost(input.host), "source host is not a valid hostname or IP address");
  assert(Number.isInteger(input.port) && input.port >= 1 && input.port <= 65535, "source SSH port is out of range");
  assert(USER_RE.test(input.user), "source SSH username contains unsupported characters");
  assert(input.password && input.password.length > 0, "source SSH password is required");

  const notes: string[] = [];
  const webRoots: DetectedWebRoot[] = [];
  const homes: DetectedHome[] = [];
  const databases: DetectedDatabase[] = [];
  const engines: DetectedEngine[] = [];
  const rawAppDirs: DetectedAppDir[] = [];
  const containers: DetectedContainer[] = [];
  const ports: DetectedPort[] = [];
  const services: DetectedService[] = [];
  const seenPort = new Set<string>();
  let dbSizeBytes = 0;
  let sourceArch: string | null = null;
  const osrel: { id?: string; versionId?: string; pretty?: string } = {};
  // Raw `--version` banners per engine, parsed after the scan loop.
  const dbVerRaw: Record<"mysql" | "postgres", string> = { mysql: "", postgres: "" };

  const conn = await connectSource(input);
  try {
    // ---- 1. Filesystem + engine probe (fixed, input-free, read-only) ------
    const scan = await execRemote(conn, SCAN_SCRIPT, SCAN_TIMEOUT_MS);
    const engineState: Record<"mysql" | "postgres", { present: boolean; listening: boolean }> = {
      mysql: { present: false, listening: false },
      postgres: { present: false, listening: false },
    };

    for (const raw of scan.stdout.split("\n")) {
      const line = raw.replace(/\r$/, "");
      if (!line) continue;
      const parts = line.split("\t");
      if (parts[0] === "WEB" && parts.length >= 4) {
        const appType = parts[1] as WebAppType;
        const sizeLabel = parts[2] || "?";
        const path = normalizeRemotePath(parts[3]);
        if (!validPath(path)) continue;
        if (webRoots.some((w) => w.path === path)) continue;
        webRoots.push({
          path,
          sizeLabel,
          appType: (["wordpress", "laravel", "django", "node", "php"] as WebAppType[]).includes(appType)
            ? appType
            : "unknown",
        });
      } else if (parts[0] === "HOME" && parts.length >= 3) {
        const sizeLabel = parts[1] || "?";
        const path = normalizeRemotePath(parts[2]);
        if (!validPath(path)) continue;
        if (homes.some((h) => h.path === path)) continue;
        homes.push({ path, sizeLabel });
      } else if (parts[0] === "ENGINE" && parts.length >= 4) {
        const eng = parts[1] === "postgres" ? "postgres" : "mysql";
        engineState[eng] = { present: parts[2] === "1", listening: parts[3] === "1" };
      } else if (parts[0] === "APPDIR" && parts.length >= 5) {
        const sizeLabel = parts[3] || "?";
        const path = normalizeRemotePath(parts[4]);
        if (!validPath(path)) continue; // candidate for TRANSFER — must pass the strict allowlist
        rawAppDirs.push({
          path,
          sizeLabel,
          runtime: mapRuntime(parts[1]),
          signature: mapSignature(parts[2]),
        });
      } else if (parts[0] === "DOCKER") {
        // Line body is "name|image|ports|mounts" (never contains a tab, so parts[1] holds it whole).
        if (containers.length >= MAX_CONTAINERS) continue;
        const seg = (parts.slice(1).join("\t")).split("|");
        const name = cleanText(seg[0] ?? "", 128);
        if (!CONTNAME_RE.test(name)) continue; // shell-inert display id
        if (containers.some((c) => c.name === name)) continue;
        const mounts = (seg[3] ?? "")
          .split(",")
          .map((m) => cleanText(m, 256))
          .filter((m) => m.length > 0)
          .slice(0, 12);
        containers.push({
          name,
          image: cleanText(seg[1] ?? "", 200),
          ports: cleanText(seg[2] ?? "", 200),
          mounts,
        });
      } else if (parts[0] === "PORT") {
        if (ports.length >= MAX_PORTS) continue;
        const body = parts.slice(1).join("\t").trim();
        const toks = body.split(/\s+/);
        if (toks.length < 4) continue;
        const local = toks[3]; // ss and netstat both put the local addr:port at index 3
        const pm = /:(\d{1,5})$/.exec(local);
        if (!pm) continue;
        const portNum = Number(pm[1]);
        if (!Number.isInteger(portNum) || portNum < 1 || portNum > 65535) continue;
        // Owning process: ss ⇒ users:(("name",…  ;  netstat ⇒ trailing "pid/name".
        let proc = "";
        const ssm = /users:\(\("([^"]+)"/.exec(body);
        if (ssm) proc = ssm[1];
        else {
          const nsm = /\s(\d+)\/([^\s]+)\s*$/.exec(body);
          if (nsm) proc = nsm[2];
        }
        proc = cleanText(proc, 64);
        const dedup = `${portNum}/${proc}`;
        if (seenPort.has(dedup)) continue;
        seenPort.add(dedup);
        ports.push({ port: portNum, proc, role: mapPortRole(portNum) });
      } else if (parts[0] === "DBVER" && parts.length >= 2) {
        const eng = parts[1] === "postgres" ? "postgres" : "mysql";
        dbVerRaw[eng] = parts.slice(2).join("\t"); // "" when the banner was empty
      } else if (parts[0] === "DBSIZE" && parts.length >= 3) {
        const n = Number(parts[2]);
        if (Number.isFinite(n) && n > 0) dbSizeBytes += n;
      } else if (parts[0] === "ARCH" && parts.length >= 2) {
        const a = cleanText(parts[1], 32);
        if (/^[A-Za-z0-9_-]{1,32}$/.test(a)) sourceArch = a;
      } else if (parts[0] === "OSREL" && parts.length >= 2) {
        // "ID=debian" / VERSION_ID="12" / PRETTY_NAME="Debian GNU/Linux 12".
        const body = parts.slice(1).join("\t");
        const eq = body.indexOf("=");
        if (eq > 0) {
          const key = body.slice(0, eq).trim();
          const val = cleanText(body.slice(eq + 1).trim().replace(/^["']|["']$/g, ""), 128);
          if (key === "ID") osrel.id = val.toLowerCase().slice(0, 32);
          else if (key === "VERSION_ID") osrel.versionId = val.slice(0, 32);
          else if (key === "PRETTY_NAME") osrel.pretty = val;
        }
      } else if (parts[0] === "SVC" && parts.length >= 2) {
        if (services.length >= MAX_SERVICES) continue;
        const name = cleanText(parts[1], 128);
        if (!SVCNAME_RE.test(name)) continue;

  // ---- 1. Validate EVERY non-secret input up front (fail closed) ----------
  const host = migration.sourceHost;
  const port = migration.sourcePort;
  const user = migration.sourceUser;
  assert(validHost(host), "source host is not a valid hostname or IP address");
  assert(Number.isInteger(port) && port >= 1 && port <= 65535, "source SSH port is out of range");
  assert(USER_RE.test(user), "source username contains unsupported characters");

  const rawPaths = (items.paths ?? []).map((p) => p.trim()).filter(Boolean);
  for (const p of rawPaths) assert(validPath(p), `unsupported file path: ${p}`);
  // Direct-to-real-path copy: refuse to overwrite the target's own OS locations.
  const paths = rawPaths.filter(safeCopyTarget);

  const plan = derivePlan(items);
  for (const p of plan.composeDirs) assert(safeCopyTarget(p), `unsupported compose dir: ${p}`);

  assert(paths.length || plan.dbEngines.length || plan.composeDirs.length || plan.dockerVolumes.length, "nothing selected to migrate");

  // Root-vs-sudo prefix for privileged commands ON THE SOURCE (constant strings).
  const priv = user === "root" ? "" : "sudo -n ";

  // ---- 2. Decrypt the ONE secret we still need (source SSH password) ------
  const sshPass = decryptSecret(migration.sourcePasswordEnc);
  assert(sshPass, "source SSH password is missing or could not be decrypted");

  // ---- 3. Connect to the TARGET (our own server) --------------------------
  await report(6, "Connecting…", "Connecting to your Nxeon server to prepare the lift-and-shift.");
  const { conn, sftp } = await connectTarget(target!);

  const work = `/root/nxeon-migrations/${migration.id}`;
  const passFile = `${work}/ssh.pass`;
  const knownHosts = `${work}/known_hosts`;
  const sshOpts =
    `-p ${port} -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile=${knownHosts} ` +
    `-o ConnectTimeout=25 -o PreferredAuthentications=password -o PubkeyAuthentication=no`;
  const srcSpec = `${user}@${host}`;
  // rsync pull from the source over the sshpass-driven ssh (used everywhere below).
  const rsyncPull = (remotePath: string, localParent: string) =>
    `sshpass -f ${passFile} rsync -az --numeric-ids --timeout=1200 -e 'ssh ${sshOpts}' ${srcSpec}:${remotePath} ${localParent}/`;
  // Run a fixed command ON THE SOURCE and capture its output on the target.
  const onSource = (cmd: string) => `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} '${cmd}'`;

  const results: MigrationStepResult[] = [];
  const verifiedRunning: string[] = [];
  const needsAttention: string[] = [];
  const push = (r: MigrationStepResult) => {
    results.push(r);
    if (r.status === "running") verifiedRunning.push(r.step);
    else if (r.status === "copied" || r.status === "failed") needsAttention.push(`${r.step} — ${r.detail}`);
  };

  try {
    // ---- 4. Prepare the target: transfer tools + work dir + secret file ----
    await report(10, "Preparing…", "Ensuring transfer tools (rsync, sshpass) are present on the target.");
    await execRemote(
      conn,
      `command -v rsync >/dev/null 2>&1 && command -v sshpass >/dev/null 2>&1 || ` +
        `{ (apt-get update -y && apt-get install -y rsync sshpass) || (dnf install -y rsync sshpass) || (yum install -y rsync sshpass); }`,
      INSTALL_TIMEOUT_MS
    );
    const tools = await execRemote(conn, `command -v rsync && command -v sshpass`, SETUP_TIMEOUT_MS);
    assert(tools.code === 0, "could not install rsync/sshpass on the target server");

    await execRemote(
      conn,
      `mkdir -p ${work}/dumps && chmod 700 ${work} && touch ${knownHosts} && chmod 600 ${knownHosts}`,
      SETUP_TIMEOUT_MS
    );
    // Write the source SSH password to a 0600 file over SFTP (never a shell arg).
    await sftpWrite(sftp, passFile, sshPass);

    // ---- 4b. STORAGE PRE-FLIGHT (defense in depth) ------------------------
    // Re-read the target's free disk right now and compare it to the planned
    // total. Abort early (before installing/copying anything) if it won't fit, so
    // we never fill the destination's disk. A probe we can't read is NOT a block
    // (matches the wizard's soft-warning behaviour) — we only stop when we can
    // positively confirm the data won't fit. This throw routes through the normal
    // migration-failure path (Migration → FAILED); it never marks the VM ERROR.
    const plannedBytes = Math.max(0, Number(items.totalBytes ?? 0));
    if (plannedBytes > 0) {
      await report(12, "Checking free space…", "Confirming the new server has room for everything selected.");
      const df = await execRemote(conn, `df -B1 --output=avail / 2>/dev/null | tail -n1`, SETUP_TIMEOUT_MS).catch(
        () => ({ code: 1, stdout: "", stderr: "" })
      );
      const avail = Number((df.stdout || "").trim().split("\n").pop()?.trim());
      if (Number.isFinite(avail) && avail > 0 && plannedBytes > avail) {
        const needGb = (plannedBytes / GiB).toFixed(1);
        const haveGb = (avail / GiB).toFixed(1);
        throw new Error(
          `Not enough free disk on the destination (need ${needGb} GB, have ${haveGb} GB) — add storage and retry.`
        );
      }
    }

    // ---- 5. Install prerequisites on the target (fixed allowlist) ---------
    if (plan.prereqs.length) {
      await report(16, "Installing prerequisites…", `Preparing the target: ${plan.prereqs.map((k) => PKG_LABEL[k]).join(", ")}.`);
      // Log which DB engine variant we're matching from the source.
      if (plan.dbEngines.includes("mysql")) {
        const want =
          plan.mysqlVariant === "mysql"
            ? `MySQL${plan.mysqlVersion ? ` ${plan.mysqlVersion.split(".")[0]}` : ""}`
            : `MariaDB${plan.mysqlVersion ? ` ${plan.mysqlVersion}` : ""}`;
        await report(17, "Installing prerequisites…", `  Matching the source database engine: installing ${want} on the new server.`);
      }
      let installed = await ensurePackages(conn, plan.prereqs);

      // Transparent fallback: if the source ran Oracle MySQL but mysql-server can't
      // be installed on THIS target distro, degrade to MariaDB and record it honestly.
      // The swapped-in install result (key "mysql", label "MariaDB server") makes the
      // fallback visible in the summary rather than silently pretending it's MySQL.
      const oracle = installed.find((r) => r.key === "mysql_oracle");
      if (oracle && !oracle.ok) {
        await report(
          17,
          "Installing prerequisites…",
          "  MySQL server isn't installable on this OS — falling back to MariaDB (your MySQL dump still imports; minor tweaks possible)."
        );
        const fb = await ensurePackages(conn, ["mysql"]);
        installed = installed.filter((r) => r.key !== "mysql_oracle");
        installed.push(fb[0]);
      }

      for (const r of installed) {
        if (r.ok) {
          push({ step: `Install ${PKG_LABEL[r.key]}`, status: "running", detail: r.already ? "already present" : "installed" });
          await report(18, "Installing prerequisites…", `  ${PKG_LABEL[r.key]}: ${r.already ? "already present" : "installed"}.`);
        } else {
          push({ step: `Install ${PKG_LABEL[r.key]}`, status: "failed", detail: r.err ?? "install failed" });
          await report(18, "Installing prerequisites…", `  ${PKG_LABEL[r.key]}: could not install — ${r.err ?? "unknown error"}.`);
        }
      }
      // Make sure DB engines + docker daemon are actually up before we use them.
      if (plan.dbEngines.includes("mysql"))
        await execRemote(conn, `systemctl enable --now mariadb 2>/dev/null || systemctl enable --now mysql 2>/dev/null || service mysql start 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
      if (plan.dbEngines.includes("postgres"))
        await execRemote(conn, `systemctl enable --now postgresql 2>/dev/null || service postgresql start 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
      if (plan.hasContainers)
        await execRemote(conn, `systemctl enable --now docker 2>/dev/null || service docker start 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
    }

    // ---- 6. Files: rsync each selected path to the SAME path on target ----
    if (paths.length) {
      await report(28, "Copying files…", `Copying ${paths.length} path(s) from ${srcSpec} to the same locations on the new server.`);
      let idx = 0;
      let copied = 0;
      for (const p of paths) {
        idx++;
        const destParent = parentDir(p);
        await execRemote(conn, `mkdir -p ${destParent}`, SETUP_TIMEOUT_MS);
        const pct = 28 + Math.round((idx / paths.length) * 22); // 28 → 50
        await report(pct, "Copying files…", `  rsync ${p} → ${p}`);
        const r = await execRemote(conn, rsyncPull(p, destParent), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        if (r.code === 0) {
          copied++;
        } else {
          const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
          push({ step: `Copy ${p}`, status: "failed", detail: tail || `rsync exit ${r.code}` });
          await report(pct, "Copying files…", `  copy failed for ${p}: ${tail || `rsync exit ${r.code}`}`);
        }
      }
      if (copied) push({ step: `Copy ${copied} folder(s) to their original paths`, status: "copied", detail: "files placed at the same paths on the new server" });
    }

    // ---- 7. Named Docker volume data --------------------------------------
    if (plan.dockerVolumes.length) {
      await report(52, "Copying container data…", `Copying ${plan.dockerVolumes.length} named Docker volume(s).`);
      let ok = 0;
      for (const v of plan.dockerVolumes) {
        // Create the volume (idempotent), then rsync its _data into place.
        await execRemote(conn, `docker volume create ${v} >/dev/null 2>&1 || true`, SETUP_TIMEOUT_MS).catch(() => {});
        const dataDir = `/var/lib/docker/volumes/${v}/_data`;
        await execRemote(conn, `mkdir -p ${dataDir}`, SETUP_TIMEOUT_MS).catch(() => {});
        const r = await execRemote(conn, rsyncPull(`${dataDir}`, `/var/lib/docker/volumes/${v}`), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        if (r.code === 0) ok++;
        else {
          const tail = (r.stderr || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
          push({ step: `Copy volume ${v}`, status: "failed", detail: tail || `rsync exit ${r.code}` });
        }
      }
      if (ok) push({ step: `Copy ${ok} Docker volume(s)`, status: "copied", detail: "volume data restored under /var/lib/docker/volumes" });
    }

    // ---- 8. Databases: dump via source root LOCAL auth, import on target ---
    for (const engine of plan.dbEngines) {
      await report(60, "Migrating databases…", `Dumping ${engine === "postgres" ? "PostgreSQL" : "MySQL/MariaDB"} from the source (root, no password).`);
      if (engine === "mysql") {
        const dump = `${work}/dumps/mysql-all.sql`;
        // Dump ONLY the source's USER databases. `--all-databases` includes MySQL's
        // internal system schemas (mysql, information_schema, performance_schema,
        // sys); restoring the source's `mysql` schema into a different-version engine
        // corrupts/aborts the import (ERROR 1728 "Cannot load from mysql.proc").
        // So: enumerate databases over root's LOCAL socket auth (no password), drop
        // the system schemas, and dump the rest by name.
        const listCmd = `${priv}mysql -N -e "SHOW DATABASES"`;
        const listed = await execRemote(conn, onSource(listCmd), SETUP_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        const SYSTEM_SCHEMAS = new Set(["mysql", "information_schema", "performance_schema", "sys"]);
        const userDbs: string[] = [];
        for (const raw of (listed.stdout || "").split("\n")) {
          const name = raw.trim();
          if (!name || SYSTEM_SCHEMAS.has(name.toLowerCase())) continue;
          // Reject (never sanitize) any name that isn't a shell-inert identifier
          // before it is interpolated into the dump command.
          if (!IDENT_RE.test(name)) continue;
          userDbs.push(name);
        }
        const dbList = [...new Set(userDbs)];
        if (dbList.length === 0) {
          if (listed.code !== 0) {
            push({ step: "Migrate MySQL/MariaDB", status: "failed", detail: "root could not enumerate databases via local socket — import skipped" });
            await report(62, "Migrating databases…", `  Could not list MySQL databases on the source — skipping.`);
          } else {
            push({ step: "Migrate MySQL/MariaDB", status: "skipped", detail: "no user databases to migrate (only system schemas present)" });
            await report(62, "Migrating databases…", `  No user MySQL databases to migrate — skipped.`);
          }
          continue;
        }
        // mysqldump over root's LOCAL socket auth (Debian/Ubuntu root = auth_socket),
        // limited to the validated user DB names.
        const dumpCmd = `${priv}mysqldump --single-transaction --routines --triggers --events --databases ${dbList.join(" ")}`;
        const r = await execRemote(conn, `${onSource(dumpCmd)} > ${dump} 2>${work}/dumps/mysql.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        const nonEmpty = await execRemote(conn, `test -s ${dump}`, SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
        if (r.code !== 0 || !nonEmpty) {
          const err = await execRemote(conn, `tail -c 200 ${work}/dumps/mysql.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
          push({ step: "Migrate MySQL/MariaDB", status: "failed", detail: `root could not dump via local socket${err ? `: ${err}` : ""} — import skipped` });
          await report(62, "Migrating databases…", `  MySQL dump via root failed — skipping (databases left for manual export).`);
        } else {
          // Import on the target as its own root (socket auth — no password). `--force`
          // keeps one bad statement from aborting the whole restore.
          const imp = await execRemote(conn, `mysql --force < ${dump} 2>${work}/dumps/mysql-import.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
          if (imp.code === 0) {
            push({ step: "Migrate MySQL/MariaDB databases", status: "copied", detail: `dumped ${dbList.length} user database(s) via source root socket and imported on the target` });
            await report(64, "Migrating databases…", `  MySQL databases dumped and imported (${dbList.length} user DB(s)).`);
          } else {
            const err = await execRemote(conn, `tail -c 200 ${work}/dumps/mysql-import.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
            push({ step: "Import MySQL/MariaDB", status: "failed", detail: `dump succeeded but import failed${err ? `: ${err}` : ""} — dump kept at ${dump}` });
          }
        }
      } else {
        const dump = `${work}/dumps/postgres-all.sql`;
        // pg_dumpall over peer auth as the postgres superuser.
        const dumpCmd = user === "root" ? "sudo -u postgres pg_dumpall" : "sudo -n -u postgres pg_dumpall";
        const r = await execRemote(conn, `${onSource(dumpCmd)} > ${dump} 2>${work}/dumps/pg.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        const nonEmpty = await execRemote(conn, `test -s ${dump}`, SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
        if (r.code !== 0 || !nonEmpty) {
          const err = await execRemote(conn, `tail -c 200 ${work}/dumps/pg.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
          push({ step: "Migrate PostgreSQL", status: "failed", detail: `postgres peer dump failed${err ? `: ${err}` : ""} — import skipped` });
          await report(62, "Migrating databases…", `  PostgreSQL dump via peer auth failed — skipping.`);
        } else {
          const imp = await execRemote(conn, `sudo -u postgres psql -f ${dump} >/dev/null 2>${work}/dumps/pg-import.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
          // pg_dumpall + psql exits 0 even with benign "role already exists" notices.
          if (imp.code === 0) {
            push({ step: "Migrate PostgreSQL databases", status: "copied", detail: "dumped via source postgres peer auth and imported on the target" });
            await report(64, "Migrating databases…", `  PostgreSQL databases dumped and imported.`);
          } else {
            const err = await execRemote(conn, `tail -c 200 ${work}/dumps/pg-import.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
            push({ step: "Import PostgreSQL", status: "failed", detail: `dump succeeded but import reported errors${err ? `: ${err}` : ""} — dump kept at ${dump}` });
          }
        }
      }
    }

    // ---- 9. Docker Compose bring-up ---------------------------------------
    if (plan.composeDirs.length) {
      await report(74, "Starting containers…", `Bringing up ${plan.composeDirs.length} Docker Compose project(s).`);
      for (const dir of plan.composeDirs) {
        // dir has already been copied to the same path in step 6 (or is being copied).
        const r = await execRemote(
          conn,
          `sh -c 'cd ${dir} && { docker compose up -d || docker-compose up -d; }' >/dev/null 2>${work}/dumps/compose.err`,
          TRANSFER_TIMEOUT_MS
        ).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        if (r.code === 0) {
          push({ step: `Compose up ${dir}`, status: "running", detail: "docker compose up -d succeeded" });
          await report(78, "Starting containers…", `  compose up in ${dir}: started.`);
        } else {
          const err = await execRemote(conn, `tail -c 200 ${work}/dumps/compose.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
          push({ step: `Compose up ${dir}`, status: "failed", detail: `could not start${err ? `: ${err}` : ""} — run 'docker compose up -d' in ${dir}` });
          await report(78, "Starting containers…", `  compose up in ${dir} failed — left for manual start.`);
        }
      }
    }
    // Standalone (non-compose) containers: log a run-equivalent, never auto-run
    // an arbitrary source-supplied image. Honest — these are left for the user.
    for (const c of plan.containers) {
      if (!c.name || !c.image) continue;
      const portsHint = c.ports ? ` ports[${c.ports}]` : "";
      const mountsHint = c.mounts.length ? ` mounts[${c.mounts.join(",")}]` : "";
      push({
        step: `Container ${c.name}`,
        status: "copied",
        detail: `recreate on the new server: image ${c.image}${portsHint}${mountsHint}`,
      });
    }

    // ---- 10. Web-server vhosts (best-effort copy + reload) ----------------
    for (const w of plan.webServers) {
      if (w === "nginx") {
        await execRemote(conn, `mkdir -p /etc/nginx`, SETUP_TIMEOUT_MS).catch(() => {});
        const r = await execRemote(conn, rsyncPull("/etc/nginx/", "/etc/nginx"), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        if (r.code === 0) {
          const up = await execRemote(conn, `nginx -t 2>/dev/null && (systemctl reload nginx 2>/dev/null || systemctl restart nginx 2>/dev/null)`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
          if (up.code === 0) push({ step: "nginx vhosts", status: "running", detail: "config copied, nginx -t passed, reloaded" });
          else push({ step: "nginx vhosts", status: "copied", detail: "config copied but nginx did not reload cleanly — check `nginx -t`" });
        } else {
          push({ step: "nginx vhosts", status: "failed", detail: "could not copy /etc/nginx from the source" });
        }
      } else {
        await execRemote(conn, `mkdir -p /etc/apache2`, SETUP_TIMEOUT_MS).catch(() => {});
        const r = await execRemote(conn, rsyncPull("/etc/apache2/", "/etc/apache2"), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
        if (r.code === 0) {
          const up = await execRemote(conn, `apachectl configtest 2>/dev/null && (systemctl reload apache2 2>/dev/null || systemctl restart apache2 2>/dev/null)`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
          if (up.code === 0) push({ step: "Apache vhosts", status: "running", detail: "config copied, configtest passed, reloaded" });
          else push({ step: "Apache vhosts", status: "copied", detail: "config copied but Apache did not reload cleanly — check `apachectl configtest`" });
        } else {
          push({ step: "Apache vhosts", status: "failed", detail: "could not copy /etc/apache2 from the source" });
        }
      }
    }

    // ---- 11. systemd services (best-effort copy of the unit + enable) -----
    if (plan.services.length) {
      await report(84, "Re-enabling services…", `Re-enabling up to ${plan.services.length} service(s) that ran on the source.`);
      for (const svc of plan.services) {
        const unit = `/etc/systemd/system/${svc}.service`;
        // Copy the unit file only if it exists on the source (best-effort).
        const r = await execRemote(conn, rsyncPull(unit, "/etc/systemd/system"), SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
        if (r.code !== 0) {
          push({ step: `Service ${svc}`, status: "copied", detail: "unit not a simple /etc/systemd/system file — re-enable manually" });
          continue;
        }
        await execRemote(conn, `systemctl daemon-reload 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
        const en = await execRemote(conn, `systemctl enable --now ${svc} 2>/dev/null`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
        const active = await execRemote(conn, `systemctl is-active ${svc} 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim() === "active").catch(() => false);
        if (en.code === 0 && active) push({ step: `Service ${svc}`, status: "running", detail: "unit copied, enabled and active" });
        else push({ step: `Service ${svc}`, status: "copied", detail: "unit copied but not confirmed active — check `systemctl status`" });
      }
    }

    // ---- 12. Verification: DB engines, containers, listening ports --------
    await report(92, "Verifying…", "Checking that databases, containers and services are up on the new server.");
    if (plan.dbEngines.includes("mysql")) {
      const up = await execRemote(conn, `systemctl is-active mariadb 2>/dev/null || systemctl is-active mysql 2>/dev/null || pgrep -x mysqld >/dev/null 2>&1 && echo active`, SETUP_TIMEOUT_MS).then((x) => /active/.test(x.stdout)).catch(() => false);
      push({ step: "MySQL/MariaDB engine", status: up ? "running" : "copied", detail: up ? "engine is active on the target" : "engine not confirmed active — start it manually" });
    }
    if (plan.dbEngines.includes("postgres")) {
      const up = await execRemote(conn, `systemctl is-active postgresql 2>/dev/null || (pgrep -x postgres >/dev/null 2>&1 && echo active)`, SETUP_TIMEOUT_MS).then((x) => /active/.test(x.stdout)).catch(() => false);
      push({ step: "PostgreSQL engine", status: up ? "running" : "copied", detail: up ? "engine is active on the target" : "engine not confirmed active — start it manually" });
    }
    if (plan.hasContainers) {
      const n = await execRemote(conn, `docker ps -q 2>/dev/null | wc -l`, SETUP_TIMEOUT_MS).then((x) => parseInt(x.stdout.trim(), 10) || 0).catch(() => 0);
      push({ step: "Docker containers", status: n > 0 ? "running" : "copied", detail: n > 0 ? `${n} container(s) running on the target` : "no containers running yet — start your compose project(s)" });
      await report(94, "Verifying…", `  docker ps shows ${n} running container(s).`);
    }
    if (plan.verifyPorts.length) {
      const list = plan.verifyPorts.join(" ");
      const out = await execRemote(
        conn,
        `for p in ${list}; do (ss -lnt 2>/dev/null || netstat -lnt 2>/dev/null) | grep -q ":$p " && echo "$p up" || echo "$p down"; done`,
        SETUP_TIMEOUT_MS
      ).then((x) => x.stdout).catch(() => "");
      const upPorts = (out.match(/(\d+) up/g) ?? []).map((s) => s.replace(" up", ""));
      const downPorts = (out.match(/(\d+) down/g) ?? []).map((s) => s.replace(" down", ""));
      if (upPorts.length) push({ step: "Listening ports", status: "running", detail: `now listening on the target: ${upPorts.join(", ")}` });
      if (downPorts.length) push({ step: "Ports not yet listening", status: "copied", detail: `not up on the target yet: ${downPorts.join(", ")} — start the owning app/service` });
      await report(95, "Verifying…", `  ports up: ${upPorts.join(", ") || "none"}; not up: ${downPorts.join(", ") || "none"}.`);
    }

    // ---- 13. Final honest summary ----------------------------------------
    await report(
      97,
      "Finalising…",
      `Migrated & running (verified): ${verifiedRunning.length}. Copied — may need a manual step: ${needsAttention.length}.`
    );
    if (needsAttention.length) {
      await report(98, "Finalising…", `Needs a manual step: ${needsAttention.slice(0, 8).join(" | ")}${needsAttention.length > 8 ? " …" : ""}`);
    }

    return { results, verifiedRunning, needsAttention };
  } finally {
    // Scrub the SSH password file from the target, always. DB dumps under
    // ${work}/dumps are intentionally kept so a failed import can be retried by hand.
    await execRemote(conn, `shred -u ${passFile} 2>/dev/null || rm -f ${passFile}`, SETUP_TIMEOUT_MS).catch(() => {});
    try {
      conn.end();
    } catch {
      /* best-effort */
    }
  }
}

/** Where transient migration state (dumps) lands on the target, for the notice. */
export function migrationWorkDir(migrationId: string): string {
  return `/root/nxeon-migrations/${migration_id_safe(migrationId)}`;
}

function migration_id_safe(id: string): string {
  return /^[A-Za-z0-9_-]{1,64}$/.test(id) ? id : "invalid";
}

        if (!SVCNAME_RE.test(name)) continue;
        if (services.some((s) => s.name === name)) continue;
        services.push({ name });
      }
    }

    // Prune web roots that are ancestors of another detected root (avoid copying
    // a parent AND its children — e.g. drop /var/www when /var/www/html exists).
    const pruned = webRoots.filter(
      (a) => !webRoots.some((b) => b.path !== a.path && b.path.startsWith(a.path + "/"))
    );
    webRoots.length = 0;
    webRoots.push(...pruned.slice(0, MAX_WEB_ROOTS));
    homes.splice(MAX_HOMES);

    // Merge candidate app dirs into a migratable list, deduped against web roots /
    // home dirs (and each other) so a directory is never listed — or copied — twice.
    // A path clashes if it equals, contains, or is contained by an already-known path.
    const known = [...webRoots.map((w) => w.path), ...homes.map((h) => h.path)];
    const appDirs: DetectedAppDir[] = [];
    for (const a of rawAppDirs) {
      if (appDirs.length >= MAX_APP_DIRS) break;
      const clashesKnown = known.some(
        (p) => a.path === p || a.path.startsWith(p + "/") || p.startsWith(a.path + "/")
      );
      if (clashesKnown) continue;
      const clashesApp = appDirs.some(
        (b) => a.path === b.path || a.path.startsWith(b.path + "/") || b.path.startsWith(a.path + "/")
      );
      if (clashesApp) continue;
      appDirs.push(a);
    }
    appDirs.sort((x, y) => parseSizeLabel(y.sizeLabel) - parseSizeLabel(x.sizeLabel));
    if (appDirs.length > 0) {
      notes.push(
        `Found ${appDirs.length} app ${appDirs.length === 1 ? "directory" : "directories"} outside the standard web folders (from running processes / app files).`
      );
    }
    if (containers.length > 0) {
      notes.push(
        `Detected ${containers.length} running Docker ${containers.length === 1 ? "container" : "containers"} — we install Docker + Compose, copy their data and named volumes, and start any Compose project automatically on the new server.`
      );
    }

    // ---- 2. Databases — only if the customer supplied DB creds ------------
    const hasSafePass =
      !!input.dbPassword && !input.dbPassword.includes("\n") && !input.dbPassword.includes("\r");
    if (input.dbPassword && !hasSafePass) {
      notes.push("Database password contains unsupported characters — databases were skipped.");
    }

    for (const eng of ["mysql", "postgres"] as const) {
      const st = engineState[eng];
      const rec: DetectedEngine = { engine: eng, present: st.present, listening: st.listening, listed: false };
      if (st.present && hasSafePass) {
        const effUser = (input.dbUser && input.dbUser.trim()) || (eng === "mysql" ? "root" : "postgres");
        if (!DBUSER_RE.test(effUser)) {
          notes.push(`Database user "${effUser}" has unsupported characters — ${eng} databases were skipped.`);
        } else {
          try {
            const found =
              eng === "mysql"
                ? await listMysql(conn, effUser, input.dbPassword!)
                : await listPostgres(conn, effUser, input.dbPassword!);
            for (const d of found) {
              if (databases.length >= MAX_DATABASES) break;
              databases.push(d);
            }
            rec.listed = true;
          } catch (e: any) {
            notes.push(
              `${eng === "mysql" ? "MySQL" : "PostgreSQL"} is installed but we couldn't read its databases with those credentials — you can add databases manually.`
            );
          }
        }
      } else if (st.present && !input.dbPassword) {
        notes.push(
          `${eng === "mysql" ? "MySQL" : "PostgreSQL"} detected — all its databases are included automatically (no password needed; we dump them with root access on the old server).`
        );
      }
      engines.push(rec);
    }

    databases.sort((a, b) => parseSizeLabel(b.sizeLabel) - parseSizeLabel(a.sizeLabel));
    ports.sort((a, b) => a.port - b.port);

    const sourceOs =
      osrel.id || osrel.pretty || osrel.versionId
        ? { id: osrel.id ?? "", versionId: osrel.versionId ?? "", pretty: osrel.pretty ?? "" }
        : null;

    // Exact engine variant + version for each PRESENT engine — used to install the
    // MATCHING engine on the target for a clean, same-engine restore.
    const dbEngines: DbEngineDetail[] = [];
    if (engineState.mysql.present) {
      const { variant, version } = parseMysqlVersion(dbVerRaw.mysql);
      dbEngines.push({ engine: "mysql", variant, version });
    }
    if (engineState.postgres.present) {
      dbEngines.push({ engine: "postgres", variant: null, version: parsePgVersion(dbVerRaw.postgres) });
    }

    return {
      ok: true,
      webRoots,
      homes,
      databases,
      engines,
      dbEngines,
      appDirs,
      containers,
      ports,
      services,
      notes,
      dbSizeBytes,
      sourceOs,
      sourceArch,
    };
  } finally {
    try {
      conn.end();
    } catch {
      /* best-effort */
    }
  }
}

/** Enumerate MySQL/MariaDB schemas + sizes. Creds read from /dev/stdin (never argv). */
async function listMysql(conn: Client, user: string, pass: string): Promise<DetectedDatabase[]> {
  // `--defaults-extra-file=/dev/stdin` makes mysql read the [client] block from
  // the STDIN we stream below — the password never appears on the command line.
  const query =
    "SELECT table_schema, IFNULL(SUM(data_length+index_length),0) " +
    "FROM information_schema.tables GROUP BY table_schema;";
  const cnf = `[client]\nuser=${user}\npassword=${pass}\nhost=127.0.0.1\nprotocol=tcp\n`;
  const r = await execRemoteInput(
    conn,
    `mysql --defaults-extra-file=/dev/stdin -N -B -e ${shSingleQuote(query)}`,
    cnf,
    DB_TIMEOUT_MS
  );
  if (r.code !== 0) throw new Error(r.stderr.slice(0, 200) || `mysql exit ${r.code}`);
  const out: DetectedDatabase[] = [];
  for (const line of r.stdout.split("\n")) {
    const [name, bytes] = line.replace(/\r$/, "").split("\t");
    if (!name || SYSTEM_SCHEMAS.has(name.toLowerCase())) continue;
    if (!DBNAME_RE.test(name)) continue;
    out.push({ engine: "mysql", name, sizeLabel: humanBytes(Number(bytes) || 0) });
  }
  return out;
}

/** Enumerate PostgreSQL databases + sizes. Creds read from /dev/stdin (.pgpass). */
async function listPostgres(conn: Client, user: string, pass: string): Promise<DetectedDatabase[]> {
  const query =
    "SELECT datname, pg_database_size(datname) FROM pg_database WHERE datistemplate = false;";
  const pgpass = `127.0.0.1:5432:*:${user}:${pass}\n`;
  const r = await execRemoteInput(
    conn,
    `PGPASSFILE=/dev/stdin psql -h 127.0.0.1 -U ${user} -w -A -t -F '\t' -c ${shSingleQuote(query)}`,
    pgpass,
    DB_TIMEOUT_MS
  );
  if (r.code !== 0) throw new Error(r.stderr.slice(0, 200) || `psql exit ${r.code}`);
  const out: DetectedDatabase[] = [];
  for (const line of r.stdout.split("\n")) {
    const [name, bytes] = line.replace(/\r$/, "").split("\t");
    if (!name || name === "postgres") continue;
    if (!DBNAME_RE.test(name)) continue;
    out.push({ engine: "postgres", name, sizeLabel: humanBytes(Number(bytes) || 0) });
  }
  return out;
}

/**
 * Single-quote a FIXED, code-authored SQL string for the remote shell. The
 * inputs here are compile-time constants (never customer data), so this only
 * guards the literal `'` inside our own query text.
 */
function shSingleQuote(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`;
}

