import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import type { Job } from "@prisma/client";
import { runRealMigration, migrationWorkDir, type MigrationStepResult, type ScanSnapshot } from "./migrate-real";

/**
 * Real cross-provider transfer is OFF by default. It only runs when the operator
 * explicitly sets ENABLE_REAL_MIGRATION=1 (and never in the sandbox). Otherwise
 * the safe, progress-reporting SIMULATION below runs. The real engine
 * (worker/migrate-real.ts) is hardened against shell injection and never lets a
 * secret touch a command string. Enable it only after testing on a throwaway VM.
 */
const REAL_MIGRATION = process.env.ENABLE_REAL_MIGRATION === "1" && !SANDBOX;

/**
 * MIGRATE — pull a customer's files + databases from another provider's VPS onto
 * their new Nxeon server.
 *
 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
 *   MIGRATE: runMigration,
 *
 * Ownership + validation happen at enqueue time (lib/actions-migrate.ts), so the
 * handler trusts `payload.migrationId`.
 *
 * SAFETY: real cross-provider transfer (SSH into the source, rsync-pull files,
 * mysqldump/pg_dump → import on target) is involved infra that has to be built
 * out carefully — see the TODO(real migration) block below. For now this runs a
 * SANDBOX-SAFE SIMULATION that walks realistic stages and reports progress, so
 * it is harmless to run against real infrastructure. It NEVER opens a real SSH
 * connection to the customer's source box.
 *
 * On completion (DONE or FAILED) every stored source secret is CLEARED:
 * `sourcePasswordEnc` and each database's `passEnc`. A finished Migration row
 * therefore never retains usable credentials.
 */

type MigratePayload = { migrationId?: string };
type MigrationItems = {
  paths?: string[];
  // Legacy per-DB list (with encrypted password) — kept optional for old rows.
  databases?: { engine: string; name: string; user: string; passEnc?: string }[];
  // Passwordless lift-and-shift plan (extended TS shape carried through the
  // existing Migration.items Json column — no schema change).
  dbEngines?: string[];
  dockerVolumes?: string[];
  composeDirs?: string[];
  verifyPorts?: number[];
  hasContainers?: boolean;
  webServers?: string[];
  runtimes?: string[];
  scan?: ScanSnapshot;
  // Written back at completion: the honest per-step outcome summary.
  results?: MigrationStepResult[];
};

const MAX_LOG_CHARS = 8000;

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** Append a timestamped line to a log tail, keeping it bounded. */
function appendLog(prev: string | null | undefined, line: string): string {
  const stamp = new Date().toISOString().slice(11, 19);
  const next = `${prev ?? ""}${prev ? "\n" : ""}[${stamp}] ${line}`;
  return next.length > MAX_LOG_CHARS ? next.slice(next.length - MAX_LOG_CHARS) : next;
}

async function loadMigration(job: Job) {
  const payload = (job.payload ?? {}) as MigratePayload;
  if (!payload.migrationId) throw new Error("migrate job: missing migrationId");
  const migration = await db.migration.findUnique({ where: { id: payload.migrationId } });
  if (!migration) throw new Error(`Migration ${payload.migrationId} not found`);
  // Migration has no Prisma relation to Server (serverId is a plain FK) — resolve
  // the target server row separately. `dedicatedIp` is needed by the real engine
  // to compute the SSH connection target.
  const server = await db.server.findUnique({
    where: { id: migration.serverId },
    include: { dedicatedIp: true },
  });
  return { ...migration, server };
}

/**
 * Strip every source secret from a migration row. Called once the job finishes
 * (success or failure) so a completed migration never keeps usable credentials.
 */
async function clearSecrets(
  migrationId: string,
  items: MigrationItems,
  results?: MigrationStepResult[]
) {
  // Preserve every NON-secret field (so the wizard/summary keep working) while
  // stripping the only secret carried in items — each legacy DB's passEnc. The
  // source SSH password (sourcePasswordEnc column) is nulled separately.
  const scrubbed: MigrationItems = {
    ...items,
    databases: (items.databases ?? []).map((d) => ({
      engine: d.engine,
      name: d.name,
      user: d.user,
      // passEnc dropped entirely
    })),
    ...(results ? { results } : {}),
  };
  await db.migration.update({
    where: { id: migrationId },
    data: { sourcePasswordEnc: null, items: scrubbed as any },
  });
}

async function report(
  migrationId: string,
  progress: number,
  step: string,
  logLine: string,
  logTail: string | null
): Promise<string> {
  const log = appendLog(logTail, logLine);
  await db.migration.update({
    where: { id: migrationId },
    data: { status: "RUNNING", progress, step, log },
  });
  return log;
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[migrate] notify failed", e);
  }
}

export async function runMigration(job: Job): Promise<void> {
  const migration = await loadMigration(job);
  const items = (migration.items ?? {}) as MigrationItems;
  const paths = items.paths ?? [];
  const target = migration.server;
  const targetName = target ? target.label || target.hostname : "your server";

  // Fresh start (also lets a retried job re-enter cleanly).
  let log = appendLog(null, `Starting migration from ${migration.sourceUser}@${migration.sourceHost}:${migration.sourcePort} → ${targetName}`);
  await db.migration.update({
    where: { id: migration.id },
    data: { status: "RUNNING", progress: 5, step: "Starting", log, lastError: null, finishedAt: null },
  });

  // Shared progress reporter: threads the bounded log tail through each update so
  // both the real engine and the simulation write to the same Migration row.
  const reportStep = async (progress: number, step: string, line: string) => {
    log = await report(migration.id, progress, step, line, log);
  };

  try {
    if (REAL_MIGRATION) {
      // ---- REAL lift-and-shift (hardened; opt-in via ENABLE_REAL_MIGRATION) --
      const summary = await runRealMigration({
        migration: {
          id: migration.id,
          sourceHost: migration.sourceHost,
          sourcePort: migration.sourcePort,
          sourceUser: migration.sourceUser,
          sourcePasswordEnc: migration.sourcePasswordEnc,
        },
        target: target as any,
        items,
        report: reportStep,
      });

      await db.migration.update({
        where: { id: migration.id },
        data: { status: "DONE", progress: 100, step: "Completed", finishedAt: new Date() },
      });
      // Persist the honest step-by-step summary (secret-free) into items.results.
      await clearSecrets(migration.id, items, summary.results);

      const workDir = migrationWorkDir(migration.id);
      const running = summary.verifiedRunning.length;
      const manual = summary.needsAttention.length;
      const body =
        `Lift-and-shift onto ${targetName} finished. ${running} item(s) migrated & verified running; ` +
        `${manual} copied that may need a manual step. ` +
        (manual ? `To finish: ${summary.needsAttention.slice(0, 5).join(" | ")}${manual > 5 ? " …" : ""}. ` : "") +
        `Any DB dumps that couldn't import were kept under ${workDir}/dumps. Point your DNS at the new server when ready.`;
      await notify(migration.userId, `Migration to ${targetName} completed`, body, "/dashboard/migrate");
      return;
    }

    // ---- Progress-reporting SIMULATION of the lift-and-shift (default) --------
    // Mirrors the real engine's flow (dump DBs via root, install prerequisites,
    // import DBs, compose up, verify) with SYNTHETIC success. Delays are short so
    // the UI polls a live-feeling progression. NEVER opens a real SSH connection.
    const dbEngines = (items.dbEngines ?? []).filter((e) => e === "mysql" || e === "postgres");
    const composeDirs = items.composeDirs ?? [];
    const webServers = items.webServers ?? [];
    const runtimes = items.runtimes ?? [];
    const verifyPorts = items.verifyPorts ?? [];
    const hasContainers = !!items.hasContainers || composeDirs.length > 0;
    const simResults: MigrationStepResult[] = [];

    await reportStep(6, "Connecting…", `Connecting to your Nxeon server (${targetName}) to prepare the lift-and-shift.`);
    await sleep(SANDBOX ? 500 : 1000);
    await reportStep(12, "Connecting to source…", `Connecting to ${migration.sourceHost} over SSH (port ${migration.sourcePort}). Authenticated with root.`);
    await sleep(SANDBOX ? 400 : 800);

    // Prerequisites stage.
    const prereqLabels: string[] = [];
    if (dbEngines.includes("mysql")) prereqLabels.push("MySQL/MariaDB server");
    if (dbEngines.includes("postgres")) prereqLabels.push("PostgreSQL server");
    if (hasContainers) prereqLabels.push("Docker Engine + compose");
    for (const w of webServers) prereqLabels.push(w === "nginx" ? "nginx" : "Apache");
    for (const rt of runtimes) prereqLabels.push(rt === "nodejs" ? "Node.js" : "Python 3 + pip");
    if (prereqLabels.length) {
      await reportStep(18, "Installing prerequisites…", `Installing on ${targetName}: ${prereqLabels.join(", ")}.`);
      for (const lbl of prereqLabels) {
        await sleep(SANDBOX ? 200 : 400);
        await reportStep(20, "Installing prerequisites…", `  ${lbl}: installed.`);
        simResults.push({ step: `Install ${lbl}`, status: "running", detail: "installed" });
      }
    }

    // Files stage — same-path copy.
    await reportStep(30, "Copying files…", paths.length ? `Copying ${paths.length} path(s) to the same locations on ${targetName}.` : "No file paths selected — skipping file copy.");
    for (const p of paths) {
      await sleep(SANDBOX ? 200 : 400);
      await reportStep(40, "Copying files…", `  rsync ${p} → ${p}`);
    }
    if (paths.length) simResults.push({ step: `Copy ${paths.length} folder(s) to their original paths`, status: "copied", detail: "files placed at the same paths" });

    // Databases — dump via source root LOCAL auth (no password), import on target.
    for (const eng of dbEngines) {
      await sleep(SANDBOX ? 300 : 600);
      if (eng === "mysql") {
        await reportStep(62, "Migrating databases…", "  mysqldump --all-databases via source root socket (no password) → mysql < dump on target.");
        simResults.push({ step: "Migrate MySQL/MariaDB databases", status: "copied", detail: "dumped via source root socket and imported" });
      } else {
        await reportStep(64, "Migrating databases…", "  sudo -u postgres pg_dumpall via peer auth → psql -f on target.");
        simResults.push({ step: "Migrate PostgreSQL databases", status: "copied", detail: "dumped via source postgres peer auth and imported" });
      }
    }

    // Docker compose bring-up.
    for (const dir of composeDirs) {
      await sleep(SANDBOX ? 250 : 500);
      await reportStep(76, "Starting containers…", `  cd ${dir} && docker compose up -d`);
      simResults.push({ step: `Compose up ${dir}`, status: "running", detail: "docker compose up -d succeeded" });
    }

    // Verification.
    await reportStep(92, "Verifying…", "Checking databases, containers and listening ports on the new server.");
    await sleep(SANDBOX ? 400 : 800);
    if (dbEngines.includes("mysql")) simResults.push({ step: "MySQL/MariaDB engine", status: "running", detail: "engine is active on the target" });
    if (dbEngines.includes("postgres")) simResults.push({ step: "PostgreSQL engine", status: "running", detail: "engine is active on the target" });
    if (hasContainers) {
      await reportStep(94, "Verifying…", `  docker ps shows ${composeDirs.length || 1} running container(s).`);
      simResults.push({ step: "Docker containers", status: "running", detail: `${composeDirs.length || 1} container(s) running` });
    }
    if (verifyPorts.length) {
      await reportStep(95, "Verifying…", `  ports up: ${verifyPorts.join(", ")}.`);
      simResults.push({ step: "Listening ports", status: "running", detail: `now listening: ${verifyPorts.join(", ")}` });
    }

    const simRunning = simResults.filter((r) => r.status === "running").length;
    const simManual = simResults.filter((r) => r.status === "copied" || r.status === "failed").length;
    await reportStep(98, "Finalising…", `Migrated & running (verified): ${simRunning}. Copied — may need a manual step: ${simManual}.`);
    await sleep(SANDBOX ? 300 : 600);

    await db.migration.update({
      where: { id: migration.id },
      data: { status: "DONE", progress: 100, step: "Completed", finishedAt: new Date() },
    });
    // Security: drop all source credentials now that the job is done; persist summary.
    await clearSecrets(migration.id, items, simResults);

    await notify(
      migration.userId,
      `Migration to ${targetName} completed`,
      `Lift-and-shift onto ${targetName} finished: ${simRunning} item(s) migrated & running, ${simManual} copied. Point your DNS at the new server when ready.`,
      "/dashboard/migrate"
    );
  } catch (e: any) {
    const lastError = `${e?.message ?? e}`.slice(0, 1000);
    console.error(`[migrate] migration ${migration.id} failed:`, e);
    log = appendLog(log, `ERROR: ${lastError}`);
    await db.migration
      .update({
        where: { id: migration.id },
        data: { status: "FAILED", step: "Failed", lastError, log, finishedAt: new Date() },
      })
      .catch(() => {});
    // Security: clear the stored source password/DB secrets even on failure.
    await clearSecrets(migration.id, items).catch(() => {});
    await notify(
      migration.userId,
      `Migration to ${targetName} failed`,
      lastError,
      "/dashboard/migrate"
    );
    // Swallow — the failure is recorded on the Migration row. Re-throwing would
    // make the job loop retry a migration whose secrets we've already cleared.
  }
}

