//
// Docker image reference — `repo`, `ns/repo:tag`, `registry.io:5000/ns/repo@sha256:…`.
// MUST match IMAGEREF_RE in worker/migrate-detect.ts.
const IMAGEREF_RE = /^[A-Za-z0-9][A-Za-z0-9._:@/-]{0,254}$/;
// Docker container / network name (docker's own charset).
const CONTNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
// A DNS hostname we are willing to write into a generated vhost or a curl Host
// header. MUST match DOMAIN_RE in worker/migrate-detect.ts.
const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$/;
// MySQL account parts. `%` (the wildcard host) and `-`/`.`/`_` are all inert.
const MYSQL_USER_RE = /^[A-Za-z0-9_.-]{1,32}$/;
const MYSQL_HOST_RE = /^[A-Za-z0-9_.%-]{1,64}$/;
// Kernel block-device leaf name: sdb, vdb, nvme1n1, xvdf.
const BLOCKDEV_RE = /^[a-z][a-z0-9]{1,31}$/;
const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
// A Linux capability as `docker inspect` reports it (CAP_NET_ADMIN / NET_ADMIN).
const CAP_RE = /^(CAP_)?[A-Z][A-Z0-9_]{1,31}$/;
// `--user` value: name, uid, name:group or uid:gid.
const RUNUSER_RE = /^[A-Za-z0-9_][A-Za-z0-9_.:-]{0,64}$/;

// Docker restart policies we will reproduce verbatim. Anything else is refused.
const RESTART_POLICIES = new Set(["no", "always", "unless-stopped", "on-failure"]);
// Docker's own built-in networks — these need no `docker network create`.
const BUILTIN_NETWORKS = new Set(["bridge", "host", "none", "default"]);
// MySQL's own plumbing accounts. Migrating these would overwrite the NEW
// server's root/maintenance logins and lock us out of our own box, so they are
// never touched; only real application accounts are reproduced.
const MYSQL_SYSTEM_USERS = new Set([
  "root", "mysql.sys", "mysql.session", "mysql.infoschema", "mariadb.sys",
  "debian-sys-maint", "healthchecker", "sys_maint", "",
]);
// Login shells we are willing to set on a recreated system user. Anything else
// falls back to nologin (the account still exists so file ownership resolves).
const LOGIN_SHELLS = new Set([
  "/bin/sh", "/bin/bash", "/bin/dash", "/bin/zsh", "/usr/bin/zsh", "/usr/bin/bash",
  "/usr/bin/fish", "/bin/false", "/usr/bin/false", "/sbin/nologin", "/usr/sbin/nologin",
  "/usr/bin/nologin",
]);
const NOLOGIN = "/usr/sbin/nologin";
// Image names that mean "this container IS the reverse proxy" — if one of these
// publishes :80/:443 the host web server must stay out of its way.
const PROXY_IMAGE_RE = /(^|\/)(traefik|caddy|nginx|haproxy|envoyproxy\/envoy|jwilder\/nginx-proxy|nginxproxy\/nginx-proxy|jc21\/nginx-proxy-manager)(:|$)/i;

