/** dirname of a validated absolute path (both inputs/outputs are shell-inert). */
function parentDir(p: string): string {
  const i = p.lastIndexOf("/");
  return i <= 0 ? "/" : p.slice(0, i);
}

/** Strip control characters and bound any free text that came back from a probe. */
function clean(s: unknown, max: number): string {
  // eslint-disable-next-line no-control-regex
  return String(s ?? "").replace(/[\x00-\x1f\x7f]/g, "").trim().slice(0, max);
}

/** A Docker image reference we are willing to put in a command at all. */
function validImageRef(r: string): boolean {
  return (
    typeof r === "string" &&
    IMAGEREF_RE.test(r) &&
    !r.includes("..") &&
    !r.includes("//") &&
    !r.startsWith("-") &&
    !r.includes("<none>")
  );
}

/**
 * True when a reference cannot come from a public registry — a LOCALLY-BUILT
 * tag. A registry host is the first `/`-segment when it contains a `.` (domain)
 * or `:` (host:port), or is exactly `localhost`. `ns/name` with neither is
 * either Docker Hub or a local build tag and cannot be told apart by name, so we
 * treat it as local: a `docker save`/`load` always works, whereas guessing
 * "pullable" wrongly leaves the customer's container permanently dead (exactly
 * what happened with `studionexis/frontend:latest` in the field).
 * MUST match isLocalImageRef in worker/migrate-detect.ts.
 */
function isLocalImageRef(ref: string): boolean {
  const bare = ref.split("@")[0];
  const slash = bare.indexOf("/");
  if (slash < 0) return false; // Docker Hub library image, e.g. `redis:7-alpine`
  const head = bare.slice(0, slash);
  if (head === "localhost") return true;
  return !(head.includes(".") || head.includes(":"));
}

/** A hostname we are willing to serve / probe (lowercased, wildcard stripped). */
function normalizeDomain(raw: string): string | null {
  const h = clean(raw, 253).toLowerCase().replace(/^["']|["']$/g, "").replace(/^\*\./, "").replace(/\.$/, "");
  if (!h || h === "localhost" || h === "_" || h === "default_server") return null;
  if (!DOMAIN_RE.test(h)) return null;
  if (/^\d+(\.\d+)*$/.test(h)) return null; // an IP is not a vhost name
  const tld = h.slice(h.lastIndexOf(".") + 1);
  if (tld.length < 2 || /\d/.test(tld)) return null;
  return h;
}

function gb(n: number): string {
  return `${(n / GiB).toFixed(1)} GB`;
}

/** Last few non-empty lines of a command result, bounded — for honest logging. */
function tailOf(r: { stdout?: string; stderr?: string }, lines = 2, max = 200): string {
  return clean((r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-lines).join(" "), max);
}

/** True when a failure was actually "the disk is full" (the dominant real failure). */
function isEnospc(text: string): boolean {
  return /no space left on device|ENOSPC|write.*: no space|disk quota exceeded/i.test(text ?? "");
}

type ExecResult = { code: number; stdout: string; stderr: string };

/**
 * `execRemote` that never throws — a timed-out or broken command reports exit 1
 * with its reason in `stderr`. Every best-effort step uses this so one failed
 * probe can never abort the whole migration.
 */
function sh(conn: Client, cmd: string, timeoutMs: number = SETUP_TIMEOUT_MS): Promise<ExecResult> {
  return execRemote(conn, cmd, timeoutMs).catch((e) => ({
    code: 1,
    stdout: "",
    stderr: String(e?.message ?? e),
  }));
}

/** `sh` reduced to a boolean "did it succeed". */
async function shOk(conn: Client, cmd: string, timeoutMs: number = SETUP_TIMEOUT_MS): Promise<boolean> {
  return (await sh(conn, cmd, timeoutMs)).code === 0;
}

