/**
 * The wizard's stored scan snapshot (`Migration.items.scan`) is trimmed on the
 * way into the DB and is taken hours or days before the cutover, so it cannot
 * answer the questions that decide whether the site actually SERVES afterwards:
 * which images back each container, the full `docker inspect` shape of the
 * standalone ones, which MySQL accounts the apps log in as, which domains the
 * web server answers on, what cron/TLS/system-user state exists.
 *
 * So the engine re-probes the source itself, live, over the SSH channel it
 * already holds. The probe is ONE fixed, code-authored POSIX-sh script that is
 * written to the TARGET over SFTP (0600, bytes — never a shell argument) and fed
 * to the source with `ssh … sh -s < script`. Travelling on STDIN instead of argv
 * means the script needs no quoting gymnastics and contains ZERO interpolated
 * values other than a compile-time-constant `sudo -n` prefix, so it has no
 * injection surface at all. It is strictly read-only: `docker inspect`, `mysql
 * -e SELECT`, `grep`, `ls`, `awk` over /etc/passwd, `du`.
 *
 * EVERYTHING it returns is untrusted and is re-validated against the allowlists
 * above before it can reach any command.
 */
type SrcPort = { containerPort: number; proto: string; hostIp: string; hostPort: number };
type SrcMount = { kind: string; name: string; source: string; dest: string; rw: boolean };
type SrcContainer = {
  id: string;
  name: string;
  image: string;
  state: string;
  restart: string;
  netmode: string;
  runuser: string;
  workdir: string;
  privileged: boolean;
  devices: number;
  caps: string[];
  cmd: string;
  entrypoint: string;
  imagecmd: string;
  imageentrypoint: string;
  project: string;
  ports: SrcPort[];
  mounts: SrcMount[];
  networks: string[];
};
type SrcImage = { ref: string; sizeBytes: number; local: boolean };
type SrcInventory = {
  probed: boolean;
  hasDocker: boolean;
  images: SrcImage[];
  imageBytes: number;
  volumeBytes: number;
  containers: SrcContainer[];
  mysqlAccounts: { user: string; host: string }[];
  domains: string[];
  webConfigs: string[];
  tlsCerts: string[];
  hasLetsEncrypt: boolean;
  cronUsers: { name: string; dir: string }[];
  hasCronD: boolean;
  users: { name: string; uid: number; gid: number; home: string; shell: string }[];
  groups: { name: string; gid: number }[];
};

function emptyInventory(): SrcInventory {
  return {
    probed: false, hasDocker: false, images: [], imageBytes: 0, volumeBytes: 0,
    containers: [], mysqlAccounts: [], domains: [], webConfigs: [], tlsCerts: [],
    hasLetsEncrypt: false, cronUsers: [], hasCronD: false, users: [], groups: [],
  };
}

/** Parse docker's human size label ("1.23GB", "345MB", "12.3kB") into bytes. */
function parseDockerSize(label: string): number {
  const m = /^([\d.]+)\s*([KMGT]?)/i.exec(clean(label, 32));
  if (!m) return 0;
  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
  return Math.max(0, Math.round(parseFloat(m[1]) * (mult[m[2].toUpperCase()] ?? 1)));
}

function human(n: number): string {
  if (!Number.isFinite(n) || n <= 0) return "0 B";
  const u = ["B", "KB", "MB", "GB", "TB"];
  let i = 0;
  let v = n;
  while (v >= 1024 && i < u.length - 1) {
    v /= 1024;
    i++;
  }
  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${u[i]}`;
}

/**
 * The read-only inventory script. Authored as an array of PLAIN strings (never a
 * template literal) so shell `${…}` expansions can't collide with JS
 * interpolation, exactly like the detection scan. `priv` is "" or "sudo -n" — a
 * compile-time constant picked from `user === "root"`, never source data.
 */
function srcInventoryScript(priv: string): string {
  return [
    "export LC_ALL=C",
    'if command -v timeout >/dev/null 2>&1; then TO="timeout 25"; else TO=""; fi',
    'PRIV="' + priv + '"',
    // One Go template that emits every container field we can safely reproduce,
    // one "key value" per line. Optional strings emit "-" so whitespace-splitting
    // stays aligned.
    "FMT='name {{.Name}}",
    "image {{.Config.Image}}",
    "state {{.State.Status}}",
    "restart {{.HostConfig.RestartPolicy.Name}}",
    "netmode {{.HostConfig.NetworkMode}}",
    "runuser {{.Config.User}}",
    "workdir {{.Config.WorkingDir}}",
    "privileged {{.HostConfig.Privileged}}",
    "devices {{len .HostConfig.Devices}}",
    "caps {{range .HostConfig.CapAdd}}{{.}} {{end}}",
    "cmd {{range .Config.Cmd}}{{.}}~{{end}}",
    "entrypoint {{range .Config.Entrypoint}}{{.}}~{{end}}",
    'project {{range $k, $v := .Config.Labels}}{{if eq $k "com.docker.compose.project"}}{{$v}}{{end}}{{end}}',
    "{{range $p, $bs := .HostConfig.PortBindings}}{{range $bs}}port {{$p}} {{if .HostIp}}{{.HostIp}}{{else}}-{{end}} {{.HostPort}}",
    "{{end}}{{end}}{{range .Mounts}}mount {{.Type}} {{if .Name}}{{.Name}}{{else}}-{{end}} {{if .Source}}{{.Source}}{{else}}-{{end}} {{.Destination}} {{.RW}}",
    "{{end}}{{range $k, $v := .NetworkSettings.Networks}}net {{$k}}",
    "{{end}}'",
    // The IMAGE's own default cmd/entrypoint, so we can tell whether the
    // container OVERRODE them (an override we cannot safely re-tokenise ⇒ refuse).
    "IFMT='imagecmd {{range .Config.Cmd}}{{.}}~{{end}}",
    "imageentrypoint {{range .Config.Entrypoint}}{{.}}~{{end}}'",
    "if command -v docker >/dev/null 2>&1; then",
    "  printf 'HASDOCKER\\t1\\n'",
    "  $TO $PRIV docker images --format '{{.Repository}}:{{.Tag}}|{{.Size}}' 2>/dev/null | head -n 120 | while IFS= read -r il; do",
    '    [ -n "$il" ] && printf \'IMAGE\\t%s\\n\' "$il"',
    "  done",
    "  if [ -d /var/lib/docker/volumes ]; then",
    '    dvb=$($TO $PRIV du -sbx /var/lib/docker/volumes 2>/dev/null | cut -f1); [ -n "$dvb" ] || dvb=0',
    "    printf 'DVOLBYTES\\t%s\\n' \"$dvb\"",
    "  fi",
    "  for cid in $($TO $PRIV docker ps -aq 2>/dev/null | head -n 40); do",
    '    $TO $PRIV docker inspect "$cid" --format "$FMT" 2>/dev/null | while IFS= read -r cl; do',
    '      [ -n "$cl" ] && printf \'C\\t%s\\t%s\\n\' "$cid" "$cl"',
    "    done",
    "    iid=$($TO $PRIV docker inspect -f '{{.Image}}' \"$cid\" 2>/dev/null)",
    '    if [ -n "$iid" ]; then',
    '      $TO $PRIV docker image inspect "$iid" --format "$IFMT" 2>/dev/null | while IFS= read -r jl; do',
    '        [ -n "$jl" ] && printf \'C\\t%s\\t%s\\n\' "$cid" "$jl"',
    "      done",
    "    fi",
    "  done",
    "fi",
    // Application MySQL accounts. Only user+host come back here; the password
    // HASHES are never read into our process — they are generated straight into a
    // 0600 SQL file on the target by a second script.
    "if command -v mysql >/dev/null 2>&1 || command -v mariadb >/dev/null 2>&1; then",
    "  $TO $PRIV mysql -N -B -e 'SELECT user, host FROM mysql.user' 2>/dev/null | head -n 80 | while IFS= read -r ml; do",
    '    [ -n "$ml" ] && printf \'MYACCT\\t%s\\n\' "$ml"',
    "  done",
    "fi",
    // Reverse-proxy / web-server config: which trees exist and which domains they
    // answer on. Without this the new box serves the stock nginx page.
    "if [ -d /etc/nginx ]; then",
    "  printf 'WEBCFG\\tnginx\\n'",
    "  $TO grep -rhoE 'server_name[[:space:]]+[^;]+' /etc/nginx 2>/dev/null | head -n 80 | while IFS= read -r sl; do",
    "    printf 'SRVNAME\\t%s\\n' \"$sl\"",
    "  done",
    "fi",
    "if [ -d /etc/apache2 ]; then printf 'WEBCFG\\tapache2\\n'; fi",
    "if [ -d /etc/httpd ]; then printf 'WEBCFG\\thttpd\\n'; fi",
    "if [ -d /etc/apache2 ] || [ -d /etc/httpd ]; then",
    "  $TO grep -rhoE '(ServerName|ServerAlias)[[:space:]]+[^[:space:]]+' /etc/apache2 /etc/httpd 2>/dev/null | head -n 80 | while IFS= read -r sl; do",
    "    printf 'SRVNAME\\t%s\\n' \"$sl\"",
    "  done",
    "fi",
    "if [ -d /etc/letsencrypt ]; then",
    "  printf 'LEDIR\\t1\\n'",
    "  for led in /etc/letsencrypt/live/*/; do",
