    "    leb=${led%/}; leb=${leb##*/}",
    '    [ -n "$leb" ] && printf \'TLSCERT\\t%s\\n\' "$leb"',
    "  done",
    "fi",
    "for crd in /var/spool/cron/crontabs /var/spool/cron; do",
    '  [ -d "$crd" ] || continue',
    '  for crf in "$crd"/*; do',
    '    [ -f "$crf" ] || continue',
    "    crb=${crf##*/}",
    "    printf 'CRONUSER\\t%s\\t%s\\n' \"$crb\" \"$crd\"",
    "  done",
    "done",
    "if [ -d /etc/cron.d ]; then",
    '  crn=$(ls -1 /etc/cron.d 2>/dev/null | wc -l); [ -n "$crn" ] || crn=0',
