    "awk -F: '($3>=1000 && $3<65534){printf \"PWGROUP\\t%s\\t%s\\n\",$1,$3}' /etc/group 2>/dev/null | head -n 40",
    "printf 'INVENTORY_OK\\t1\\n'",
    "",
  ].join("\n");
}

/** Parse the inventory probe's stdout. Every value is validated before it is kept. */
function parseInventory(stdout: string): SrcInventory {
  const inv = emptyInventory();
  const byId = new Map<string, SrcContainer>();

  for (const raw of (stdout ?? "").split("\n")) {
    const line = raw.replace(/\r$/, "");
    if (!line) continue;
    const parts = line.split("\t");
    const kind = parts[0];

    if (kind === "INVENTORY_OK") {
      inv.probed = true;
    } else if (kind === "HASDOCKER") {
      inv.hasDocker = true;
    } else if (kind === "IMAGE" && parts.length >= 2) {
      const seg = parts.slice(1).join("\t").split("|");
      const ref = clean(seg[0], 255);
      if (!validImageRef(ref) || inv.images.some((i) => i.ref === ref)) continue;
      if (inv.images.length >= 120) continue;
      inv.images.push({ ref, sizeBytes: parseDockerSize(seg[1] ?? ""), local: isLocalImageRef(ref) });
    } else if (kind === "DVOLBYTES" && parts.length >= 2) {
      const n = Number(parts[1]);
      if (Number.isFinite(n) && n > 0) inv.volumeBytes = n;
    } else if (kind === "C" && parts.length >= 3) {
      const cid = clean(parts[1], 64);
      if (!/^[0-9a-f]{6,64}$/i.test(cid)) continue;
      let c = byId.get(cid);
      if (!c) {
        if (byId.size >= 40) continue;
        c = {
          id: cid, name: "", image: "", state: "", restart: "", netmode: "", runuser: "",
          workdir: "", privileged: false, devices: 0, caps: [], cmd: "", entrypoint: "",
          imagecmd: "", imageentrypoint: "", project: "", ports: [], mounts: [], networks: [],
        };
        byId.set(cid, c);
      }
      const body = parts.slice(2).join("\t");
      const sp = body.indexOf(" ");
      const key = sp < 0 ? body : body.slice(0, sp);
      const val = sp < 0 ? "" : body.slice(sp + 1);
      switch (key) {
        case "name": c.name = clean(val, 128).replace(/^\//, ""); break;
        case "image": c.image = clean(val, 255); break;
        case "state": c.state = clean(val, 32); break;
        case "restart": c.restart = clean(val, 32); break;
        case "netmode": c.netmode = clean(val, 128); break;
        case "runuser": c.runuser = clean(val, 64); break;
        case "workdir": c.workdir = clean(val, 255); break;
        case "privileged": c.privileged = clean(val, 8) === "true"; break;
        case "devices": c.devices = Math.max(0, Number(clean(val, 8)) || 0); break;
        case "caps": c.caps = clean(val, 512).split(/\s+/).filter(Boolean).slice(0, 20); break;
        case "cmd": c.cmd = clean(val, 1024); break;
        case "entrypoint": c.entrypoint = clean(val, 1024); break;
        case "imagecmd": c.imagecmd = clean(val, 1024); break;
        case "imageentrypoint": c.imageentrypoint = clean(val, 1024); break;
        case "project": c.project = clean(val, 128); break;
        case "port": {
          // "<containerPort>/<proto> <hostIp|-> <hostPort>"
          const t = clean(val, 128).split(/\s+/);
          if (t.length < 3 || c.ports.length >= 20) break;
          const pm = /^(\d{1,5})\/(tcp|udp)$/.exec(t[0]);
          const hp = Number(t[2]);
          if (!pm || !Number.isInteger(hp) || hp < 1 || hp > 65535) break;
          const cp = Number(pm[1]);
          if (!Number.isInteger(cp) || cp < 1 || cp > 65535) break;
          const ip = t[1] === "-" ? "" : t[1];
          if (ip && !IPV4_RE.test(ip) && !IPV6_RE.test(ip)) break;
          c.ports.push({ containerPort: cp, proto: pm[2], hostIp: ip, hostPort: hp });
          break;
        }
        case "mount": {
          // "<type> <name|-> <source|-> <dest> <rw>"
          const t = clean(val, 1024).split(/\s+/);
          if (t.length < 5 || c.mounts.length >= 20) break;
          c.mounts.push({
            kind: t[0],
            name: t[1] === "-" ? "" : t[1],
            source: t[2] === "-" ? "" : t[2],
            dest: t[3],
            rw: t[4] === "true",
          });
          break;
        }
        case "net": {
          const n = clean(val, 128);
          if (n && c.networks.length < 8 && !c.networks.includes(n)) c.networks.push(n);
          break;
        }
      }
    } else if (kind === "MYACCT" && parts.length >= 3) {
      const u = clean(parts[1], 64);
      const h = clean(parts[2], 128);
      if (inv.mysqlAccounts.length >= 80) continue;
      if (!MYSQL_USER_RE.test(u) || !MYSQL_HOST_RE.test(h)) continue;
      if (MYSQL_SYSTEM_USERS.has(u) || u.startsWith("mysql.") || u.startsWith("mariadb.")) continue;
      if (inv.mysqlAccounts.some((a) => a.user === u && a.host === h)) continue;
      inv.mysqlAccounts.push({ user: u, host: h });
    } else if (kind === "WEBCFG" && parts.length >= 2) {
      const w = clean(parts[1], 16);
      if (["nginx", "apache2", "httpd"].includes(w) && !inv.webConfigs.includes(w)) inv.webConfigs.push(w);
    } else if (kind === "SRVNAME" && parts.length >= 2) {
      const toks = clean(parts.slice(1).join(" "), 512).split(/\s+/).slice(1, 12);
      for (const t of toks) {
        if (inv.domains.length >= 60) break;
        const d = normalizeDomain(t);
        if (d && !inv.domains.includes(d)) inv.domains.push(d);
      }
    } else if (kind === "LEDIR") {
      inv.hasLetsEncrypt = true;
    } else if (kind === "TLSCERT" && parts.length >= 2) {
      const d = normalizeDomain(parts[1]);
      if (d && inv.tlsCerts.length < 60 && !inv.tlsCerts.includes(d)) inv.tlsCerts.push(d);
    } else if (kind === "CRONUSER" && parts.length >= 3) {
      const n = clean(parts[1], 64);
      const dir = clean(parts[2], 128);
      if (!USER_RE.test(n) || !validPath(dir) || inv.cronUsers.length >= 40) continue;
      if (inv.cronUsers.some((c) => c.name === n)) continue;
      inv.cronUsers.push({ name: n, dir });
    } else if (kind === "CROND") {
      inv.hasCronD = true;
    } else if (kind === "PWUSER" && parts.length >= 6) {
      const name = clean(parts[1], 64);
      const uid = Number(parts[2]);
      const gid = Number(parts[3]);
      const home = clean(parts[4], 255);
      const shell = clean(parts[5], 255);
      if (inv.users.length >= 40) continue;
      if (!USER_RE.test(name)) continue;
      if (!Number.isInteger(uid) || uid < 1000 || uid >= 65534) continue;
      if (!Number.isInteger(gid) || gid < 0 || gid >= 65534) continue;
      if (!validPath(home)) continue;
      inv.users.push({ name, uid, gid, home, shell: LOGIN_SHELLS.has(shell) ? shell : NOLOGIN });
    } else if (kind === "PWGROUP" && parts.length >= 3) {
      const name = clean(parts[1], 64);
      const gid = Number(parts[2]);
      if (inv.groups.length >= 40 || !USER_RE.test(name)) continue;
      if (!Number.isInteger(gid) || gid < 1000 || gid >= 65534) continue;
      inv.groups.push({ name, gid });
    }
  }

  inv.containers = [...byId.values()].filter((c) => CONTNAME_RE.test(c.name) && validImageRef(c.image));
  inv.imageBytes = inv.images.reduce((n, i) => n + i.sizeBytes, 0);
  return inv;
}

// ===========================================================================
// TARGET STORAGE — attached block device + honest space arithmetic
// ===========================================================================
type BlockDev = { name: string; type: string; sizeBytes: number; fstype: string; mount: string };

/** Read `df` free bytes for a path (GNU `--output`, with a portable fallback). */
async function availBytes(conn: Client, path: string): Promise<number | null> {
  const r = await sh(conn, `df -B1 --output=avail ${path} 2>/dev/null | tail -n1`);
  let n = Number(clean(r.stdout, 32));
  if (!Number.isFinite(n) || n <= 0) {
    const r2 = await sh(conn, `df -B1 ${path} 2>/dev/null | awk 'NR==2{print $4}'`);
    n = Number(clean(r2.stdout, 32));
  }
  return Number.isFinite(n) && n > 0 ? n : null;
}

/** Parse `lsblk -b -P` KEY="value" output into rows. */
function parseLsblk(out: string): BlockDev[] {
  const rows: BlockDev[] = [];
  for (const line of (out ?? "").split("\n")) {
    if (!line.trim()) continue;
    const kv: Record<string, string> = {};
    for (const m of line.matchAll(/([A-Z]+)="([^"]*)"/g)) kv[m[1]] = m[2];
    if (!kv.NAME) continue;
    rows.push({
      name: clean(kv.NAME, 64),
      type: clean(kv.TYPE ?? "", 32),
      sizeBytes: Number(kv.SIZE) || 0,
      fstype: clean(kv.FSTYPE ?? "", 32),
      mount: clean(kv.MOUNTPOINT ?? kv.MOUNTPOINTS ?? "", 255),
    });
  }
  return rows;
}

/**
 * Find a block device on the TARGET that is attached but completely unused —
 * TYPE=disk, no filesystem, no mountpoint, no partitions and not the disk that
 * carries `/`. A real migration had a 20 GB volume sitting idle in exactly this
 * state while the root disk filled to 92% and the builds died.
 *
 * The name is validated against BLOCKDEV_RE and is additionally re-confirmed
 * blank with `blkid` (must FAIL, i.e. no signature at all) immediately before
 * anything is written — we will never mkfs a device that has any content.
 */
async function findUnusedDisk(conn: Client): Promise<BlockDev | null> {
  const ls = await sh(conn, `lsblk -b -P -o NAME,TYPE,SIZE,FSTYPE,MOUNTPOINT 2>/dev/null`);
  if (ls.code !== 0) return null;
  const rows = parseLsblk(ls.stdout);
  if (!rows.length) return null;

  // Belt and braces: never touch the disk that backs `/`.
  let rootDisk = "";
  const rs = await sh(conn, `findmnt -n -o SOURCE / 2>/dev/null | head -n1`);
  const rootSrc = clean(rs.stdout, 128);
  if (/^\/dev\/[A-Za-z0-9/_-]{1,64}$/.test(rootSrc)) {
    const pk = await sh(conn, `lsblk -no PKNAME ${rootSrc} 2>/dev/null | head -n1`);
    const d = clean(pk.stdout, 64);
    if (BLOCKDEV_RE.test(d)) rootDisk = d;
  }

  const candidates = rows.filter(
    (d) =>
      d.type === "disk" &&
      !d.fstype &&
      !d.mount &&
      d.name !== rootDisk &&
      BLOCKDEV_RE.test(d.name) &&
      d.sizeBytes >= MIN_EXTRA_DISK_BYTES &&
      // no partitions / LVM / crypt children carved out of it
      !rows.some((o) => o.name !== d.name && o.name.startsWith(d.name))
  );
  if (!candidates.length) return null;
  candidates.sort((a, b) => b.sizeBytes - a.sizeBytes);
  const pick = candidates[0];

  // Final confirmation that the device really is blank before we consider it.
  const blk = await sh(conn, `blkid /dev/${pick.name} >/dev/null 2>&1; echo $?`);
  if (clean(blk.stdout, 8) === "0") return null; // has a signature — hands off
  const inUse = await shOk(conn, `findmnt -S /dev/${pick.name} >/dev/null 2>&1`);
  if (inUse) return null;
  return pick;
}

/** Format + persistently mount a blank disk at EXTRA_DISK_MOUNT. Idempotent. */
async function prepareExtraDisk(conn: Client, dev: string): Promise<{ ok: boolean; detail: string }> {
  if (!BLOCKDEV_RE.test(dev)) return { ok: false, detail: "device name failed validation" };
  const mk = await sh(conn, `mkfs.ext4 -F -m 0 -L nxeon-data /dev/${dev} 2>&1`, INSTALL_TIMEOUT_MS);
  if (mk.code !== 0) return { ok: false, detail: `mkfs.ext4 failed: ${tailOf(mk)}` };

  const bl = await sh(conn, `blkid -s UUID -o value /dev/${dev} 2>/dev/null`);
  const uuid = clean(bl.stdout, 64);
  if (!UUID_RE.test(uuid)) return { ok: false, detail: "could not read a valid filesystem UUID" };

  await sh(conn, `mkdir -p ${EXTRA_DISK_MOUNT}`);
  // Persist by UUID so it survives a reboot; `nofail` keeps a detached volume
  // from wedging the boot. Idempotent — the grep guard makes a re-run a no-op.
  await sh(
    conn,
    `grep -q "UUID=${uuid} " /etc/fstab || printf 'UUID=%s %s ext4 defaults,nofail 0 2\\n' '${uuid}' '${EXTRA_DISK_MOUNT}' >> /etc/fstab`
  );
  const mnt = await sh(conn, `mountpoint -q ${EXTRA_DISK_MOUNT} || mount ${EXTRA_DISK_MOUNT} 2>&1 || mount /dev/${dev} ${EXTRA_DISK_MOUNT} 2>&1`, SETUP_TIMEOUT_MS);
  const mounted = await shOk(conn, `mountpoint -q ${EXTRA_DISK_MOUNT}`);
  if (!mounted) return { ok: false, detail: `mount failed: ${tailOf(mnt)}` };
  return { ok: true, detail: `formatted ext4 and mounted at ${EXTRA_DISK_MOUNT} (fstab UUID entry added)` };
}

/**
 * Move Docker's on-disk state onto the extra volume BEFORE anything is pulled,
 * loaded or built.
 *
 * BOTH stores are relocated. `/var/lib/containerd` is a SEPARATE store from
 * `/var/lib/docker`: with the containerd image store that `get.docker.com`
 * installs on Ubuntu 22.04, image layers and build ingest
 * (`io.containerd.content.v1.content/ingest/…`) live under containerd. In the
 * field, relocating only `/var/lib/docker` still let the root disk reach 100%
 * with 9.4 GB parked in `/var/lib/containerd`. Bind mounts are used for both, so
 * one mechanism covers both stores regardless of which image store is active and
 * without rewriting a daemon.json we do not own.
 *
 * Safety: the daemons are stopped first, data is rsynced (not moved) and the old
 * directory is only deleted after the bind mount is CONFIRMED live.
 */
async function relocateDockerStores(
  conn: Client,
  say: (line: string) => Promise<void>
): Promise<{ moved: string[]; failed: string[] }> {
  const moved: string[] = [];
  const failed: string[] = [];
  await sh(conn, `systemctl stop docker.socket docker containerd 2>/dev/null; true`, SETUP_TIMEOUT_MS);

  for (const store of DOCKER_STORES) {
    const leaf = store.slice(store.lastIndexOf("/") + 1);
    const dest = `${EXTRA_DISK_MOUNT}/${leaf}`;
    // Already relocated (a re-run, or the previous attempt got this far)?
    const already = await sh(conn, `findmnt -n -o SOURCE --target ${store} 2>/dev/null`);
    if (clean(already.stdout, 255).startsWith(EXTRA_DISK_MOUNT)) {
      moved.push(`${store} (already on ${EXTRA_DISK_MOUNT})`);
      continue;
    }
    await sh(conn, `mkdir -p ${dest} ${store}`);
    const cp = await sh(conn, `rsync -a --numeric-ids ${store}/ ${dest}/ 2>&1`, TRANSFER_TIMEOUT_MS);
    if (cp.code !== 0) {
      failed.push(`${store}: copy failed (${tailOf(cp)})`);
      continue;
    }
    await sh(
      conn,
      `grep -q " ${store} none bind" /etc/fstab || printf '%s %s none bind,nofail 0 0\\n' '${dest}' '${store}' >> /etc/fstab`
    );
    // Empty the original only AFTER the copy succeeded, and keep it aside until
    // the bind mount is confirmed.
    await sh(conn, `rm -rf ${store}.premigrate && mv ${store} ${store}.premigrate && mkdir -p ${store}`, SETUP_TIMEOUT_MS);
    const mnt = await sh(conn, `mount --bind ${dest} ${store} 2>&1`, SETUP_TIMEOUT_MS);
    const live = await shOk(conn, `mountpoint -q ${store}`);
    if (!live) {
      // Roll back cleanly — better a full root disk than a broken Docker.
      await sh(conn, `rmdir ${store} 2>/dev/null; mv ${store}.premigrate ${store} 2>/dev/null; true`);
      await sh(conn, `sed -i '\\| ${store} none bind|d' /etc/fstab 2>/dev/null; true`);
      failed.push(`${store}: bind mount failed (${tailOf(mnt)}) — left in place`);
      continue;
    }
    await sh(conn, `rm -rf ${store}.premigrate 2>/dev/null; true`, SETUP_TIMEOUT_MS);
    moved.push(store);
  }

  await sh(conn, `systemctl enable --now containerd 2>/dev/null; systemctl enable --now docker 2>/dev/null; true`, INSTALL_TIMEOUT_MS);
  const df = await sh(conn, `df -h ${DOCKER_STORES.join(" ")} 2>/dev/null | tail -n +2`);
  const dfTail = clean(df.stdout, 400).split("\n").map((l) => l.trim()).filter(Boolean).join(" | ");
  if (dfTail) await say(`  Docker storage now: ${dfTail}`);
  return { moved, failed };
}

/**
 * Reclaim build/ingest space. `docker builder prune -af` reclaimed 7.1 GB in the
 * field immediately after two image builds, which is the difference between a
 * working bring-up and ENOSPC. Dangling images go too. Deliberately NOT
 * `image prune -a` / `container prune` — those would delete images we have just
 * transferred but not yet started.
 */
async function pruneDocker(conn: Client): Promise<number> {
  const before = (await availBytes(conn, DOCKER_STORES[0])) ?? 0;
  await sh(conn, `docker builder prune -af >/dev/null 2>&1; docker image prune -f >/dev/null 2>&1; true`, INSTALL_TIMEOUT_MS);
  const after = (await availBytes(conn, DOCKER_STORES[0])) ?? 0;
  return Math.max(0, after - before);
}

// ===========================================================================
// DOCKER IMAGES — pull public, save/load everything else
// ===========================================================================
/**
 * Make one image exist on the TARGET.
 *
 *   already present → nothing (a re-run must not re-transfer gigabytes)
 *   public registry → `docker pull` (fast, and costs no source bandwidth)
 *   otherwise       → `docker save | gzip` on the source, streamed straight
 *                     through the SSH channel into `gunzip | docker load`
 *
 * The locally-built case is the one that silently broke a real migration: the
 * engine copied files and named volumes but never the IMAGE, so standalone
 * containers could never start. A pull that fails also falls back to save/load,
 * so a private registry the new box cannot authenticate to still works.
 *
 * `ref` is validated by validImageRef before it reaches any command; success is
 * confirmed with `docker image inspect` rather than trusting an exit code
 * through a pipeline.
 */
async function ensureImage(
  conn: Client,
  ref: string,
  local: boolean,
  onSource: (cmd: string) => string,
  priv: string,
  say: (line: string) => Promise<void>
): Promise<{ status: "present" | "pulled" | "loaded" | "failed"; detail: string }> {
  if (!validImageRef(ref)) return { status: "failed", detail: "image reference failed validation" };

  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
    return { status: "present", detail: "already on the new server" };
  }

  if (!local) {
    const pull = await sh(conn, `docker pull ${ref} 2>&1`, IMAGE_TIMEOUT_MS);
    if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
      return { status: "pulled", detail: "pulled from its registry" };
    }
    const why = tailOf(pull, 1, 120);
    await say(`  ${ref}: pull failed (${why || "unavailable"}) — transferring it from the old server instead.`);
  }

  // `docker save | gzip -1` on the source → `gunzip | docker load` on the target,
  // through the SSH channel we already hold. gzip -1 because these links are
  // usually faster than the CPU and the layers are mostly already compressed.
  const stream = `${onSource(`${priv}docker save ${ref} | gzip -1`)} | gunzip -c | docker load 2>&1`;
  const r = await sh(conn, stream, IMAGE_TIMEOUT_MS);
  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
    return { status: "loaded", detail: "transferred from the old server (docker save/load)" };
  }
  const why = tailOf(r, 2, 180);
  return {
    status: "failed",
    detail: isEnospc(why)
      ? "ran out of disk while loading the image"
      : `could not pull or transfer the image${why ? `: ${why}` : ""}`,
  };
}

// ===========================================================================
// STANDALONE CONTAINER RECREATION
// ===========================================================================
type ContainerPlan = {
  name: string;
  image: string;
  restart: string;
  ports: SrcPort[];
  binds: { src: string; dest: string; ro: boolean }[];
  volumes: { name: string; dest: string; ro: boolean }[];
  network: string; // "" = default bridge
  hostNetwork: boolean;
  runuser: string;
  workdir: string;
  privileged: boolean;
  caps: string[];
  /** Non-empty ⇒ we refuse to recreate and log what a human has to do instead. */
  blockers: string[];
};

/**
 * Turn one inspected source container into a plan we are willing to execute, or
 * into a list of BLOCKERS explaining why we will not.
 *
 * The rule is absolute: a value either passes its allowlist and goes into the
 * command, or the whole container is refused and logged. Nothing is sanitized,
 * nothing arbitrary is ever executed. That is why an overridden Cmd/Entrypoint
 * is a blocker — re-tokenising a shell string safely is not possible, so we say
 * so instead of guessing.
 */
function planContainer(c: SrcContainer): ContainerPlan {
  const blockers: string[] = [];
  const plan: ContainerPlan = {
    name: c.name, image: c.image, restart: "unless-stopped", ports: [], binds: [], volumes: [],
    network: "", hostNetwork: false, runuser: "", workdir: "", privileged: false, caps: [], blockers,
  };

  if (!CONTNAME_RE.test(c.name)) blockers.push("container name is not reproducible safely");
  if (!validImageRef(c.image)) blockers.push("image reference is not reproducible safely");

  // Restart policy: keep the source's, but upgrade "no"/unset to unless-stopped
  // so a reboot of the new server does not take the site down.
  plan.restart = RESTART_POLICIES.has(c.restart) && c.restart !== "no" ? c.restart : "unless-stopped";

  // Cmd / Entrypoint overrides cannot be re-tokenised safely.
  if (c.cmd !== c.imagecmd) blockers.push("it runs a custom command (docker run … <cmd>)");
  if (c.entrypoint !== c.imageentrypoint) blockers.push("it runs a custom entrypoint");
  if (c.devices > 0) blockers.push(`it maps ${c.devices} host device(s)`);

  for (const p of c.ports) {
    if (plan.ports.length >= 20) break;
    if (p.hostIp && !IPV4_RE.test(p.hostIp)) {
      blockers.push("a published port binds to an address we cannot validate");
      break;
    }
    plan.ports.push(p);
  }

  for (const m of c.mounts) {
    if (m.kind === "bind") {
      if (!validPath(m.source) || !validPath(m.dest)) {
        blockers.push(`bind mount ${clean(m.dest, 60) || "?"} uses a path we cannot validate`);
        continue;
      }
      plan.binds.push({ src: m.source, dest: m.dest, ro: !m.rw });
    } else if (m.kind === "volume") {
      if (!VOLNAME_RE.test(m.name) || !validPath(m.dest)) {
        blockers.push(`volume mount ${clean(m.dest, 60) || "?"} uses a name/path we cannot validate`);
        continue;
      }
      plan.volumes.push({ name: m.name, dest: m.dest, ro: !m.rw });
    } else if (m.kind) {
      blockers.push(`mount type "${clean(m.kind, 24)}" is not reproduced automatically`);
    }
  }

  // Networking: host mode and a single user-defined network are reproducible;
  // container:<id> sharing and multi-attach are not.
  if (c.netmode === "host") {
    plan.hostNetwork = true;
  } else if (c.netmode.startsWith("container:")) {
    blockers.push("it shares another container's network namespace");
  } else {
    const custom = c.networks.filter((n) => !BUILTIN_NETWORKS.has(n));
    if (custom.length > 1) blockers.push("it is attached to more than one custom network");
    else if (custom.length === 1) {
      if (!CONTNAME_RE.test(custom[0])) blockers.push("its network name is not reproducible safely");
      else plan.network = custom[0];
    }
  }

  if (c.runuser) {
    if (RUNUSER_RE.test(c.runuser)) plan.runuser = c.runuser;
    else blockers.push("its run-as user is not reproducible safely");
  }
  if (c.workdir && c.workdir !== "/") {
    if (validPath(c.workdir)) plan.workdir = c.workdir;
    else blockers.push("its working directory is not reproducible safely");
  }
  plan.privileged = c.privileged;
  for (const cap of c.caps) {
    if (plan.caps.length >= 20) break;
    if (CAP_RE.test(cap)) plan.caps.push(cap);
    else blockers.push("it adds a Linux capability we cannot validate");
  }
  return plan;
}

/** Assemble the `docker run` command. Every interpolated value is pre-validated. */
function buildRunCommand(p: ContainerPlan, envFile: string): string {
  const a: string[] = ["docker", "run", "-d", "--name", p.name, "--restart", p.restart];
  if (p.hostNetwork) a.push("--network", "host");
  else if (p.network) a.push("--network", p.network);
  if (p.runuser) a.push("--user", p.runuser);
  if (p.workdir) a.push("-w", p.workdir);
  if (p.privileged) a.push("--privileged");
  for (const c of p.caps) a.push("--cap-add", c);
  if (!p.hostNetwork) {
    for (const port of p.ports) {
      const hp = port.hostIp ? `${port.hostIp}:${port.hostPort}` : String(port.hostPort);
      a.push("-p", `${hp}:${port.containerPort}/${port.proto}`);
    }
  }
  for (const b of p.binds) a.push("-v", `${b.src}:${b.dest}${b.ro ? ":ro" : ""}`);
  for (const v of p.volumes) a.push("-v", `${v.name}:${v.dest}${v.ro ? ":ro" : ""}`);
  a.push("--env-file", envFile, p.image);
  return a.join(" ");
}

/** The per-container env probe. `name` is CONTNAME_RE-validated by the caller. */
function containerEnvScript(priv: string, name: string): string {
  return [
    "export LC_ALL=C",
    'PRIV="' + priv + '"',
    "$PRIV docker inspect --format '{{range .Config.Env}}{{println .}}{{end}}' " + name + " 2>/dev/null",
    "",
  ].join("\n");
}

// ===========================================================================
// WEB / REVERSE PROXY
// ===========================================================================
/**
 * A minimal, code-authored nginx vhost that proxies the customer's domains to
 * the local port their app already listens on. This is the difference between
 * "the app is running" and "the site works": a real migration brought the app up
 * on 127.0.0.1:3720 and port 80 still served the stock "Welcome to nginx" page
 * because no vhost existed for the domain.
 *
 * `domains` are DOMAIN_RE-validated and `port` is an integer, and the file is
 * written over SFTP — no shell is involved in producing it at all.
 */
function buildNginxVhost(domains: string[], port: number): string {
  return [
    "# Generated by the Nxeon migration engine.",
    "# Your app was migrated and listens on 127.0.0.1:" + port + "; this makes it",
    "# answer on your domain(s) over port 80. Safe to edit, replace, or extend",
    "# with TLS (certbot --nginx will add it in place).",
    "server {",
    "    listen 80;",
    "    listen [::]:80;",
    `    server_name ${domains.join(" ")};`,
    "",
    "    client_max_body_size 64m;",
    "",
    "    location / {",
    `        proxy_pass http://127.0.0.1:${port};`,
    "        proxy_http_version 1.1;",
    "        proxy_set_header Host $host;",
    "        proxy_set_header X-Real-IP $remote_addr;",
    "        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;",
    "        proxy_set_header X-Forwarded-Proto $scheme;",
    "        proxy_set_header Upgrade $http_upgrade;",
    '        proxy_set_header Connection "upgrade";',
    "        proxy_read_timeout 300s;",
    "    }",
    "}",
    "",
  ].join("\n");
}

/**
 * Open 80/443 when a firewall is actually active. ufw and firewalld are handled
 * because their rule model is declarative and idempotent. A hand-rolled iptables
 * DROP policy is only DETECTED and reported — blindly inserting ACCEPT rules
 * into someone's chain is exactly the kind of guesswork this engine refuses to
 * do, and the two commands to run are printed instead.
 */
async function openWebPorts(conn: Client): Promise<{ kind: string; detail: string }> {
  const ufw = await sh(conn, `command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | head -n1`);
  if (/Status:\s*active/i.test(ufw.stdout)) {
    await sh(conn, `ufw allow 80/tcp >/dev/null 2>&1; ufw allow 443/tcp >/dev/null 2>&1; true`);
    return { kind: "ufw", detail: "ufw is active — allowed 80/tcp and 443/tcp" };
  }
  const fwd = await sh(conn, `command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state 2>/dev/null`);
  if (/running/i.test(fwd.stdout)) {
    await sh(
      conn,
      `firewall-cmd --permanent --add-service=http >/dev/null 2>&1; firewall-cmd --permanent --add-service=https >/dev/null 2>&1; firewall-cmd --reload >/dev/null 2>&1; true`
    );
    return { kind: "firewalld", detail: "firewalld is running — allowed http and https" };
  }
  const ipt = await sh(conn, `iptables -S INPUT 2>/dev/null | head -n1`);
  if (/-P INPUT DROP/.test(ipt.stdout)) {
    return {
      kind: "iptables",
      detail:
        "a hand-written iptables policy is dropping input — run: iptables -I INPUT -p tcp --dport 80 -j ACCEPT; iptables -I INPUT -p tcp --dport 443 -j ACCEPT",
    };
  }
  return { kind: "none", detail: "no active host firewall — 80/443 are already reachable" };
}

/** HTTP-probe one URL and return its status code ("000" = nothing answered). */
async function httpCode(conn: Client, url: string, hostHeader?: string): Promise<string> {
  const hdr = hostHeader ? `-H 'Host: ${hostHeader}' ` : "";
  const r = await sh(
    conn,
    `curl -sS -o /dev/null -w '%{http_code}' --max-time 12 ${hdr}${url} 2>/dev/null || echo 000`,
    SETUP_TIMEOUT_MS
  );
  const code = clean(r.stdout, 16).split("\n").filter(Boolean).pop() ?? "000";
  return /^\d{3}$/.test(code) ? code : "000";
}

/**
 * "Serving" means the web stack answered with an HTTP status — 200/301/401/404
 * all prove the port is bound, the vhost matched and something is behind it.
 * Only a connection failure (000) or a 5xx counts as not serving.
 */
function isServing(code: string): boolean {
  return /^[1-4]\d\d$/.test(code);
}

// ===========================================================================
// MySQL APPLICATION ACCOUNTS
// ===========================================================================
/**
 * Generate `CREATE USER … / GRANT …` for the source's APPLICATION accounts.
 *
 * The dump deliberately skips the `mysql` system schema (restoring it across
 * engine versions corrupts the import), which silently left every application DB
 * user behind: the data arrived but the app got access-denied. This closes that
 * hole without reintroducing the system-schema problem.
 *
 * Password material NEVER enters this process: the script runs on the source and
 * its stdout is redirected straight into a 0600 file on the target, which is
 * applied with `mysql < file` and then shredded. `SHOW CREATE USER` preserves the
 * existing hash (`IDENTIFIED WITH … AS '<hash>'` / `IDENTIFIED BY PASSWORD`), so
 * application passwords keep working unchanged. `IF NOT EXISTS` makes a re-run
 * idempotent instead of duplicating or resetting accounts.
 *
 * Every user/host pair is MYSQL_USER_RE / MYSQL_HOST_RE validated, and MySQL's
 * own root/maintenance accounts are excluded before this is ever called.
 */
function mysqlGrantsScript(priv: string, accounts: { user: string; host: string }[]): string {
  const specs = accounts.map((a) => `${a.user}:${a.host}`).join(" ");
  return [
    "export LC_ALL=C",
    'PRIV="' + priv + '"',
    "printf -- '-- application accounts migrated by Nxeon\\n'",
    "for spec in " + specs + "; do",
    "  u=${spec%%:*}",
    "  h=${spec#*:}",
    '  $PRIV mysql -N -B -e "SHOW CREATE USER \'$u\'@\'$h\'" 2>/dev/null | sed -e \'s/^CREATE USER /CREATE USER IF NOT EXISTS /\' -e \'s/$/;/\'',
    '  $PRIV mysql -N -B -e "SHOW GRANTS FOR \'$u\'@\'$h\'" 2>/dev/null | sed -e \'s/$/;/\'',
    "done",
    "",
  ].join("\n");
}

// ---------------------------------------------------------------------------

/**
 * Perform a real lift-and-shift migration. Throws only on a FATAL setup error

// Run a fixed command ON THE SOURCE and capture its output on the target.
const onSource = (cmd: string) => `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} '${cmd}'`;
// Run a FIXED, code-authored SCRIPT on the source by streaming it in over
// STDIN (`ssh … sh -s < file`) instead of squeezing it through argv. The body
// is written to the target over SFTP as bytes, so the script never passes
// through a shell as a string and needs no quoting at all — which is what lets
// the inventory/grant probes be non-trivial without opening an injection hole.
const onSourceScript = (scriptPath: string) =>
  `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} sh -s < ${scriptPath}`;
let scriptSeq = 0;
const putScript = async (body: string): Promise<string> => {
  const p = `${work}/src-${++scriptSeq}.sh`;
  await sftpWrite(sftp, p, body);
  return p;
};

