input.new_string:
// rsync pull from the source over the sshpass-driven ssh (used everywhere below).
//
//   -a            archive: recurse and preserve permissions, ownership, group,
//                 timestamps, symlinks and device nodes. This is what keeps a
//                 web root's mode bits and a service account's ownership intact.
//   -H            preserve hard links within the copied tree.
//   --numeric-ids ownership travels as raw uid/gid, so it is correct even
//                 before the matching accounts exist on the new server (they are
//                 recreated in step 5e, which then gives those numbers names).
//   -z            compress in flight.
//
// There are deliberately NO --exclude/--filter rules: rsync copies dotfiles by
// default, so `.env`, `.htaccess`, `.git`, `.npmrc` and every other hidden file
// inside a selected directory transfers. Losing a `.env` would break the app
// just as thoroughly as losing its database.
const rsyncPull = (remotePath: string, localParent: string) =>
  `sshpass -f ${passFile} rsync -aHz --numeric-ids --timeout=1200 -e 'ssh ${sshOpts}' ${srcSpec}:${remotePath} ${localParent}/`;

// pg_dumpall (unlike mysqldump of user schemas) emits the cluster's
// globals — every CREATE ROLE with its stored password and its grants
// — so PostgreSQL application logins come across automatically and
// need no equivalent of the MySQL account step below.
push({
  step: "Migrate PostgreSQL databases",
  status: "copied",
  detail: "dumped via source postgres peer auth and imported on the target, including database roles/logins and their passwords (pg_dumpall carries cluster globals)",
});
await report(64, "Migrating databases…", `  PostgreSQL databases, roles and logins dumped and imported.`);

// ---- 8b. MySQL application accounts + grants --------------------------
// Silent app-breaker: the dump above intentionally skips the `mysql` system
// schema, so the DATA arrives but the accounts the apps log in as do not, and
// every connection fails with access-denied. Reproduce just the application
// accounts — never root or MySQL's own maintenance logins, which would
// overwrite the new server's own credentials.
//
// Password hashes never enter this process: the generator runs on the source
// and its output is redirected straight into a 0600 file on the target, which
// is applied and then shredded. Nothing from it is ever logged.
if (plan.dbEngines.includes("mysql") && inv.mysqlAccounts.length > 0) {
  await report(66, "Migrating database users…", `Recreating ${inv.mysqlAccounts.length} application database account(s) with their existing passwords.`);
  const usersSql = `${work}/dumps/mysql-users.sql`;
  const genScript = await putScript(mysqlGrantsScript(priv, inv.mysqlAccounts));
  const gen = await sh(conn, `(umask 077; ${onSourceScript(genScript)} > ${usersSql} 2>/dev/null)`, TRANSFER_TIMEOUT_MS);
  const hasSql = await shOk(conn, `test -s ${usersSql}`);
  if (gen.code !== 0 || !hasSql) {
    push({
      step: "Migrate database users",
      status: "failed",
      detail: `could not read the old server's database accounts — recreate ${inv.mysqlAccounts.length} MySQL user(s) and their grants by hand, or your apps will get access-denied`,
    });
  } else {
    // --force: one unsupported statement (e.g. an auth plugin the target's
    // engine lacks) must not abandon the remaining accounts.
    const ap = await sh(conn, `mysql --force < ${usersSql} 2>${work}/dumps/mysql-users.err`, TRANSFER_TIMEOUT_MS);
    // Confirm by ASKING THE TARGET which of the accounts now exist, rather
    // than trusting an exit code.
    const check = await sh(conn, `mysql -N -B -e "SELECT user, host FROM mysql.user" 2>/dev/null`);
    const present = new Set(
      clean(check.stdout, 8000)
        .split("\n")
        .map((l) => l.split(/\s+/).slice(0, 2).join("@"))
    );
    const landed = inv.mysqlAccounts.filter((a) => present.has(`${a.user}@${a.host}`));
    const missing = inv.mysqlAccounts.filter((a) => !present.has(`${a.user}@${a.host}`));
    // NEVER echo the error file — it can quote statements. Only count/classify.
    const errCount = Number(
      clean((await sh(conn, `grep -c '^ERROR' ${work}/dumps/mysql-users.err 2>/dev/null`)).stdout, 8)
    ) || 0;
    if (landed.length && !missing.length) {
      push({
        step: `Migrate ${landed.length} database user(s)`,
        status: "running",
        detail: "application database accounts and grants recreated with their existing passwords — apps can log in unchanged",
      });
      await report(67, "Migrating database users…", `  ${landed.length} database account(s) recreated with their original passwords.`);
    } else if (landed.length) {
      push({
        step: "Migrate database users",
        status: "copied",
        detail: `${landed.length} of ${inv.mysqlAccounts.length} account(s) recreated; ${missing.map((m) => m.user).join(", ")} could not be reproduced (likely an auth plugin this engine does not support) — recreate ${missing.length === 1 ? "it" : "them"} and re-grant by hand`,
      });
    } else {
      push({
        step: "Migrate database users",
        status: "failed",
        detail: `none of the ${inv.mysqlAccounts.length} application database account(s) could be recreated${errCount ? ` (${errCount} statement error(s))` : ""}${ap.code !== 0 ? "" : ""} — apps that log in as their own DB user will get access-denied until they are created by hand`,
      });
    }
  }
}

// ---- 8c. Scheduled jobs (crontabs) ------------------------------------
// Backups, queue workers and cache warmers all live here and are invisible
// until they silently stop happening. --ignore-existing so the new server's
// own distro cron entries are never clobbered.
if (inv.cronUsers.length || inv.hasCronD) {
  const dirs = [...new Set(inv.cronUsers.map((c) => c.dir))];
  let copied = 0;
  for (const d of dirs) {
    await sh(conn, `mkdir -p ${d}`);
    const r = await sh(conn, rsyncPull(`${d}/`, d), TRANSFER_TIMEOUT_MS);
    if (r.code === 0) copied += inv.cronUsers.filter((c) => c.dir === d).length;
  }
  let cronD = false;
  if (inv.hasCronD) {
    await sh(conn, `mkdir -p /etc/cron.d`);
    const r = await sh(
      conn,
      `sshpass -f ${passFile} rsync -aHz --numeric-ids --ignore-existing --timeout=600 -e 'ssh ${sshOpts}' ${srcSpec}:/etc/cron.d/ /etc/cron.d/`,
      TRANSFER_TIMEOUT_MS
    );
    cronD = r.code === 0;
  }
  // Crontab files must be 0600 and owned by the crontab group or cron ignores them.
  for (const d of dirs) await sh(conn, `chmod 600 ${d}/* 2>/dev/null; true`);
  await sh(conn, `systemctl enable --now cron 2>/dev/null || systemctl enable --now crond 2>/dev/null || true`);
  if (copied || cronD) {
    push({
      step: "Scheduled jobs (cron)",
      status: "copied",
      detail: `${copied} user crontab(s)${cronD ? " and /etc/cron.d entries" : ""} copied and cron enabled — check any job that references a path or host that changed`,
    });
    await report(68, "Copying scheduled jobs…", `  ${copied} crontab(s)${cronD ? " + /etc/cron.d" : ""} copied.`);
  }
}

// ---- 8d. Existing TLS certificates ------------------------------------
// Copying /etc/letsencrypt (certs, keys, and the renewal config that names
// the authenticator) means HTTPS keeps working the instant DNS moves, instead
// of the site going from "working with TLS" to "browser warning".
if (inv.hasLetsEncrypt) {
  await sh(conn, `mkdir -p /etc/letsencrypt`);
  const r = await sh(conn, rsyncPull("/etc/letsencrypt/", "/etc/letsencrypt"), TRANSFER_TIMEOUT_MS);
  if (r.code === 0) {
    const names = inv.tlsCerts.slice(0, 6).join(", ");
    push({
      step: "TLS certificates",
      status: "copied",
      detail: `/etc/letsencrypt copied${names ? ` (${names})` : ""} — HTTPS keeps working; automatic renewal resumes once this server's IP is what the domain resolves to`,
    });
    await report(69, "Copying certificates…", `  Let's Encrypt certificates copied${names ? `: ${names}` : ""}.`);
  } else {
    push({ step: "TLS certificates", status: "failed", detail: "could not copy /etc/letsencrypt — re-issue certificates after DNS points here" });
  }
}

// ---- 9. Docker Compose bring-up ---------------------------------------

