}
// Standalone (non-compose) containers: log a run-equivalent, never auto-run
// an arbitrary source-supplied image. Honest — these are left for the user.
for (const c of plan.containers) {
  if (!c.name || !c.image) continue;
  const portsHint = c.ports ? ` ports[${c.ports}]` : "";
  const mountsHint = c.mounts.length ? ` mounts[${c.mounts.join(",")}]` : "";
  push({
    step: `Container ${c.name}`,
    status: "copied",
    detail: `recreate on the new server: image ${c.image}${portsHint}${mountsHint}`,
  });
}

input.new_string:
// ---- 9a. Docker IMAGES -------------------------------------------------
// The migration used to copy files and named volumes but never the images, so
// standalone containers whose image was built locally (`studionexis/frontend:
// latest` — no registry host, exists nowhere but the old server) could never
// start on the new box. Every image any container references is made to exist
// here: pulled when it genuinely comes from a registry, otherwise streamed
// across with `docker save | gzip` → `gunzip | docker load`.
//
// This runs BEFORE compose up on purpose: with the images already present
// under the tags compose expects, `compose up` reuses them instead of
// rebuilding — which is both far more reliable and the difference between
// fitting on the disk and not.
const imagesNeeded: SrcImage[] = [];
if (plan.hasContainers && srcContainers.length) {
  const seen = new Set<string>();
  for (const c of srcContainers) {
    if (!validImageRef(c.image) || seen.has(c.image)) continue;
    seen.add(c.image);
    const known = inv.images.find((i) => i.ref === c.image);
    imagesNeeded.push({ ref: c.image, sizeBytes: known?.sizeBytes ?? 0, local: isLocalImageRef(c.image) });
  }
  // Locally-built images first (nothing else can supply them), then smallest
  // first so a tight disk still gets the most containers running.
  imagesNeeded.sort((a, b) => Number(b.local) - Number(a.local) || a.sizeBytes - b.sizeBytes);
}

if (imagesNeeded.length) {
  const localCount = imagesNeeded.filter((i) => i.local).length;
  await report(
    70,
    "Transferring container images…",
    `Making ${imagesNeeded.length} container image(s) available on the new server` +
      (localCount ? ` — ${localCount} of them are built on the old server and are transferred directly.` : ".")
  );

  // Re-check free space HERE, not just at the start: the file copy and the
  // database import have both landed since the pre-flight ran.
  let dockerAvail = await availBytes(conn, DOCKER_STORES[0]);
  const phaseNeed = inv.imageBytes * IMAGE_OVERHEAD_FACTOR + IMAGE_PHASE_FLOOR;
  if (dockerAvail !== null && dockerAvail < phaseNeed) {
    const reclaimed = await pruneDocker(conn);
    dockerAvail = await availBytes(conn, DOCKER_STORES[0]);
    await report(
      70,
      "Transferring container images…",
      `  Freed ${human(reclaimed)} of build cache; ${human(dockerAvail ?? 0)} free where Docker stores images (about ${human(phaseNeed)} wanted).`
    );
  }

  let transferred = 0;
  let budget = MAX_IMAGE_TRANSFER_BYTES;
  let idx = 0;
  for (const img of imagesNeeded) {
    idx++;
    const pct = 70 + Math.round((idx / imagesNeeded.length) * 3); // 70 → 73
    if (img.sizeBytes > MAX_SINGLE_IMAGE_BYTES) {
      push({
        step: `Image ${img.ref}`,
        status: "failed",
        detail: `${human(img.sizeBytes)} is above the ${human(MAX_SINGLE_IMAGE_BYTES)} per-image transfer limit — move it by hand (docker save/load) or push it to a registry`,
      });
      continue;
    }
    if (img.local && img.sizeBytes > budget) {
      push({
        step: `Image ${img.ref}`,
        status: "failed",
        detail: `the ${human(MAX_IMAGE_TRANSFER_BYTES)} image-transfer budget for one migration is used up — transfer this image by hand`,
      });
      continue;
    }

    // Per-image space gate: refuse to START an operation that cannot finish,
    // pruning the build cache first (7.1 GB was reclaimable in the field).
    const cost = Math.max(img.sizeBytes * IMAGE_OVERHEAD_FACTOR, 256 * MiB);
    let avail = await availBytes(conn, DOCKER_STORES[0]);
    if (avail !== null && avail < cost + IMAGE_PHASE_FLOOR) {
      await pruneDocker(conn);
      avail = await availBytes(conn, DOCKER_STORES[0]);
    }
    if (avail !== null && avail < cost + IMAGE_PHASE_FLOOR) {
      push({
        step: `Image ${img.ref}`,
        status: "failed",
        detail: `not enough disk to install it (needs about ${human(cost)}, only ${human(avail)} free) — add storage, then run: docker pull ${img.ref}`,
      });
      await report(pct, "Transferring container images…", `  ${img.ref}: skipped — not enough disk space.`);
      continue;
    }

    let res = await ensureImage(conn, img.ref, img.local, onSource, priv, (l) => report(pct, "Transferring container images…", l));
    // ENOSPC is the dominant real-world failure — reclaim and retry once.
    if (res.status === "failed" && isEnospc(res.detail)) {
      const reclaimed = await pruneDocker(conn);
      await report(pct, "Transferring container images…", `  Disk filled up — freed ${human(reclaimed)} of build cache and retrying ${img.ref}.`);
      res = await ensureImage(conn, img.ref, img.local, onSource, priv, (l) => report(pct, "Transferring container images…", l));
    }

    if (res.status === "failed") {
      push({ step: `Image ${img.ref}`, status: "failed", detail: res.detail });
      await report(pct, "Transferring container images…", `  ${img.ref}: ${res.detail}.`);
    } else {
      if (res.status === "loaded") {
        transferred++;
        budget -= img.sizeBytes;
      }
      if (res.status !== "present") {
        await report(pct, "Transferring container images…", `  ${img.ref} (${human(img.sizeBytes)}): ${res.detail}.`);
      }
    }
  }
  if (transferred) {
    push({
      step: `Transfer ${transferred} container image(s)`,
      status: "running",
      detail: "locally-built images copied from the old server with docker save/load, so containers can start here",
    });
  }
}

// ---- 9b. Docker Compose bring-up ---------------------------------------
if (plan.composeDirs.length) {
  await report(74, "Starting containers…", `Bringing up ${plan.composeDirs.length} Docker Compose project(s).`);
  for (const dir of plan.composeDirs) {
    if (!composeCmd) {
      push({ step: `Compose up ${dir}`, status: "copied", detail: `Docker Compose is not installed on the new server — install it and run 'docker compose up -d' in ${dir}` });
      continue;
    }
    // dir has already been copied to the same path in step 6, and its images
    // were made to exist in 9a, so this reuses them instead of rebuilding.
    const run = async () =>
      sh(conn, `sh -c 'cd ${dir} && ${composeCmd} up -d' >/dev/null 2>${work}/dumps/compose.err`, TRANSFER_TIMEOUT_MS);
    let r = await run();
    let err = clean((await sh(conn, `tail -c 400 ${work}/dumps/compose.err 2>/dev/null`)).stdout, 400);
    if (r.code !== 0 && isEnospc(err)) {
      const reclaimed = await pruneDocker(conn);
      await report(76, "Starting containers…", `  ${dir} ran out of disk — freed ${human(reclaimed)} of build cache and retrying.`);
      r = await run();
      err = clean((await sh(conn, `tail -c 400 ${work}/dumps/compose.err 2>/dev/null`)).stdout, 400);
    }
    if (r.code === 0) {
      push({ step: `Compose up ${dir}`, status: "running", detail: `${composeCmd} up -d succeeded` });
      await report(78, "Starting containers…", `  compose up in ${dir}: started.`);
    } else {
      const why = isEnospc(err)
        ? "the new server ran out of disk space while building/pulling its images"
        : clean(err.split("\n").filter(Boolean).slice(-1)[0] ?? "", 200);
      push({ step: `Compose up ${dir}`, status: "failed", detail: `could not start${why ? `: ${why}` : ""} — run '${composeCmd} up -d' in ${dir}` });
      await report(78, "Starting containers…", `  compose up in ${dir} failed — left for manual start.`);
    }
  }
}

// ---- 9c. Standalone (non-Compose) containers ---------------------------
// These used to be logged as "recreate on the new server" and nothing else.
// Now that their images exist, they are recreated faithfully — same name,
// image, published ports, environment, restart policy, mounts and network.
//
// The safety rule is absolute: every value is validated against the
// allowlists above before it enters the command, and anything we cannot
// reproduce EXACTLY (a custom command/entrypoint, a mapped device, a shared
// network namespace, an unvalidatable path) makes us refuse the container and
// say why. We never execute an unvalidated string from the source.
//
// Environment variables are handled without ever putting a secret in a
// command line or in this process: they are read on the source straight into
// a 0600 file on the target and consumed with `--env-file`.
const standalone = srcContainers.filter((c) => !c.project);
if (standalone.length) {
  await report(79, "Recreating containers…", `Recreating ${standalone.length} standalone container(s) from the old server.`);
  for (const c of standalone) {
    if (c.state !== "running") {
      push({ step: `Container ${c.name}`, status: "skipped", detail: `it was not running on the old server (${c.state || "stopped"}) — not started here either` });
      continue;
    }
    const p = planContainer(c);

    // Idempotency: a re-run must never create a second copy.
    if (await shOk(conn, `docker inspect ${p.name} >/dev/null 2>&1`)) {
      await sh(conn, `docker start ${p.name} >/dev/null 2>&1; true`, SETUP_TIMEOUT_MS);
      const up = await sh(conn, `docker inspect -f '{{.State.Running}}' ${p.name} 2>/dev/null`);
      const running = clean(up.stdout, 16) === "true";
      push({
        step: `Container ${p.name}`,
        status: running ? "running" : "copied",
        detail: running ? "already present on the new server and running" : "already present but not running — check `docker logs`",
      });
      continue;
    }

    if (p.blockers.length) {
      push({
        step: `Container ${p.name}`,
        status: "copied",
        detail: `not recreated automatically because ${p.blockers.slice(0, 3).join("; ")} — start it by hand from image ${p.image}`,
      });
      await report(80, "Recreating containers…", `  ${p.name}: left for you — ${p.blockers[0]}.`);
      continue;
    }
    if (!(await shOk(conn, `docker image inspect ${p.image} >/dev/null 2>&1`))) {
      push({ step: `Container ${p.name}`, status: "failed", detail: `its image ${p.image} could not be made available on the new server — see the image step above` });
      continue;
    }
    // A bind mount whose host directory never arrived would start the app
    // against an EMPTY directory and look healthy while losing data. Refuse.
    const missing: string[] = [];
    for (const b of p.binds) if (!(await shOk(conn, `test -e ${b.src}`))) missing.push(b.src);
    if (missing.length) {
      push({
        step: `Container ${p.name}`,
        status: "copied",
        detail: `not started because the folder(s) it mounts were not migrated: ${missing.slice(0, 3).join(", ")} — add them to the migration (or create them) and start it by hand`,
      });
      continue;
    }

    if (p.network) await sh(conn, `docker network inspect ${p.network} >/dev/null 2>&1 || docker network create ${p.network} >/dev/null 2>&1; true`);
    for (const v of p.volumes) await sh(conn, `docker volume create ${v.name} >/dev/null 2>&1; true`);

    const envFile = `${work}/env/${p.name}.env`;
    const envScript = await putScript(containerEnvScript(priv, p.name));
    await sh(conn, `(umask 077; ${onSourceScript(envScript)} > ${envFile} 2>/dev/null); touch ${envFile}; chmod 600 ${envFile}`, SETUP_TIMEOUT_MS);
    // Keep only well-formed KEY=VALUE lines — done ON THE TARGET with grep so
    // the values are never read into this process or into a log.
    await sh(conn, `grep -E '^[A-Za-z_][A-Za-z0-9_]*=' ${envFile} > ${envFile}.f 2>/dev/null; mv -f ${envFile}.f ${envFile} 2>/dev/null; chmod 600 ${envFile}; true`);

    const runCmd = buildRunCommand(p, envFile);
    let r = await sh(conn, `${runCmd} >/dev/null 2>${work}/dumps/run.err`, IMAGE_TIMEOUT_MS);
    let err = clean((await sh(conn, `tail -c 300 ${work}/dumps/run.err 2>/dev/null`)).stdout, 300);
    if (r.code !== 0 && isEnospc(err)) {
      await pruneDocker(conn);
      await sh(conn, `docker rm -f ${p.name} >/dev/null 2>&1; true`);
      r = await sh(conn, `${runCmd} >/dev/null 2>${work}/dumps/run.err`, IMAGE_TIMEOUT_MS);
      err = clean((await sh(conn, `tail -c 300 ${work}/dumps/run.err 2>/dev/null`)).stdout, 300);
    }
    const up = await sh(conn, `docker inspect -f '{{.State.Running}}' ${p.name} 2>/dev/null`);
    if (clean(up.stdout, 16) === "true") {
      const portList = p.ports.map((x) => `${x.hostIp || "0.0.0.0"}:${x.hostPort}→${x.containerPort}`).join(", ");
      push({
        step: `Container ${p.name}`,
        status: "running",
        detail: `recreated and running (image ${p.image}, restart=${p.restart}${portList ? `, ports ${portList}` : ""})`,
      });
      await report(81, "Recreating containers…", `  ${p.name}: recreated and running.`);
    } else {
      push({
        step: `Container ${p.name}`,
        status: "failed",
        detail: `could not start${err ? `: ${clean(err.split("\n").filter(Boolean).slice(-1)[0] ?? "", 160)}` : ""} — check \`docker logs ${p.name}\``,
      });
      await report(81, "Recreating containers…", `  ${p.name}: did not start — left for you.`);
    }
  }
}

// ---- 9d. Reclaim build/ingest space ------------------------------------
if (plan.hasContainers) {
  const reclaimed = await pruneDocker(conn);
  if (reclaimed > 64 * MiB) {
    await report(83, "Tidying up…", `  Reclaimed ${human(reclaimed)} of Docker build cache and dangling images.`);
  }
}

