} else if (kind === "PWGROUP" && parts.length >= 3) {

/**
 * ONE vhost's INTENT as it exists on the source: which names it answers on,
 * whether it proxies (and to which local port) or serves a document root, and
 * whether it terminated TLS.
 */
type SrcVhost = {
  names: string[];
  wildcard: string; // base domain of a `*.base` server_name, else ""
  proxyPort: number; // resolved local upstream port, 0 when it serves files
  root: string;
  ssl: boolean;
  isDefault: boolean;
  ports: number[];
};

/**
 * Parse `nginx -T` (the source's FULLY MERGED, running configuration) into vhost
 * intent.
 *
 * WHY intent and not the files: blind-copying the source's `/etc/nginx` over the
 * target's is what broke a real cutover in seven separate ways. The source was
 * HestiaCP on nginx 1.25; the target is stock Ubuntu nginx 1.18. The copy
 * replaced the target's `nginx.conf` (so its `include sites-enabled/*` vanished
 * and any vhost written there was silently ignored), carried `listen
 * <old-ip>:80` into 21 files (`bind() to <old ip>:80 failed` — nginx would not
 * start at all), referenced certificates and `options-ssl-nginx.conf` that do
 * not exist here, used `http2 on;` which 1.18 rejects as an unknown directive,
 * pointed at log directories that do not exist, and installed a catch-all
 * default server proxying to a dead port that answered 502 for every request.
 *
 * So: read the source's intent, then GENERATE a clean configuration in the
 * target's own dialect, leaving the target's nginx.conf and include layout
 * untouched. The source tree is kept as a read-only reference copy for the
 * customer instead of being installed.
 */
function parseNginxDump(lines: string[]): SrcVhost[] {
  const upstreams = new Map<string, number>();
  const out: SrcVhost[] = [];
  let depth = 0;
  let cur: SrcVhost | null = null;
  let curDepth = 0;
  let upName = "";
  let upDepth = -1;

  for (const raw of lines) {
    const line = clean(raw, 1000).trim();
    if (!line || line.startsWith("#")) continue;
    const opens = (line.match(/\{/g) ?? []).length;
    const closes = (line.match(/\}/g) ?? []).length;
    const d = line.replace(/;\s*$/, "").trim();

    // upstream blocks, so `proxy_pass http://myapp` can be resolved to a port
    const um = /^upstream\s+([A-Za-z0-9._-]{1,64})\s*\{/.exec(line);
    if (!cur && um) {
      upName = um[1];
      upDepth = depth;
      depth += opens - closes;
      continue;
    }
    if (upName) {
      const sm = /^server\s+([A-Za-z0-9._-]+):(\d{1,5})/.exec(d);
      if (sm && !upstreams.has(upName)) {
        const p = Number(sm[2]);
        if (Number.isInteger(p) && p >= 1 && p <= 65535) upstreams.set(upName, p);
      }
      depth += opens - closes;
      if (depth <= upDepth) {
        upName = "";
        upDepth = -1;
      }
      continue;
    }

    if (!cur && /^server\s*\{/.test(line)) {
      cur = { names: [], wildcard: "", proxyPort: 0, root: "", ssl: false, isDefault: false, ports: [] };
      curDepth = depth;
      depth += opens - closes;
      continue;
    }

    if (cur) {
      let m: RegExpExecArray | null;
      if ((m = /^server_name\s+(.+)$/.exec(d))) {
        for (const t of m[1].split(/\s+/).slice(0, 12)) {
          if (t === "_" || t === "localhost") {
            cur.isDefault = true;
            continue;
          }
          if (t.startsWith("*.")) {
            const b = normalizeDomain(t.slice(2));
            if (b) {
              cur.wildcard = b;
              if (!cur.names.includes(b)) cur.names.push(b);
            }
            continue;
          }
          const dm = normalizeDomain(t);
          if (dm && !cur.names.includes(dm)) cur.names.push(dm);
        }
      } else if ((m = /^listen\s+(.+)$/.exec(d))) {
        const toks = m[1].split(/\s+/);
        const addr = toks[0];
        let port = 0;
        if (/^\d{1,5}$/.test(addr)) port = Number(addr);
        else {
          const pm = /^(?:\[[0-9a-fA-F:]+\]|[0-9.]+):(\d{1,5})$/.exec(addr);
          if (pm) port = Number(pm[1]);
        }
        if (Number.isInteger(port) && port >= 1 && port <= 65535 && !cur.ports.includes(port)) cur.ports.push(port);
        if (toks.includes("ssl") || port === 443) cur.ssl = true;
        if (toks.includes("default_server") || toks.includes("default")) cur.isDefault = true;
      } else if ((m = /^root\s+(\S+)$/.exec(d))) {
        const p = m[1].replace(/\/$/, "");
        if (validPath(p)) cur.root = p;
      } else if ((m = /^proxy_pass\s+(\S+)$/.exec(d))) {
        const pm = /^https?:\/\/([A-Za-z0-9._-]+)(?::(\d{1,5}))?/.exec(m[1]);
        if (pm && !cur.proxyPort) {
          if (pm[2]) {
            const p = Number(pm[2]);
            if (Number.isInteger(p) && p >= 1 && p <= 65535) cur.proxyPort = p;
          } else {
            const up = upstreams.get(pm[1]);
            if (up) cur.proxyPort = up;
          }
        }
      }
      depth += opens - closes;
      if (depth <= curDepth) {
        if (cur.names.length) out.push(cur);
        cur = null;
      }
      continue;
    }

    depth += opens - closes;
    if (depth < 0) depth = 0;
  }
  return out;
}

/** Same idea for Apache, from a grepped stream of its vhost-shaped directives. */
function parseApacheDump(lines: string[]): SrcVhost[] {
  const out: SrcVhost[] = [];
  let cur: SrcVhost | null = null;
  for (const raw of lines) {
    const line = clean(raw, 1000).trim();
    if (!line) continue;
    if (/^<VirtualHost/i.test(line)) {
      cur = { names: [], wildcard: "", proxyPort: 0, root: "", ssl: false, isDefault: false, ports: [] };
      const pm = /:(\d{1,5})>?\s*$/.exec(line);
      if (pm) {
        const p = Number(pm[1]);
        if (Number.isInteger(p) && p >= 1 && p <= 65535) {
          cur.ports.push(p);
          if (p === 443) cur.ssl = true;
        }
      }
      continue;
    }
    if (!cur) continue;
    if (/^<\/VirtualHost/i.test(line)) {
      if (cur.names.length) out.push(cur);
      cur = null;
      continue;
    }
    let m: RegExpExecArray | null;
    if ((m = /^Server(?:Name|Alias)\s+(.+)$/i.exec(line))) {
      for (const t of m[1].split(/\s+/).slice(0, 12)) {
        if (t.startsWith("*.")) {
          const b = normalizeDomain(t.slice(2));
          if (b) {
            cur.wildcard = b;
            if (!cur.names.includes(b)) cur.names.push(b);
          }
          continue;
        }
        const dm = normalizeDomain(t);
        if (dm && !cur.names.includes(dm)) cur.names.push(dm);
      }
    } else if ((m = /^DocumentRoot\s+"?([^"\s]+)"?$/i.exec(line))) {
      const p = m[1].replace(/\/$/, "");
      if (validPath(p)) cur.root = p;
    } else if ((m = /^ProxyPass\s+\S+\s+(\S+)/i.exec(line))) {
      const pm = /^https?:\/\/[A-Za-z0-9._-]+:(\d{1,5})/.exec(m[1]);
      if (pm && !cur.proxyPort) {
        const p = Number(pm[1]);
        if (Number.isInteger(p) && p >= 1 && p <= 65535) cur.proxyPort = p;
      }
    } else if (/^SSLCertificateFile/i.test(line)) {
      cur.ssl = true;
    }
  }
  return out;
}

/** One site as it will be SERVED on the target, after validation + reconciliation. */
type TargetSite = {
  names: string[]; // validated, primary first; may include the wildcard base
  wildcard: string; // "" or the base domain to add `*.base` for
  proxyPort: number; // 0 ⇒ serve `root` instead
  root: string;
  certDomain: string; // "" unless a real certificate exists ON THE TARGET
  phpSocket: string; // "" unless php-fpm is actually running here
};

/**
 * Generate the migrated site configuration in the TARGET's own nginx dialect.
 *
 *  - `bindIp` is non-empty when the target's live config already has IP-bound
 *    `listen` directives. nginx picks the most specific listen socket BEFORE it
 *    ever looks at server_name, so a generic `listen 80` block loses to an
 *    IP-bound one and the generated vhost would never be selected. Matching the
 *    specificity is what makes it win (this bit twice in the field — once on 80,
 *    once on 443, where it served the wrong certificate).
 *  - `http2Directive` is true only on nginx ≥ 1.25, where `http2 on;` exists.
 *    On 1.18 that directive is a hard config error, so HTTP/2 is folded into the
 *    `listen` line instead.
 *  - A TLS server block is emitted ONLY when the certificate files were verified
 *    to exist on this machine. A config that references a missing certificate
 *    stops nginx from starting at all — the worst possible outcome.
 *
 * Every interpolated value is pre-validated: domains by DOMAIN_RE, paths by
 * PATH_RE, ports as integers. The file is written over SFTP, so no shell is
 * involved in producing it.
 */
function buildMigratedNginxConf(sites: TargetSite[], bindIp: string, http2Directive: boolean): string {
  const L: string[] = [
    "# Generated by the Nxeon migration engine — do not hand-edit if you plan to",
    "# re-run the migration; it rewrites this file. It is written for THIS",
    "# server's nginx, not copied from the old one, so it cannot import the old",
    "# server's paths, IP bindings, certificate locations or directive syntax.",
    "",
  ];
  const listen = (port: number, extra: string) =>
    bindIp ? `    listen ${bindIp}:${port}${extra};` : `    listen ${port}${extra};\n    listen [::]:${port}${extra};`;

  const body = (s: TargetSite, indent: string): string[] => {
    const b: string[] = [];
    if (s.proxyPort) {
      b.push(`${indent}client_max_body_size 64m;`);
      b.push("");
      b.push(`${indent}location / {`);
      b.push(`${indent}    proxy_pass http://127.0.0.1:${s.proxyPort};`);
      b.push(`${indent}    proxy_http_version 1.1;`);
      b.push(`${indent}    proxy_set_header Host $host;`);
      b.push(`${indent}    proxy_set_header X-Real-IP $remote_addr;`);
      b.push(`${indent}    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;`);
      b.push(`${indent}    proxy_set_header X-Forwarded-Proto $scheme;`);
      b.push(`${indent}    proxy_set_header Upgrade $http_upgrade;`);
      b.push(`${indent}    proxy_set_header Connection "upgrade";`);
      b.push(`${indent}    proxy_read_timeout 300s;`);
      b.push(`${indent}}`);
    } else {
      b.push(`${indent}root ${s.root};`);
      b.push(`${indent}index index.php index.html index.htm;`);
      b.push(`${indent}client_max_body_size 64m;`);
      b.push("");
      b.push(`${indent}location / {`);
      b.push(s.phpSocket ? `${indent}    try_files $uri $uri/ /index.php?$query_string;` : `${indent}    try_files $uri $uri/ =404;`);
      b.push(`${indent}}`);
      if (s.phpSocket) {
        b.push("");
        b.push(`${indent}location ~ \\.php$ {`);
        b.push(`${indent}    try_files $uri =404;`);
        b.push(`${indent}    fastcgi_split_path_info ^(.+\\.php)(/.+)$;`);
        b.push(`${indent}    fastcgi_pass unix:${s.phpSocket};`);
        b.push(`${indent}    fastcgi_index index.php;`);
        b.push(`${indent}    include fastcgi_params;`);
        b.push(`${indent}    fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`);
        b.push(`${indent}}`);
      }
      b.push("");
      b.push(`${indent}location ~ /\\. { deny all; }`);
    }
    return b;
  };

  for (const s of sites) {
    const names = [...s.names];
    if (s.wildcard) names.push(`*.${s.wildcard}`);
    const nameList = names.join(" ");
    L.push(`# ---- ${s.names[0]} ----`);
    L.push("server {");
    L.push(listen(80, ""));
    L.push(`    server_name ${nameList};`);
    L.push("");
    L.push("    # Keep HTTP-01 certificate issue/renewal working.");
    L.push("    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }");
    L.push("");
    if (s.certDomain) {
      L.push("    location / { return 301 https://$host$request_uri; }");
    } else {
      L.push(...body(s, "    "));
    }
    L.push("}");
    L.push("");
    if (s.certDomain) {
      L.push("server {");
      L.push(listen(443, http2Directive ? " ssl" : " ssl http2"));
      if (http2Directive) L.push("    http2 on;");
      L.push(`    server_name ${nameList};`);
      L.push("");
      L.push(`    ssl_certificate /etc/letsencrypt/live/${s.certDomain}/fullchain.pem;`);
      L.push(`    ssl_certificate_key /etc/letsencrypt/live/${s.certDomain}/privkey.pem;`);
      L.push("    ssl_protocols TLSv1.2 TLSv1.3;");
      L.push("    ssl_prefer_server_ciphers off;");
      L.push("    ssl_session_cache shared:MIGSSL:10m;");
      L.push("    ssl_session_timeout 1d;");
      L.push("");
      L.push(...body(s, "    "));
      L.push("}");
      L.push("");
    }
  }
  return L.join("\n") + "\n";
}

