// ---- 10. MAKE THE SITE ACTUALLY SERVE ---------------------------------
// The old behaviour here — rsync the source's /etc/nginx over the target's —
// is what turned a technically-complete migration into a dead site. See the
// long note on parseNginxDump: it overwrote the target's nginx.conf (so the
// include layout vanished and vhosts were silently ignored), imported
// `listen <old-ip>:80` into every file (nginx would not start), referenced
// certificates that do not exist here, used directives this nginx version
// rejects, and installed a catch-all proxying to a dead port that 502'd every
// request. So we now read the source's INTENT and generate a clean config in
// this server's own dialect, and keep the old tree only as a reference.
await report(84, "Publishing your site…", "Working out how your site should be served on the new server.");

// The target's public address, for IP-bound listen directives.
let targetIp = clean(target!.dedicatedIp?.address ?? "", 64);
if (!IPV4_RE.test(targetIp)) {
  targetIp = clean((await sh(conn, `hostname -I 2>/dev/null | awk '{print $1}'`)).stdout, 64);
  if (!IPV4_RE.test(targetIp)) targetIp = "";
}

// What is actually listening on this box right now?
const listening = new Set<number>();
{
  const r = await sh(conn, `(ss -lnt 2>/dev/null || netstat -lnt 2>/dev/null) | awk '{print $4}'`);
  for (const l of clean(r.stdout, 12000).split("\n")) {
    const m = /:(\d{1,5})$/.exec(l.trim());
    if (m) {
      const p = Number(m[1]);
      if (Number.isInteger(p) && p >= 1 && p <= 65535) listening.add(p);
    }
  }
}

// 10a. Keep the source's web config as a REFERENCE copy — never installed.
const refDir = `${work}/source-webconfig`;
if (inv.webConfigs.length) {
  for (const w of inv.webConfigs) {
    const srcTree = w === "nginx" ? "/etc/nginx" : w === "apache2" ? "/etc/apache2" : "/etc/httpd";
    await sh(conn, `mkdir -p ${refDir}/${w}`);
    await sh(conn, rsyncPull(`${srcTree}/`, `${refDir}/${w}`), TRANSFER_TIMEOUT_MS);
  }
  push({
    step: "Old web-server configuration",
    status: "copied",
    detail: `kept for reference at ${refDir} — deliberately NOT installed, because the old server's nginx.conf, IP bindings, certificate paths and directive syntax are not valid on this server; a clean config was generated instead`,
  });
}

// 10b. Does a CONTAINER own ports 80/443? Then the host web server must stay
// out of its way — two things cannot bind the same port, and the container
// proxy (Traefik/Caddy/nginx-proxy) is the one the compose project expects.
const webContainers = srcContainers.filter((c) => c.ports.some((p) => p.hostPort === 80 || p.hostPort === 443));
let webKind: "nginx" | "apache" | "container" | "none" = "none";
const servedSites: TargetSite[] = [];

if (webContainers.length) {
  webKind = "container";
  await sh(conn, `systemctl disable --now nginx 2>/dev/null; systemctl disable --now apache2 2>/dev/null; systemctl disable --now httpd 2>/dev/null; true`);
  const bound80 = listening.has(80) || (await shOk(conn, `(ss -lnt 2>/dev/null || netstat -lnt 2>/dev/null) | grep -q ':80 '`));
  const names = webContainers.map((c) => c.name).join(", ");
  const isProxy = webContainers.some((c) => PROXY_IMAGE_RE.test(c.image));
  push({
    step: "Reverse proxy (containerised)",
    status: bound80 ? "running" : "failed",
    detail: bound80
      ? `${names} publish${webContainers.length === 1 ? "es" : ""} port 80/443 and ${webContainers.length === 1 ? "is" : "are"} bound — the host web server was disabled so it cannot fight them for the port${isProxy ? " (this is your reverse proxy, so it also owns TLS)" : ""}`
      : `${names} should publish port 80/443 but nothing is listening on 80 here — start the project (\`${composeCmd || "docker compose"} up -d\`) and check \`docker logs\`, or your domain will not answer`,
  });
