} else {
  // 10c. Build the served-site list from the SOURCE's vhost intent.
  const srcVhosts = [...parseNginxDump(inv.nginxDump), ...parseApacheDump(inv.apacheDump)];
  const phpRaw = clean((await sh(conn, `ls -1 /run/php/php*-fpm.sock /var/run/php/php*-fpm.sock 2>/dev/null | head -n1`)).stdout, 255);
  const phpSocket = validPath(phpRaw) ? phpRaw : "";
  const certFor = async (names: string[]): Promise<string> => {
    for (const n of names) {
      if (await shOk(conn, `test -s /etc/letsencrypt/live/${n}/fullchain.pem && test -s /etc/letsencrypt/live/${n}/privkey.pem`)) return n;
    }
    return "";
  };
  // Local HTTP ports the migrated containers publish, as a fallback upstream.
  const appPorts = [...new Set(srcContainers.flatMap((c) => c.ports.filter((p) => p.proto === "tcp").map((p) => p.hostPort)))]
    .filter((p) => ![22, 80, 443, 3306, 5432, 6379, 11211, 27017, 9200].includes(p))
    .filter((p) => listening.has(p))
    .sort((a, b) => a - b);

  const unresolved: string[] = [];
  const seenName = new Set<string>();
  for (const v of srcVhosts) {
    if (servedSites.length >= 20) break;
    const names = v.names.filter((n) => !seenName.has(n));
    if (!names.length) continue;

    let port = v.proxyPort && listening.has(v.proxyPort) ? v.proxyPort : 0;
    let root = "";
    if (!port && v.root && (await shOk(conn, `test -d ${v.root}`))) root = v.root;
    if (!port && !root && appPorts.length === 1) port = appPorts[0];
    if (!port && !root) {
      unresolved.push(names[0]);
      continue;
    }
    for (const n of names) seenName.add(n);
    servedSites.push({
      names,
      wildcard: v.wildcard,
      proxyPort: port,
      root,
      certDomain: await certFor(names),
