    } else {
      push({
        step: "Publish your site",
        status: "copied",
        detail:
          `your app is running on 127.0.0.1:${appPorts[0]} but we could not work out which domain it should answer on. ` +
          `Once you know it, run: printf 'server {\\n listen 80;\\n server_name YOUR-DOMAIN;\\n location / { proxy_pass http://127.0.0.1:${appPorts[0]}; proxy_set_header Host $host; }\\n}\\n' > /etc/nginx/conf.d/site.conf && nginx -t && systemctl restart nginx`,
      });
    }
  }
  if (unresolved.length) {
    push({
      step: "Sites we could not publish automatically",
      status: "copied",
      detail: `${unresolved.slice(0, 6).join(", ")} — the old config pointed at an app port or folder that does not exist here yet; start the app, then add a vhost (the old config is at ${refDir} for reference)`,
    });
  }

  // 10d. Generate + install, in the target's own dialect.
  if (servedSites.length) {
    const sourceUsedApache = inv.webConfigs.some((w) => w === "apache2" || w === "httpd") && !inv.webConfigs.includes("nginx");
    webKind = sourceUsedApache ? "apache" : "nginx";
    const pkg: PkgKey = webKind === "apache" ? "apache" : "nginx";
    await ensurePackages(conn, [pkg]);

    const totalNames = servedSites.reduce((n, s) => n + s.names.length, 0);
    const withTls = servedSites.filter((s) => s.certDomain).length;
    await report(
      85,
      "Publishing your site…",
      `Generating a fresh ${webKind === "apache" ? "Apache" : "nginx"} configuration for ${totalNames} domain name(s)` +
        (withTls ? `, ${withTls} of them with the certificate that came across.` : " (HTTP only — no matching certificate was found).")
    );

    if (webKind === "nginx") {
      // Version-correct syntax: `http2 on;` only exists from nginx 1.25. On
      // 1.18 it is a fatal unknown directive, so HTTP/2 folds into `listen`.
      const vr = await sh(conn, `nginx -v 2>&1`);
