      const conf = buildMigratedNginxConf(servedSites, bindIp, http2Directive);
      await sh(conn, `rm -rf ${work}/nginx-before && cp -a /etc/nginx ${work}/nginx-before 2>/dev/null; true`);
      await sh(conn, `mkdir -p /etc/nginx/conf.d`);
      const primary = `/etc/nginx/conf.d/nxeon-migrated.conf`;
      await sftpWrite(sftp, primary, conf);
