            step: "Publish your site",
            status: "failed",
            detail: `the generated vhost is on disk at ${installedAt} but this server's nginx.conf does not include it, so it is being ignored — add \`include ${installedAt};\` inside the http block of /etc/nginx/nginx.conf and run \`systemctl restart nginx\``,
          });
        } else {
