          push({
            step: `Publish ${servedSites.length} site(s)`,
            status: "running",
            detail: `a clean nginx config was generated for ${names} at ${installedAt}, verified with \`nginx -t\`, confirmed loaded with \`nginx -T\`, and nginx restarted${withTls ? " — HTTPS uses the certificates migrated from the old server" : ""}`,
          });
