      await sh(conn, `chmod 644 ${site} && a2dissite 000-default >/dev/null 2>&1; a2ensite nxeon-migrated >/dev/null 2>&1; true`);
      const test = await sh(conn, `apachectl configtest 2>&1`);
      if (test.code !== 0) {
        await sh(conn, `a2dissite nxeon-migrated >/dev/null 2>&1; rm -f ${site}; systemctl restart apache2 2>/dev/null; true`);
        push({ step: "Publish your site", status: "failed", detail: `the generated Apache configuration was rejected (${tailOf(test, 1, 160)}) and was removed so Apache keeps running` });
      } else {
        await sh(conn, `systemctl enable apache2 >/dev/null 2>&1; systemctl restart apache2 2>&1`, SETUP_TIMEOUT_MS);
        const active = clean((await sh(conn, `systemctl is-active apache2 2>/dev/null`)).stdout, 32) === "active";
        push({
          step: active ? `Publish ${servedSites.length} site(s)` : "Publish your site",
          status: active ? "running" : "failed",
          detail: active
            ? `a clean Apache vhost was generated at ${site}, configtest passed and Apache restarted`
            : "Apache would not start with the generated vhost — it has been disabled so Apache keeps running",
        });
      }
    }
  }
}

// 10e. Wildcard / multi-tenant caveat — HTTP-01 cannot issue `*.domain`.
for (const s of servedSites) {
  if (!s.wildcard) continue;
