/**
 * The Apache equivalent of buildMigratedNginxConf, used when the SOURCE served
 * with Apache — keeping Apache means `.htaccess`-driven apps (WordPress and
 * friends) behave exactly as they did before, which a translation to nginx
 * would quietly break. Same rules: generated for THIS server, TLS blocks only
 * when the certificate really exists here, every value pre-validated.
 */
function buildMigratedApacheConf(sites: TargetSite[], bindIp: string): string {
  const L: string[] = [
    "# Generated by the Nxeon migration engine for THIS server's Apache.",
    "# The old server's config was not installed; it is kept only for reference.",
    "",
  ];
  const at = (port: number) => (bindIp ? `${bindIp}:${port}` : `*:${port}`);
  const body = (s: TargetSite): string[] => {
    const b: string[] = [];
    if (s.proxyPort) {
      b.push("    ProxyPreserveHost On");
      b.push("    RequestHeader set X-Forwarded-Proto expr=%{REQUEST_SCHEME}");
      b.push(`    ProxyPass / http://127.0.0.1:${s.proxyPort}/`);
      b.push(`    ProxyPassReverse / http://127.0.0.1:${s.proxyPort}/`);
    } else {
      b.push(`    DocumentRoot ${s.root}`);
      b.push(`    <Directory ${s.root}>`);
      b.push("        Options -Indexes +FollowSymLinks");
      b.push("        AllowOverride All");
      b.push("        Require all granted");
      b.push("    </Directory>");
    }
    return b;
  };
  for (const s of sites) {
    const aliases = [...s.names.slice(1), ...(s.wildcard ? [`*.${s.wildcard}`] : [])];
    L.push(`# ---- ${s.names[0]} ----`);
    L.push(`<VirtualHost ${at(80)}>`);
    L.push(`    ServerName ${s.names[0]}`);
    if (aliases.length) L.push(`    ServerAlias ${aliases.join(" ")}`);
    if (s.certDomain) {
      L.push("    RewriteEngine On");
      L.push("    RewriteCond %{REQUEST_URI} !^/\\.well-known/acme-challenge/");
      L.push("    RewriteRule ^(.*)$ https://%{HTTP_HOST}$1 [R=301,L]");
    } else {
      L.push(...body(s));
    }
    L.push("</VirtualHost>");
    L.push("");
    if (s.certDomain) {
      L.push(`<VirtualHost ${at(443)}>`);
      L.push(`    ServerName ${s.names[0]}`);
      if (aliases.length) L.push(`    ServerAlias ${aliases.join(" ")}`);
      L.push("    SSLEngine on");
      L.push(`    SSLCertificateFile /etc/letsencrypt/live/${s.certDomain}/fullchain.pem`);
      L.push(`    SSLCertificateKeyFile /etc/letsencrypt/live/${s.certDomain}/privkey.pem`);
      L.push(...body(s));
      L.push("</VirtualHost>");
      L.push("");
    }
  }
  return L.join("\n") + "\n";
}

