/** HTTP-probe one URL and return its status code ("000" = nothing answered). */
async function httpCode(conn: Client, url: string, hostHeader?: string): Promise<string> {
  const hdr = hostHeader ? `-H 'Host: ${hostHeader}' ` : "";
  const r = await sh(
    conn,
    `curl -sS -o /dev/null -w '%{http_code}' --max-time 12 ${hdr}${url} 2>/dev/null || echo 000`,
    SETUP_TIMEOUT_MS
  );
  const code = clean(r.stdout, 16).split("\n").filter(Boolean).pop() ?? "000";
  return /^\d{3}$/.test(code) ? code : "000";
}

