/**
 * "Migrate → point DNS → it just works" has to include HTTPS, or the customer's
 * first visit is a browser certificate warning. Three layers, tried in order,
 * and honest at every rung:
 *
 *   1. MIGRATED CERTIFICATES. Let's Encrypt certificates are portable — they
 *      stay valid on whichever machine serves them — so copying /etc/letsencrypt
 *      (certs, keys, `renewal/*.conf`, `accounts/`, the ssl option snippets)
 *      gives zero-gap HTTPS the instant traffic moves. Step 8d does the copy;
 *      fixRenewalConfigs repoints renewal at THIS server's webroot so
 *      `certbot renew` keeps working afterwards.
 *
 *   2. HTTP-01 per hostname. This can only succeed once the name resolves HERE,
 *      so it runs for names that already point at us, and is exposed as
 *      `issueMigrationCertificates()` for the DNS-cutover flow to call again
 *      afterwards. Every generated vhost carries a
 *      `location ^~ /.well-known/acme-challenge/` so `--webroot` validates.
 *
 *   3. DNS-01 for wildcards, through the customer's connected Cloudflare
 *      account. Multi-tenant apps serve `<tenant>.<base>` and HTTP-01 simply
 *      cannot issue `*.base`. The token is passed IN by the caller (it lives on
 *      the Nxeon side, not on the customer's box), written to a 0600 credentials
 *      file over SFTP — never an argv token — and shredded in `finally`.
 *      Note a wildcard matches exactly ONE label, so `hq.stg.example.com` needs
 *      `*.stg.example.com` in addition to `*.example.com`; both are requested.
 *
 * A certificate failure NEVER fails the migration — it becomes a named,
 * copy-pasteable manual step.
 */
const EMAIL_RE = /^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9.-]{1,190}\.[A-Za-z]{2,24}$/;
const ACME_WEBROOT = "/var/www/html";

/** What this migration published, persisted so the cutover flow can re-secure it. */
type SiteSpec = { sites: TargetSite[]; bindIp: string; http2: boolean; kind: "nginx" | "apache" };

/**
 * Re-validate a SiteSpec read back off the target. It is our own JSON, but it
 * came off a machine, so every field goes through the same allowlists again
 * before it can reach a config file or a command.
 */
function sanitizeSiteSpec(raw: unknown): SiteSpec | null {
  const r = raw as Record<string, unknown> | null;
  if (!r || typeof r !== "object") return null;
  const bindIp = typeof r.bindIp === "string" && IPV4_RE.test(r.bindIp) ? r.bindIp : "";
  const kind: "nginx" | "apache" = r.kind === "apache" ? "apache" : "nginx";
  const sites: TargetSite[] = [];
  for (const s of (Array.isArray(r.sites) ? r.sites : []).slice(0, 20) as Record<string, unknown>[]) {
    const names = (Array.isArray(s?.names) ? s.names : [])
      .map((n) => normalizeDomain(String(n ?? "")))
      .filter((n): n is string => !!n)
      .slice(0, 12);
    if (!names.length) continue;
    const portNum = Number(s?.proxyPort);
    const proxyPort = Number.isInteger(portNum) && portNum >= 1 && portNum <= 65535 ? portNum : 0;
    const root = typeof s?.root === "string" && validPath(s.root) ? s.root : "";
    if (!proxyPort && !root) continue;
    sites.push({
      names,
      wildcard: normalizeDomain(String(s?.wildcard ?? "")) ?? "",
      proxyPort,
      root,
      certDomain: normalizeDomain(String(s?.certDomain ?? "")) ?? "",
      phpSocket: typeof s?.phpSocket === "string" && validPath(s.phpSocket) ? s.phpSocket : "",
    });
  }
  return sites.length ? { sites, bindIp, http2: !!r.http2, kind } : null;
}

async function readSiteSpec(conn: Client, work: string): Promise<SiteSpec | null> {
  const r = await sh(conn, `cat ${work}/sites.json 2>/dev/null`);
  if (r.code !== 0 || !r.stdout.trim()) return null;
  try {
    return sanitizeSiteSpec(JSON.parse(r.stdout));
  } catch {
    return null;
  }
}

/** True when a live certificate + key really exist here for this exact name. */
async function certExists(conn: Client, domain: string): Promise<boolean> {
  if (!DOMAIN_RE.test(domain)) return false;
  return shOk(conn, `test -s /etc/letsencrypt/live/${domain}/fullchain.pem && test -s /etc/letsencrypt/live/${domain}/privkey.pem`);
}

/** Does this hostname already resolve to the NEW server? HTTP-01 requires it. */
async function resolvesHere(conn: Client, domain: string, ip: string): Promise<boolean> {
  if (!DOMAIN_RE.test(domain) || !IPV4_RE.test(ip)) return false;
  const r = await sh(conn, `getent ahostsv4 ${domain} 2>/dev/null | awk '{print $1}' | sort -u | head -n 8`);
  return clean(r.stdout, 512).split("\n").map((s) => s.trim()).includes(ip);
}

async function ensureAcmeWebroot(conn: Client): Promise<void> {
  await sh(conn, `mkdir -p ${ACME_WEBROOT}/.well-known/acme-challenge && chmod -R 755 ${ACME_WEBROOT}/.well-known`);
}

/**
 * Repoint migrated renewal configs at THIS server. Without this, `certbot renew`
 * keeps trying the old server's webroot (or its nginx/apache installer) and the
 * migrated certificates quietly stop renewing 60 days later. DNS-01 renewals are
 * left alone — their authenticator is already host-independent.
 */
const RENEWAL_FIX_SCRIPT = [
  "n=0",
  "for f in /etc/letsencrypt/renewal/*.conf; do",
  '  [ -f "$f" ] || continue',
  '  if grep -qE \'^authenticator[[:space:]]*=[[:space:]]*dns\' "$f"; then continue; fi',
  "  sed -i -e 's|^authenticator[[:space:]]*=.*|authenticator = webroot|' " +
    "-e 's|^installer[[:space:]]*=.*|installer = None|' " +
    "-e 's|^webroot_path[[:space:]]*=.*|webroot_path = /var/www/html,|' \"$f\"",
  "  awk 'BEGIN{m=0} /^\\[\\[webroot_map\\]\\]/{print; m=1; next} m==1 && /=/{sub(/=.*/, \"= /var/www/html\"); print; next} {print}' \"$f\" > \"$f.nx\" 2>/dev/null && mv \"$f.nx\" \"$f\"",
  '  grep -q \'^webroot_path\' "$f" || printf \'webroot_path = /var/www/html,\\n\' >> "$f"',
  "  n=$((n+1))",
  "done",
  "printf 'RENEWALFIX %s\\n' \"$n\"",
  "",
].join("\n");

async function fixRenewalConfigs(conn: Client, sftp: SFTPWrapper, work: string): Promise<number> {
  const p = `${work}/fix-renewal.sh`;
  await sftpWrite(sftp, p, RENEWAL_FIX_SCRIPT).catch(() => {});
  const r = await sh(conn, `sh ${p} 2>/dev/null`, SETUP_TIMEOUT_MS);
  const m = /RENEWALFIX\s+(\d+)/.exec(r.stdout);
  return m ? Number(m[1]) : 0;
}

/** The `-m …` / `--register-unsafely-without-email` fragment (validated email only). */
function acmeAccountArgs(email: string): string {
  return email && EMAIL_RE.test(email) ? `-m ${email} --no-eff-email` : "--register-unsafely-without-email";
}

/** HTTP-01 via webroot. `certName` fixes the /etc/letsencrypt/live/<name> dir. */
async function issueHttp01(conn: Client, certName: string, domains: string[], email: string): Promise<{ ok: boolean; err: string }> {
  const ds = [...new Set(domains.filter((d) => DOMAIN_RE.test(d)))].slice(0, 20);
  if (!ds.length || !DOMAIN_RE.test(certName)) return { ok: false, err: "no valid hostnames" };
  const cmd =
    `certbot certonly --webroot -w ${ACME_WEBROOT} -n --agree-tos ${acmeAccountArgs(email)} ` +
    `--keep-until-expiring --cert-name ${certName} ${ds.map((d) => `-d ${d}`).join(" ")} 2>&1`;
  const r = await sh(conn, cmd, IMAGE_TIMEOUT_MS);
  if (await certExists(conn, certName)) return { ok: true, err: "" };
  return { ok: false, err: tailOf(r, 2, 220) };
}

/**
 * DNS-01 via the customer's connected Cloudflare account — the only way to get a
 * wildcard. The token never appears in argv: it is written to a 0600 credentials
 * file over SFTP and shredded immediately afterwards, success or failure.
 */
async function issueDns01(
  conn: Client,
  sftp: SFTPWrapper,
  work: string,
  token: string,
  certName: string,
  domains: string[],
  email: string
): Promise<{ ok: boolean; err: string }> {
  if (!token || token.length > 512 || /[\r\n]/.test(token)) return { ok: false, err: "unusable Cloudflare token" };
  const ds = [...new Set(domains)].filter((d) => DOMAIN_RE.test(d.replace(/^\*\./, "")) && /^(\*\.)?[a-z0-9.-]+$/.test(d)).slice(0, 20);
  if (!ds.length || !DOMAIN_RE.test(certName)) return { ok: false, err: "no valid hostnames" };
  const ini = `${work}/cf-dns.ini`;
  try {
    await sftpWrite(sftp, ini, `dns_cloudflare_api_token = ${token}\n`);
    await sh(conn, `chmod 600 ${ini}`);
    const cmd =
      `certbot certonly --dns-cloudflare --dns-cloudflare-credentials ${ini} --dns-cloudflare-propagation-seconds 45 ` +
      `-n --agree-tos ${acmeAccountArgs(email)} --keep-until-expiring --cert-name ${certName} ` +
      `${ds.map((d) => `-d '${d}'`).join(" ")} 2>&1`;
    const r = await sh(conn, cmd, IMAGE_TIMEOUT_MS);
    if (await certExists(conn, certName)) return { ok: true, err: "" };
    return { ok: false, err: tailOf(r, 2, 220) };
  } finally {
    await sh(conn, `shred -u ${ini} 2>/dev/null || rm -f ${ini}`).catch(() => {});
  }
}

/**
 * A wildcard covers exactly ONE label, so a multi-tenant app that also uses a
 * staging tier (`hq.stg.example.com`) needs `*.stg.example.com` as well as
 * `*.example.com`. Return every base that needs its own wildcard.
 */
function wildcardBasesFor(site: TargetSite): string[] {
  const bases = new Set<string>();
  if (site.wildcard) bases.add(site.wildcard);
  for (const n of site.names) {
    const parts = n.split(".");
    if (parts.length < 3) continue;
    const parent = parts.slice(1).join(".");
    if (site.wildcard && parent !== site.wildcard && parent.endsWith(`.${site.wildcard}`)) bases.add(parent);
  }
  return [...bases].slice(0, 4);
}

/** Rewrite + reload the generated config so newly-issued certs are actually used. */
async function applyCertsAndReload(
  conn: Client,
  sftp: SFTPWrapper,
  work: string,
  spec: SiteSpec
): Promise<{ ok: boolean; detail: string }> {
  for (const s of spec.sites) {
    s.certDomain = "";
    for (const n of s.names) {
      if (await certExists(conn, n)) {
        s.certDomain = n;
        break;
      }
    }
  }
  const conf = spec.kind === "apache" ? buildMigratedApacheConf(spec.sites, spec.bindIp) : buildMigratedNginxConf(spec.sites, spec.bindIp, spec.http2);
  await sftpWrite(sftp, `${work}/sites.json`, JSON.stringify(spec)).catch(() => {});
  if (spec.kind === "apache") {
    const site = `/etc/apache2/sites-available/nxeon-migrated.conf`;
    await sftpWrite(sftp, site, conf);
    await sh(conn, `chmod 644 ${site}`);
    const t = await sh(conn, `apachectl configtest 2>&1`);
    if (t.code !== 0) return { ok: false, detail: `Apache rejected the updated config: ${tailOf(t, 1, 160)}` };
    await sh(conn, `systemctl restart apache2 2>&1`, SETUP_TIMEOUT_MS);
    return { ok: clean((await sh(conn, `systemctl is-active apache2`)).stdout, 32) === "active", detail: "Apache restarted with the certificates" };
  }
  const primary = (await shOk(conn, `test -f /etc/nginx/conf.d/nxeon-migrated.conf`))
    ? `/etc/nginx/conf.d/nxeon-migrated.conf`
    : `/etc/nginx/sites-available/nxeon-migrated.conf`;
  await sftpWrite(sftp, primary, conf);
  await sh(conn, `chmod 644 ${primary}`);
  const t = await sh(conn, `nginx -t 2>&1`);
  if (t.code !== 0) return { ok: false, detail: `nginx rejected the updated config: ${tailOf(t, 1, 160)}` };
  await sh(conn, `systemctl restart nginx 2>&1`, SETUP_TIMEOUT_MS);
  return { ok: clean((await sh(conn, `systemctl is-active nginx`)).stdout, 32) === "active", detail: "nginx restarted with the certificates" };
}

export type TlsPending = { domain: string; why: string; fix: string };

/**
 * Walk the fallback ladder for every published site and report, per hostname,
 * whether it now has TLS.
 */
async function secureSites(opts: {
  conn: Client;
  sftp: SFTPWrapper;
  work: string;
  spec: SiteSpec;
  targetIp: string;
  email: string;
  cloudflareToken?: string | null;
  webOwnedByContainer: boolean;
  say: (line: string) => Promise<void>;
}): Promise<{ secured: string[]; pending: TlsPending[] }> {
  const { conn, sftp, work, spec, targetIp, email, cloudflareToken, webOwnedByContainer, say } = opts;
  const secured: string[] = [];
  const pending: TlsPending[] = [];

  await ensureAcmeWebroot(conn);
  const fixed = await fixRenewalConfigs(conn, sftp, work);
  if (fixed) await say(`  Repointed ${fixed} certificate renewal profile(s) at this server so they keep auto-renewing.`);

  let needCertbot = false;
  for (const s of spec.sites) for (const n of s.names) if (!(await certExists(conn, n))) needCertbot = true;
  if (needCertbot) {
    const wantCf = !!cloudflareToken && spec.sites.some((s) => s.wildcard);
    await ensurePackages(conn, wantCf ? ["certbot", "certbot_dns_cloudflare"] : ["certbot"]);
  }

  for (const site of spec.sites) {
    // 1. Already covered by a certificate that came across with the migration.
    const already = site.names.find(() => false);
    void already;
    let done = false;
    for (const n of site.names) {
      if (await certExists(conn, n)) {
        secured.push(...site.names);
        await say(`  ${n}: HTTPS is already covered by the certificate migrated from the old server.`);
        done = true;
        break;
      }
    }
    if (done) continue;

    // 3. Wildcard via DNS-01 — the ONLY option for `*.domain`.
    const bases = wildcardBasesFor(site);
    if (bases.length && cloudflareToken) {
      let anyOk = false;
      for (const base of bases) {
        const r = await issueDns01(conn, sftp, work, cloudflareToken, base, [`*.${base}`, base], email);
        if (r.ok) {
          anyOk = true;
          secured.push(base, `*.${base}`);
          await say(`  Issued a wildcard certificate for *.${base} using your connected Cloudflare account (DNS-01).`);
        } else {
          pending.push({
            domain: `*.${base}`,
            why: `the wildcard certificate could not be issued (${r.err || "unknown error"})`,
            fix: `certbot certonly --dns-cloudflare --dns-cloudflare-credentials <cloudflare.ini> -d '*.${base}' -d ${base}`,
          });
        }
      }
      if (anyOk) continue;
    } else if (bases.length) {
      pending.push({
        domain: `*.${bases[0]}`,
        why: "this app serves each tenant on its own subdomain, which needs a wildcard certificate, and a wildcard can only be issued with a DNS-01 challenge — connect Cloudflare in Settings and we can do it for you",
        fix: `certbot certonly --manual --preferred-challenges dns -d '*.${bases[0]}' -d ${bases[0]}`,
      });
    }

    // 2. HTTP-01 for the names that already point at this server.
    if (webOwnedByContainer) {
      pending.push({
        domain: site.names[0],
        why: "port 80 is served by one of your containers, so we cannot run the certificate check on the host",
        fix: `issue TLS inside your proxy container (Traefik/Caddy do this automatically once ${site.names[0]} resolves here)`,
      });
      continue;
    }
    const resolving: string[] = [];
    for (const n of site.names) if (await resolvesHere(conn, n, targetIp)) resolving.push(n);
    if (!resolving.length) {
      pending.push({
        domain: site.names[0],
        why: `${site.names.length > 1 ? "none of these names point" : "this name does not point"} at the new server yet (${targetIp || "its IP"}), and a certificate cannot be issued until it does`,
        fix: `point the DNS, then run: certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${site.names[0]} ${site.names.map((d) => `-d ${d}`).join(" ")}`,
      });
      continue;
    }
    const r = await issueHttp01(conn, resolving[0], resolving, email);
    if (r.ok) {
      secured.push(...resolving);
      await say(`  Issued a certificate for ${resolving.join(", ")}.`);
      const notYet = site.names.filter((n) => !resolving.includes(n));
      if (notYet.length) {
        pending.push({
          domain: notYet[0],
          why: `${notYet.join(", ")} ${notYet.length > 1 ? "do" : "does"} not point at the new server yet, so ${notYet.length > 1 ? "they were" : "it was"} left out of the certificate`,
          fix: `point the DNS, then run: certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${resolving[0]} ${site.names.map((d) => `-d ${d}`).join(" ")}`,
        });
      }
    } else {
      pending.push({
        domain: resolving[0],
        why: `the certificate request failed (${r.err || "unknown error"})`,
        fix: `certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${resolving[0]} ${resolving.map((d) => `-d ${d}`).join(" ")}`,
      });
    }
  }

  if (secured.length) {
    const applied = await applyCertsAndReload(conn, sftp, work, spec);
    if (!applied.ok) {
      pending.push({
        domain: spec.sites[0]?.names[0] ?? "",
        why: `certificates were issued but the web server would not take the updated config (${applied.detail})`,
        fix: "check `nginx -t` / `apachectl configtest` on the server",
      });
    }
  }
  return { secured: [...new Set(secured)], pending };
}

export type MigrationTlsInput = {
  target: TargetServer | null;
  migrationId: string;
  /** Hostnames beyond the ones the migration published (e.g. the customer's Domain rows). */
  extraDomains?: string[];
  /** A Cloudflare API token with DNS-edit scope, resolved on the Nxeon side. */
  cloudflareToken?: string | null;
  acmeEmail?: string | null;
  report?: ReportFn;
};
export type MigrationTlsResult = { secured: string[]; pending: TlsPending[]; error?: string };

/**
 * Issue/refresh TLS for a completed migration — the step that has to run AFTER
 * DNS is pointed, because HTTP-01 cannot validate a name that still resolves to
 * the old server.
 *
 * Exposed as its own entry point so the DNS-cutover flow can call it once the
 * hostname resolves to the target: `runRealMigration` persists what it published
 * to `<workdir>/sites.json`, and this re-reads (and re-validates) that, walks the
 * same fallback ladder, then rewrites and reloads the vhost. Safe to call
 * repeatedly — certbot's `--keep-until-expiring` makes it a no-op once a
 * certificate is in place.
 */
export async function issueMigrationCertificates(input: MigrationTlsInput): Promise<MigrationTlsResult> {
  const { target, migrationId } = input;
  if (!target) return { secured: [], pending: [], error: "target server row not found" };
  const work = migrationWorkDir(migrationId);
  const { conn, sftp } = await connectTarget(target);
  const say = async (line: string) => {
    if (input.report) await input.report(50, "Securing your site…", line);
  };
  try {
    const spec = await readSiteSpec(conn, work);
    if (!spec) {
      return { secured: [], pending: [], error: "this migration did not publish a site configuration we can secure" };
    }
    // Fold in hostnames the platform knows about, attached to the site whose
    // primary name they share a suffix with (else the first site).
    for (const raw of (input.extraDomains ?? []).slice(0, 20)) {
      const d = normalizeDomain(raw);
      if (!d) continue;
      if (spec.sites.some((s) => s.names.includes(d))) continue;
      const host = spec.sites.find((s) => s.names.some((n) => d.endsWith(`.${n}`) || n.endsWith(`.${d}`))) ?? spec.sites[0];
      if (host && host.names.length < 12) host.names.push(d);
    }
    let targetIp = clean(target.dedicatedIp?.address ?? "", 64);
    if (!IPV4_RE.test(targetIp)) {
      targetIp = clean((await sh(conn, `hostname -I 2>/dev/null | awk '{print $1}'`)).stdout, 64);
      if (!IPV4_RE.test(targetIp)) targetIp = "";
    }
    const webOwnedByContainer = !(await shOk(conn, `systemctl is-active nginx >/dev/null 2>&1 || systemctl is-active apache2 >/dev/null 2>&1`));
    const res = await secureSites({
      conn, sftp, work, spec, targetIp,
      email: clean(input.acmeEmail ?? "", 190),
      cloudflareToken: input.cloudflareToken,
      webOwnedByContainer,
      say,
    });
    return res;
  } catch (e: any) {
    return { secured: [], pending: [], error: clean(e?.message ?? e, 300) };
  } finally {
    await sh(conn, `shred -u ${work}/cf-dns.ini 2>/dev/null || rm -f ${work}/cf-dns.ini`).catch(() => {});
    try {
      conn.end();
    } catch {
      /* best-effort */
    }
  }
}

// ---------------------------------------------------------------------------

/**
 * Perform a real lift-and-shift migration. Throws only on a FATAL setup error

input.old_string:
// ---------------------------------------------------------------------------

/**
 * Perform a real lift-and-shift migration. Throws only on a FATAL setup error

input.new_string:
// ===========================================================================
// AUTOMATIC TLS
// ===========================================================================
/**
 * "Migrate → point DNS → it just works" has to include HTTPS, or the customer's
 * first visit is a browser certificate warning. Three layers, tried in order,
 * and honest at every rung:
 *
 *   1. MIGRATED CERTIFICATES. Let's Encrypt certificates are portable — they
 *      stay valid on whichever machine serves them — so copying /etc/letsencrypt
 *      (certs, keys, `renewal/*.conf`, `accounts/`, the ssl option snippets)
 *      gives zero-gap HTTPS the instant traffic moves. Step 8d does the copy;
 *      fixRenewalConfigs repoints renewal at THIS server's webroot so
 *      `certbot renew` keeps working afterwards.
 *
 *   2. HTTP-01 per hostname. This can only succeed once the name resolves HERE,
 *      so it runs for names that already point at us, and is exposed as
 *      `issueMigrationCertificates()` for the DNS-cutover flow to call again
 *      afterwards. Every generated vhost carries a
 *      `location ^~ /.well-known/acme-challenge/` so `--webroot` validates.
 *
 *   3. DNS-01 for wildcards, through the customer's connected Cloudflare
 *      account. Multi-tenant apps serve `<tenant>.<base>` and HTTP-01 simply
 *      cannot issue `*.base`. The token is passed IN by the caller (it lives on
 *      the Nxeon side, not on the customer's box), written to a 0600 credentials
 *      file over SFTP — never an argv token — and shredded in `finally`.
 *      Note a wildcard covers exactly ONE label, so `hq.stg.example.com` needs
 *      `*.stg.example.com` as well as `*.example.com`; both are requested.
 *
 * A certificate failure NEVER fails the migration — it becomes a named,
 * copy-pasteable manual step.
 */
const EMAIL_RE = /^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9.-]{1,190}\.[A-Za-z]{2,24}$/;
const ACME_WEBROOT = "/var/www/html";

/** What this migration published, persisted so the cutover flow can re-secure it. */
type SiteSpec = { sites: TargetSite[]; bindIp: string; http2: boolean; kind: "nginx" | "apache" };

/**
 * Re-validate a SiteSpec read back off the target. It is our own JSON, but it
 * came off a machine, so every field goes through the same allowlists again
 * before it can reach a config file or a command.
 */
function sanitizeSiteSpec(raw: unknown): SiteSpec | null {
  const r = raw as Record<string, unknown> | null;
  if (!r || typeof r !== "object") return null;
  const bindIp = typeof r.bindIp === "string" && IPV4_RE.test(r.bindIp) ? r.bindIp : "";
  const kind: "nginx" | "apache" = r.kind === "apache" ? "apache" : "nginx";
  const sites: TargetSite[] = [];
  for (const s of (Array.isArray(r.sites) ? r.sites : []).slice(0, 20) as Record<string, unknown>[]) {
    const names = (Array.isArray(s?.names) ? (s.names as unknown[]) : [])
      .map((n) => normalizeDomain(String(n ?? "")))
      .filter((n): n is string => !!n)
      .slice(0, 12);
    if (!names.length) continue;
    const portNum = Number(s?.proxyPort);
    const proxyPort = Number.isInteger(portNum) && portNum >= 1 && portNum <= 65535 ? portNum : 0;
    const root = typeof s?.root === "string" && validPath(s.root) ? s.root : "";
    if (!proxyPort && !root) continue;
    sites.push({
      names,
      wildcard: normalizeDomain(String(s?.wildcard ?? "")) ?? "",
      proxyPort,
      root,
      certDomain: normalizeDomain(String(s?.certDomain ?? "")) ?? "",
      phpSocket: typeof s?.phpSocket === "string" && validPath(s.phpSocket) ? s.phpSocket : "",
    });
  }
  return sites.length ? { sites, bindIp, http2: !!r.http2, kind } : null;
}

async function readSiteSpec(conn: Client, work: string): Promise<SiteSpec | null> {
  const r = await sh(conn, `cat ${work}/sites.json 2>/dev/null`);
  if (r.code !== 0 || !r.stdout.trim()) return null;
  try {
    return sanitizeSiteSpec(JSON.parse(r.stdout));
  } catch {
    return null;
  }
}

/** True when a live certificate + key really exist here for this exact name. */
async function certExists(conn: Client, domain: string): Promise<boolean> {
  if (!DOMAIN_RE.test(domain)) return false;
  return shOk(conn, `test -s /etc/letsencrypt/live/${domain}/fullchain.pem && test -s /etc/letsencrypt/live/${domain}/privkey.pem`);
}

/** Does this hostname already resolve to the NEW server? HTTP-01 requires it. */
async function resolvesHere(conn: Client, domain: string, ip: string): Promise<boolean> {
  if (!DOMAIN_RE.test(domain) || !IPV4_RE.test(ip)) return false;
  const r = await sh(conn, `getent ahostsv4 ${domain} 2>/dev/null | awk '{print $1}' | sort -u | head -n 8`);
  return clean(r.stdout, 512).split("\n").map((s) => s.trim()).includes(ip);
}

async function ensureAcmeWebroot(conn: Client): Promise<void> {
  await sh(conn, `mkdir -p ${ACME_WEBROOT}/.well-known/acme-challenge && chmod -R 755 ${ACME_WEBROOT}/.well-known`);
}

/**
 * Repoint migrated renewal profiles at THIS server. Without this, `certbot renew`
 * keeps trying the old server's webroot (or its nginx/apache installer) and the
 * migrated certificates quietly stop renewing about 60 days later. DNS-01
 * profiles are left alone — their authenticator is already host-independent.
 */
const RENEWAL_FIX_SCRIPT = [
  "n=0",
  "for f in /etc/letsencrypt/renewal/*.conf; do",
  '  [ -f "$f" ] || continue',
  "  if grep -qE '^authenticator[[:space:]]*=[[:space:]]*dns' \"$f\"; then continue; fi",
  "  sed -i -e 's|^authenticator[[:space:]]*=.*|authenticator = webroot|' " +
    "-e 's|^installer[[:space:]]*=.*|installer = None|' " +
    "-e 's|^webroot_path[[:space:]]*=.*|webroot_path = /var/www/html,|' \"$f\"",
  "  awk 'BEGIN{m=0} /^\\[\\[webroot_map\\]\\]/{print; m=1; next} m==1 && /=/{sub(/=.*/, \"= /var/www/html\"); print; next} {print}' \"$f\" > \"$f.nx\" 2>/dev/null && mv \"$f.nx\" \"$f\"",
  "  grep -q '^webroot_path' \"$f\" || printf 'webroot_path = /var/www/html,\\n' >> \"$f\"",
  "  n=$((n+1))",
  "done",
  "printf 'RENEWALFIX %s\\n' \"$n\"",
  "",
].join("\n");

async function fixRenewalConfigs(conn: Client, sftp: SFTPWrapper, work: string): Promise<number> {
  const p = `${work}/fix-renewal.sh`;
  await sftpWrite(sftp, p, RENEWAL_FIX_SCRIPT).catch(() => {});
  const r = await sh(conn, `sh ${p} 2>/dev/null`, SETUP_TIMEOUT_MS);
  const m = /RENEWALFIX\s+(\d+)/.exec(r.stdout);
  return m ? Number(m[1]) : 0;
}

/** The `-m …` / `--register-unsafely-without-email` fragment (validated email only). */
function acmeAccountArgs(email: string): string {
  return email && EMAIL_RE.test(email) ? `-m ${email} --no-eff-email` : "--register-unsafely-without-email";
}

/** HTTP-01 via webroot. `certName` fixes the /etc/letsencrypt/live/<name> directory. */
async function issueHttp01(conn: Client, certName: string, domains: string[], email: string): Promise<{ ok: boolean; err: string }> {
  const ds = [...new Set(domains.filter((d) => DOMAIN_RE.test(d)))].slice(0, 20);
  if (!ds.length || !DOMAIN_RE.test(certName)) return { ok: false, err: "no valid hostnames" };
  const cmd =
    `certbot certonly --webroot -w ${ACME_WEBROOT} -n --agree-tos ${acmeAccountArgs(email)} ` +
    `--keep-until-expiring --cert-name ${certName} ${ds.map((d) => `-d ${d}`).join(" ")} 2>&1`;
  const r = await sh(conn, cmd, IMAGE_TIMEOUT_MS);
  if (await certExists(conn, certName)) return { ok: true, err: "" };
  return { ok: false, err: tailOf(r, 2, 220) };
}

/**
 * DNS-01 via the customer's connected Cloudflare account — the only way to get a
 * wildcard. The token never appears in argv: it is written to a 0600 credentials
 * file over SFTP and shredded immediately afterwards, success or failure.
 */
async function issueDns01(
  conn: Client,
  sftp: SFTPWrapper,
  work: string,
  token: string,
  certName: string,
  domains: string[],
  email: string
): Promise<{ ok: boolean; err: string }> {
  if (!token || token.length > 512 || /[\r\n]/.test(token)) return { ok: false, err: "unusable Cloudflare token" };
  const ds = [...new Set(domains)].filter((d) => DOMAIN_RE.test(d.replace(/^\*\./, ""))).slice(0, 20);
  if (!ds.length || !DOMAIN_RE.test(certName)) return { ok: false, err: "no valid hostnames" };
  const ini = `${work}/cf-dns.ini`;
  try {
    await sftpWrite(sftp, ini, `dns_cloudflare_api_token = ${token}\n`);
    await sh(conn, `chmod 600 ${ini}`);
    const cmd =
      `certbot certonly --dns-cloudflare --dns-cloudflare-credentials ${ini} --dns-cloudflare-propagation-seconds 45 ` +
      `-n --agree-tos ${acmeAccountArgs(email)} --keep-until-expiring --cert-name ${certName} ` +
      `${ds.map((d) => `-d '${d}'`).join(" ")} 2>&1`;
    const r = await sh(conn, cmd, IMAGE_TIMEOUT_MS);
    if (await certExists(conn, certName)) return { ok: true, err: "" };
    return { ok: false, err: tailOf(r, 2, 220) };
  } finally {
    await sh(conn, `shred -u ${ini} 2>/dev/null || rm -f ${ini}`).catch(() => {});
  }
}

/**
 * A wildcard covers exactly ONE label, so a multi-tenant app that also has a
 * staging tier (`hq.stg.example.com`) needs `*.stg.example.com` as well as
 * `*.example.com`. Return every base that needs its own wildcard.
 */
function wildcardBasesFor(site: TargetSite): string[] {
  const bases = new Set<string>();
  if (site.wildcard) bases.add(site.wildcard);
  for (const n of site.names) {
    const parts = n.split(".");
    if (parts.length < 3) continue;
    const parent = parts.slice(1).join(".");
    if (site.wildcard && parent !== site.wildcard && parent.endsWith(`.${site.wildcard}`)) bases.add(parent);
  }
  return [...bases].slice(0, 4);
}

/** Rewrite + reload the generated config so newly-issued certs are actually used. */
async function applyCertsAndReload(
  conn: Client,
  sftp: SFTPWrapper,
  work: string,
  spec: SiteSpec
): Promise<{ ok: boolean; detail: string }> {
  for (const s of spec.sites) {
    s.certDomain = "";
    for (const n of s.names) {
      if (await certExists(conn, n)) {
        s.certDomain = n;
        break;
      }
    }
  }
  const conf =
    spec.kind === "apache"
      ? buildMigratedApacheConf(spec.sites, spec.bindIp)
      : buildMigratedNginxConf(spec.sites, spec.bindIp, spec.http2);
  await sftpWrite(sftp, `${work}/sites.json`, JSON.stringify(spec)).catch(() => {});
  if (spec.kind === "apache") {
    const site = `/etc/apache2/sites-available/nxeon-migrated.conf`;
    await sftpWrite(sftp, site, conf);
    await sh(conn, `chmod 644 ${site}`);
    const t = await sh(conn, `apachectl configtest 2>&1`);
    if (t.code !== 0) return { ok: false, detail: `Apache rejected the updated config: ${tailOf(t, 1, 160)}` };
    await sh(conn, `systemctl restart apache2 2>&1`, SETUP_TIMEOUT_MS);
    return { ok: clean((await sh(conn, `systemctl is-active apache2`)).stdout, 32) === "active", detail: "Apache restarted with the certificates" };
  }
  const primary = (await shOk(conn, `test -f /etc/nginx/conf.d/nxeon-migrated.conf`))
    ? `/etc/nginx/conf.d/nxeon-migrated.conf`
    : `/etc/nginx/sites-available/nxeon-migrated.conf`;
  await sftpWrite(sftp, primary, conf);
  await sh(conn, `chmod 644 ${primary}`);
  const t = await sh(conn, `nginx -t 2>&1`);
  if (t.code !== 0) return { ok: false, detail: `nginx rejected the updated config: ${tailOf(t, 1, 160)}` };
  await sh(conn, `systemctl restart nginx 2>&1`, SETUP_TIMEOUT_MS);
  return { ok: clean((await sh(conn, `systemctl is-active nginx`)).stdout, 32) === "active", detail: "nginx restarted with the certificates" };
}

export type TlsPending = { domain: string; why: string; fix: string };

/**
 * Walk the fallback ladder for every published site and report, per hostname,
 * whether it now has TLS: migrated certificate → DNS-01 wildcard (when
 * Cloudflare is connected) → HTTP-01 → a named manual command.
 */
async function secureSites(opts: {
  conn: Client;
  sftp: SFTPWrapper;
  work: string;
  spec: SiteSpec;
  targetIp: string;
  email: string;
  cloudflareToken?: string | null;
  webOwnedByContainer: boolean;
  say: (line: string) => Promise<void>;
}): Promise<{ secured: string[]; pending: TlsPending[] }> {
  const { conn, sftp, work, spec, targetIp, email, cloudflareToken, webOwnedByContainer, say } = opts;
  const secured: string[] = [];
  const pending: TlsPending[] = [];

  await ensureAcmeWebroot(conn);
  const fixed = await fixRenewalConfigs(conn, sftp, work);
  if (fixed) await say(`  Repointed ${fixed} certificate renewal profile(s) at this server so they keep auto-renewing.`);

  let needCertbot = false;
  for (const s of spec.sites) for (const n of s.names) if (!(await certExists(conn, n))) needCertbot = true;
  if (needCertbot) {
    const wantCf = !!cloudflareToken && spec.sites.some((s) => s.wildcard);
    await ensurePackages(conn, wantCf ? ["certbot", "certbot_dns_cloudflare"] : ["certbot"]);
  }

  for (const site of spec.sites) {
    // 1. Already covered by a certificate that came across with the migration.
    let covered = false;
    for (const n of site.names) {
      if (await certExists(conn, n)) {
        secured.push(...site.names);
        await say(`  ${n}: HTTPS already covered by the certificate migrated from the old server.`);
        covered = true;
        break;
      }
    }
    if (covered) continue;

    // 3. Wildcard via DNS-01 — the ONLY way to get `*.domain`.
    const bases = wildcardBasesFor(site);
    if (bases.length && cloudflareToken) {
      let anyOk = false;
      for (const base of bases) {
        const r = await issueDns01(conn, sftp, work, cloudflareToken, base, [`*.${base}`, base], email);
        if (r.ok) {
          anyOk = true;
          secured.push(base, `*.${base}`);
          await say(`  Issued a wildcard certificate for *.${base} through your connected Cloudflare account (DNS-01).`);
        } else {
          pending.push({
            domain: `*.${base}`,
            why: `the wildcard certificate could not be issued (${r.err || "unknown error"})`,
            fix: `certbot certonly --dns-cloudflare --dns-cloudflare-credentials <cloudflare.ini> -d '*.${base}' -d ${base}`,
          });
        }
      }
      if (anyOk) continue;
    } else if (bases.length) {
      pending.push({
        domain: `*.${bases[0]}`,
        why:
          "this app gives each tenant its own subdomain, which needs a wildcard certificate — and a wildcard can only be issued with a DNS-01 challenge. Connect Cloudflare in Settings and we can issue it for you automatically",
        fix: `certbot certonly --manual --preferred-challenges dns -d '*.${bases[0]}' -d ${bases[0]}`,
      });
    }

    // 2. HTTP-01 for the names that already point at this server.
    if (webOwnedByContainer) {
      pending.push({
        domain: site.names[0],
        why: "port 80 is served by one of your containers, so the certificate check cannot run on the host",
        fix: `issue TLS inside your proxy container (Traefik and Caddy do this automatically once ${site.names[0]} resolves here)`,
      });
      continue;
    }
    const resolving: string[] = [];
    for (const n of site.names) if (await resolvesHere(conn, n, targetIp)) resolving.push(n);
    if (!resolving.length) {
      pending.push({
        domain: site.names[0],
        why: `${site.names.length > 1 ? "none of these names point" : "this name does not point"} at the new server yet${targetIp ? ` (${targetIp})` : ""}, and a certificate cannot be issued until DNS moves`,
        fix: `point the DNS, then run: certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${site.names[0]} ${site.names.map((d) => `-d ${d}`).join(" ")}`,
      });
      continue;
    }
    const r = await issueHttp01(conn, resolving[0], resolving, email);
    if (r.ok) {
      secured.push(...resolving);
      await say(`  Issued a certificate for ${resolving.join(", ")}.`);
      const notYet = site.names.filter((n) => !resolving.includes(n));
      if (notYet.length) {
        pending.push({
          domain: notYet[0],
          why: `${notYet.join(", ")} ${notYet.length > 1 ? "do" : "does"} not point at the new server yet, so ${notYet.length > 1 ? "they were" : "it was"} left out of the certificate`,
          fix: `point the DNS, then run: certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${resolving[0]} ${site.names.map((d) => `-d ${d}`).join(" ")}`,
        });
      }
    } else {
      pending.push({
        domain: resolving[0],
        why: `the certificate request failed (${r.err || "unknown error"})`,
        fix: `certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${resolving[0]} ${resolving.map((d) => `-d ${d}`).join(" ")}`,
      });
    }
  }

  if (secured.length) {
    const applied = await applyCertsAndReload(conn, sftp, work, spec);
    if (!applied.ok) {
      pending.push({
        domain: spec.sites[0]?.names[0] ?? "",
        why: `certificates were issued but the web server would not take the updated config (${applied.detail})`,
        fix: "check `nginx -t` / `apachectl configtest` on the server",
      });
    }
  }
  return { secured: [...new Set(secured)], pending };
}

export type MigrationTlsInput = {
  target: TargetServer | null;
  migrationId: string;
  /** Hostnames beyond the ones the migration published (e.g. the customer's Domain rows). */
  extraDomains?: string[];
  /** A Cloudflare API token with DNS-edit scope, resolved on the Nxeon side. */
  cloudflareToken?: string | null;
  acmeEmail?: string | null;
  report?: ReportFn;
};
export type MigrationTlsResult = { secured: string[]; pending: TlsPending[]; error?: string };

/**
 * Issue/refresh TLS for a completed migration — the step that must run AFTER DNS
 * is pointed, because HTTP-01 cannot validate a name that still resolves to the
 * old server.
 *
 * It is its own entry point precisely so the DNS-cutover flow can call it once
 * the hostname resolves to the target: `runRealMigration` persists what it
 * published to `<workdir>/sites.json`, and this re-reads (and re-validates)
 * that, walks the same fallback ladder, then rewrites and reloads the vhost.
 * Safe to call repeatedly — certbot's `--keep-until-expiring` makes it a no-op
 * once a certificate is in place.
 */
export async function issueMigrationCertificates(input: MigrationTlsInput): Promise<MigrationTlsResult> {
  const { target, migrationId } = input;
  if (!target) return { secured: [], pending: [], error: "target server row not found" };
  const work = migrationWorkDir(migrationId);
  const { conn, sftp } = await connectTarget(target);
  const say = async (line: string) => {
    if (input.report) await input.report(50, "Securing your site…", line);
  };
  try {
    const spec = await readSiteSpec(conn, work);
    if (!spec) return { secured: [], pending: [], error: "this migration did not publish a site configuration we can secure" };
    // Fold in hostnames the platform already knows, attached to the site whose
    // names they share a suffix with (else the first site).
    for (const raw of (input.extraDomains ?? []).slice(0, 20)) {
      const d = normalizeDomain(raw);
      if (!d || spec.sites.some((s) => s.names.includes(d))) continue;
      const holder = spec.sites.find((s) => s.names.some((n) => d.endsWith(`.${n}`) || n.endsWith(`.${d}`))) ?? spec.sites[0];
      if (holder && holder.names.length < 12) holder.names.push(d);
    }
    let targetIp = clean(target.dedicatedIp?.address ?? "", 64);
    if (!IPV4_RE.test(targetIp)) {
      targetIp = clean((await sh(conn, `hostname -I 2>/dev/null | awk '{print $1}'`)).stdout, 64);
      if (!IPV4_RE.test(targetIp)) targetIp = "";
    }
    const hostWebUp = await shOk(conn, `systemctl is-active nginx >/dev/null 2>&1 || systemctl is-active apache2 >/dev/null 2>&1`);
    return await secureSites({
      conn,
      sftp,
      work,
      spec,
      targetIp,
      email: clean(input.acmeEmail ?? "", 190),
      cloudflareToken: input.cloudflareToken,
      webOwnedByContainer: !hostWebUp,
      say,
    });
  } catch (e: any) {
    return { secured: [], pending: [], error: clean(e?.message ?? e, 300) };
  } finally {
    await sh(conn, `shred -u ${work}/cf-dns.ini 2>/dev/null || rm -f ${work}/cf-dns.ini`).catch(() => {});
    try {
      conn.end();
    } catch {
      /* best-effort */
    }
  }
}

