content.content:
// ---- 4c. STORAGE PRE-FLIGHT + attached-volume rescue -------------------
// The old arithmetic only counted the FILE COPY. A real run therefore passed
// pre-flight, filled a 25 GB disk to 92% and killed two of three compose
// projects with `no space left on device` — while a 20 GB volume sat attached
// to the same box with no filesystem on it, never mounted. Both halves of that
// are fixed here: Docker's real cost is budgeted, and an idle attached volume
// is put to work BEFORE anything is pulled, loaded or built.
const fileBytes = Math.max(0, Number(items.totalBytes ?? 0));
const dockerBytes = inv.imageBytes * IMAGE_OVERHEAD_FACTOR + inv.volumeBytes;
const requiredBytes = fileBytes + dockerBytes + FS_HEADROOM;
const rootAvail = await availBytes(conn, "/");
// On a RE-RUN (or a server provisioned with a data volume already in place)
// Docker's store is on its own filesystem, so its bytes must not be demanded
// from `/` a second time — otherwise a perfectly-sized server fails the
// pre-flight it passed the first time.
const dockerOnOwnFs = await shOk(
  conn,
  `[ -d /var/lib/docker ] && [ "$(df -P /var/lib/docker 2>/dev/null | tail -1 | awk '{print $1}')" != "$(df -P / 2>/dev/null | tail -1 | awk '{print $1}')" ]`
);
const rootNeeded = dockerOnOwnFs ? fileBytes + FS_HEADROOM : requiredBytes;
let extraDisk: BlockDev | null = null;
let useExtraDisk = false;

if (requiredBytes > 0) {
  await report(
    13,
    "Checking free space…",
    `Space needed: ${human(fileBytes)} of files + ${human(dockerBytes)} for Docker images/volumes ` +
      `(images unpack to roughly ${IMAGE_OVERHEAD_FACTOR}× their download size) + ${human(FS_HEADROOM)} working headroom = ${human(requiredBytes)}.`
  );
}
if (rootAvail !== null) {
  await report(13, "Checking free space…", `  The new server has ${human(rootAvail)} free on /.`);
  if (dockerOnOwnFs) {
    const dockerAvailNow = await availBytes(conn, "/var/lib/docker");
    await report(
      13,
      "Checking free space…",
      `  Docker already stores its data on a separate volume (${human(dockerAvailNow ?? 0)} free there), so only ${human(rootNeeded)} is needed on /.`
    );
  }
  const tight = rootNeeded > rootAvail || rootAvail - rootNeeded < FS_HEADROOM;
  if (tight && dockerBytes > 0) {
    extraDisk = await findUnusedDisk(conn);
    if (extraDisk) {
      const diskFits = extraDisk.sizeBytes >= dockerBytes + GiB;
      const rootFitsRest = fileBytes + FS_HEADROOM <= rootAvail;
      if (diskFits && rootFitsRest) {
        useExtraDisk = true;
        await report(
          14,
          "Checking free space…",
          `  An unused ${human(extraDisk.sizeBytes)} volume is attached as /dev/${extraDisk.name} — formatting it and moving Docker's storage onto it so the system disk stays free.`
        );
      } else {
        await report(
          14,
          "Checking free space…",
          `  An unused ${human(extraDisk.sizeBytes)} volume is attached but it is not large enough to cover this move on its own.`
        );
        extraDisk = null;
      }
    }
  }
  // Fail EARLY and clearly rather than dying mid-build with ENOSPC.
  if (rootNeeded > rootAvail && !useExtraDisk) {
    throw new Error(
      `Not enough free disk on the destination: this move needs about ${gb(rootNeeded)} ` +
        `(${gb(fileBytes)} of files, ${gb(dockerBytes)} for Docker images and volumes, ${gb(FS_HEADROOM)} of working headroom) ` +
        `but only ${gb(rootAvail)} is free. Attach a volume or resize the disk and retry.`
    );
  }
}

// ---- 5. Install prerequisites on the target (fixed allowlist) ---------

