// `*.sql` / `*.dump` are the critical ones: they are customer data, and rewriting
// an IP inside a dump is a silent corruption of the very thing we just migrated.
const SWEEP_EXCLUDE_GLOBS = [
  "*.sql", "*.dump", "*.bak", "*.gz", "*.zst", "*.bz2", "*.xz", "*.tar", "*.tgz", "*.zip",
  "*.7z", "*.rar", "*.log", "*.log.*", "*.png", "*.jpg", "*.jpeg", "*.gif", "*.webp",
  "*.svg", "*.ico", "*.pdf", "*.woff", "*.woff2", "*.ttf", "*.eot", "*.otf", "*.mp4",
  "*.mp3", "*.avi", "*.mov", "*.so", "*.so.*", "*.a", "*.o", "*.pyc", "*.class", "*.jar",
  "*.war", "*.bin", "*.exe", "*.dll", "*.db", "*.sqlite", "*.sqlite3", "*.pem", "*.key",
  "*.crt", "*.csr", "*.p12", "*.pfx", "*.lock", "*.map", "*.min.js", "*.min.css",
